(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("quintilian-institutes-1-b", [{"sp": "HDR", "t": "Institutio Oratoria (Libri I–III)"}, {"sp": "SEC", "t": "M. Fabius Quintilianus Tryphoni suo salutem", "st": "pr"}, {"sp": "N", "t": "Efflagitasti cotidiano convicio, ut libros, quos ad Marcellum meum de Institutione oratoria scripseram iam emittere inciperem. Nam ipse eos nondum opinabar satis maturuisse, quibus componendis, ut scis, paulo plus quam biennium tot alioqui negotiis districtus impendi; quod tempus non tam stilo quam inquisitioni instituti operis prope infiniti et legendis auctoribus, qui sunt innumerabiles, datum est.", "st": "pr.1"}, {"sp": "N", "t": "Usus deinde Horatii consilio, qui in arte poetica suadet, ne praecipitetur editio <em>nonumque prematur in annum,<\/em> dabam iis otium, ut, refrigerato inventionis amore, diligentius repetitos tanquam lector perpenderem.", "st": "pr.2"}, {"sp": "N", "t": "Sed si tanto opere efflagitantur quam tu adfirmas, permittamus vela ventis et oram solventibus bene precemur. Multum autem in tua quoque fide ac diligentia positum est, ut in manus hominum quam emendatissimi veniant.", "st": "pr.3"}, {"sp": "HDR", "t": "Liber I", "st": "1"}, {"sp": "N", "t": "Post impetratam studiis meis quietem, quae per viginti annos erudiendis iuvenibus impenderam, cum a me quidam familiariter postularent, ut aliquid de ratione dicendi componerem, diu sum equidem reluctatus, quod auctores utriusque linguae clarissimos non ignorabam multa, quae ad hoc opus pertinerent, diligentissime scripta posteris reliquisse.", "st": "1.pr.1"}, {"sp": "N", "t": "Sed qua ego ex causa faciliorem mihi veniam meae deprecationis arbitrabar fore, hac accendebantur illi magis, quod inter diversas opiniones priorum et quasdam etiam inter se contrarias difficilis esset electio; ut mihi si non inveniendi nova at certe iudicandi de veteribus iniungere laborem non iniuste viderentur.", "st": "1.pr.2"}, {"sp": "N", "t": "Quamvis autem non tam me vinceret praestandi, quod exigebatur, fiducia quam negandi verecundia, latius se tamen aperiente materia plus quam imponebatur oneris sponte suscepi, simul ut pleniore obsequio demererer amantissimos mei, simul ne vulgarem viam ingressus alienis demum vestigiis insisterem.", "st": "1.pr.3"}, {"sp": "N", "t": "Nam ceteri fere, qui artem orandi litteris tradiderunt, ita sunt exorsi, quasi perfectis omni alio genere doctrinae summam in eloquentia manum imponerent, sive contemnentes tanquam parva, quae prius discimus, studia, sive non ad suum pertinere officium opinati, quando divisae professionum vices essent, seu, quod proximum vero, nullam ingenii sperantes gratiam circa res etiamsi necessarias procul tamen ab ostentatione positas; ut operum fastigia spectantur, latent fundamenta.", "st": "1.pr.4"}, {"sp": "N", "t": "Ego, cum existimem nihil arti oratoriae alienum, sine quo fieri non posse oratorem fatendum est, nec ad ullius rei summam nisi praecedentibus initiis perveniri, ad minora illa, sed quae si negligas, non sit maioribus locus, demittere me non recusabo; nec aliter, quam si mihi tradatur educandus orator, studia eius formare ab infantia incipiam. Quod opus, Marcelle Victori, tibi dicamus;", "st": "1.pr.5"}, {"sp": "N", "t": "quem, cum amicissimum nobis tum eximio litterarum amore flagrantem, non propter haec modo (quamquam sint magna) dignissimum hoc mutuae inter nos caritatis pignore iudicabamus; sed quod erudiendo Getae tuo, cuius prima aetas manifestum iam ingenii lumen ostendit, non inutiles fore libri videbantur, quos ab ipsis dicendi velut incunabulis, per omnes, quae modo aliquid oratori futuro conferant, artis ad summam eius operis perducere destinabamus;", "st": "1.pr.6"}, {"sp": "N", "t": "atque eo magis, quod duo iam sub nomine meo libri ferebantur artis rhetoricae neque editi a me neque in hoc comparati. Namque alterum sermonem per biduum habitum pueri, quibus id praestabatur, exceperant; alterum pluribus sane diebus, quantum notando consequi potuerant, interceptum boni iuvenes, sed nimium amantes mei, temerario editionis honore vulgaverant.", "st": "1.pr.7"}, {"sp": "N", "t": "Quare in his quoque libris erunt eadem aliqua, multa mutata, plurima adiecta, omnia vero compositiora et, quantum nos poterimus, elaborata.", "st": "1.pr.8"}, {"sp": "N", "t": "Oratorem autem instituimus illum perfectum, qui esse nisi vir bonus non potest; ideoque non dicendi modo eximiam in eo facultatem sed omnes animi virtutes exigimus.", "st": "1.pr.9"}, {"sp": "N", "t": "Neque enim hoc concesserim, rationem rectae honestaeque vitae (ut quidam putaverunt) ad philosophos relegandam, cum vir ille vere civilis et publicarum privatarumque rerum administrationi accommodatus, qui regere consiliis urbes, fundare legibus, emendare iudiciis possit, non alius sit profecto quam orator.", "st": "1.pr.10"}, {"sp": "N", "t": "Quare, tametsi me fateor usurum quibusdam, quae philosophorum libris continentur, tamen ea iure vereque contenderim esse operis nostri proprieque ad artem oratoriam pertinere.", "st": "1.pr.11"}, {"sp": "N", "t": "An, si frequentissime de iustitia, fortitudine, temperantia ceterisque similibus disserendum est, adeo ut vix ulla possit causa reperiri in quam non aliqua ex his incidat quaestio, eaque omnia inventione atque elocutione sunt explicanda, dubitabitur, ubicunque vis ingenii et copia dicendi postulatur, ibi partes oratoris esse praecipuas?", "st": "1.pr.12"}, {"sp": "N", "t": "Fueruntque haec, ut Cicero apertissime colligit, quemadmodum iuncta natura sic officio quoque copulata, ut iidem sapientes atque eloquentes haberentur. Scidit deinde se studium, atque inertia factum est, ut artes esse plures viderentur. Nam ut primum lingua esse coepit in quaestu institutumque eloquentiae bonis male uti, curam morum, qui diserti habebantur, reliquerunt.", "st": "1.pr.13"}, {"sp": "N", "t": "Ea vero destituta infirmioribus ingeniis velut praedae fuit. Inde quidam, contempto bene dicendi labore, ad formandos animos statuendasque vitae leges regressi partem quidem potiorem, si dividi posset, retinuerunt; nomen tamen sibi insolentissimum arrogaverunt, ut soli studiosi sapientiae vocarentur, quod neque summi imperatores neque in consiliis rerum maximarum ac totius administratione rei publicae clarissime versati sibi unquam vindicare sunt ausi. Facere enim optima quam promittere maluerunt.", "st": "1.pr.14"}, {"sp": "N", "t": "Ac veterum quidem sapientiae professorum multos et honesta praecepisse et, ut praeceperint, etiam vixisse, facile concesserim; nostris vero temporibus sub hoc nomine maxima in plerisque vitia latuerunt. Non enim virtute ac studiis, ut haberentur philosophi, laborabant, sed vultum et tristitiam et dissentientem a ceteris habitum pessimis moribus praetendebant.", "st": "1.pr.15"}, {"sp": "N", "t": "Haec autem, quae velut propria philosophiae asseruntur, passim tractamus omnes. Quis enim non de iusto, aequo ac bono, modo non et vir pessimus, loquitur? quis non etiam rusticorum aliqua de causis naturalibus quaerit? nam verborum proprietas ac differentia omnibus, qui sermonem curae habent, debet esse communis.", "st": "1.pr.16"}, {"sp": "N", "t": "Sed ea et sciet optime et eloquetur orator; qui si fuisset aliquando perfectus, non a philosophorum scholis virtutis praecepta peterentur. Nunc necesse est ad eos aliquando auctores recurrere, qui desertam, ut dixi, partem oratoriae artis, meliorem praesertim, occupaverunt, et velut nostrum reposcere; non ut nos illorum utamur inventis, sed ut illos alienis usos esse doceamus.", "st": "1.pr.17"}, {"sp": "N", "t": "Sit igitur orator vir talis, qualis vere sapiens appellari possit; nec moribus modo perfectus (nam id mea quidem opinione, quanquam sunt qui dissentiant, satis non est) sed etiam scientia et omni facultate dicendi, qualis fortasse nemo adhuc fuerit;", "st": "1.pr.18"}, {"sp": "N", "t": "sed non ideo minus nobis ad summa tendendum est; quod fecerunt plerique veterum, qui, etsi nondum quemquam sapientem repertum putabant, praecepta tamen sapientiae tradiderant.", "st": "1.pr.19"}, {"sp": "N", "t": "Nam est certe aliquid consummata eloquentia, neque ad eam pervenire natura humani ingenii prohibet. Quod si non contingat, altius tamen ibunt, qui ad summa nitentur, quam qui, praesumpta desperatione quo velint evadendi, protinus circa ima substiterint.", "st": "1.pr.20"}, {"sp": "N", "t": "Quo magis impetranda erit venia, si ne minora quidem illa, verum operi, quod instituimus, necessaria praeteribo. Nam liber primus ea, quae sunt ante officium rhetoris, continebit. Secundo prima apud rhetorem elementa et quae de ipsa rhetorices substantia quaeruntur tractabimus.", "st": "1.pr.21"}, {"sp": "N", "t": "Quinque deinceps inventioni (nam huic et dispositio subiungitur), quattuor elocutioni, in cuius partem memoria ac pronuntiatio veniunt, dabuntur. Unus accedet, in quo nobis orator ipse informandus est, ubi, qui mores eius, quae in suscipiendis, discendis, agendis causis ratio, quod eloquentiae genus, quis agendi debeat esse finis, quae post fine studia, quantum nostra valebit infirmitas, disseremus.", "st": "1.pr.22"}, {"sp": "N", "t": "His omnibus admiscebitur, ut quisque locus postulabit, docendi ratio, quae non eorum modo scientia, quibus solis quidam nomen artis dederunt, studiosos instruat et (ut sic dixerim) ius ipsum rhetorices interpretetur, sed alere facundiam, vires augere eloquentiae possit.", "st": "1.pr.23"}, {"sp": "N", "t": "Nam plerumque nudae illae artes nimia subtilitatis adfectatione frangunt atque concidunt quidquid est in oratione generosius, et omnem sucum ingenii bibunt et ossa detegunt: quae ut esse et adstringi nervis suis debent, sic corpore operienda sunt.", "st": "1.pr.24"}, {"sp": "N", "t": "Ideoque nos non particulam illam, sicut plerique, sed quidquid utile ad instituendum oratorem putabamus, in hos duodecim libros contulimus breviter omnia demonstraturi. Nam si quantum de quaque re dici potest persequamur, finis operis non reperietur.", "st": "1.pr.25"}, {"sp": "N", "t": "Illud tamen in primis testandum est, nihil praecepta atque artes valere nisi adiuvante natura. Quapropter ei, cui deerit ingenium, non magis haec scripta sint quam de agrorum cultu sterilibus terris.", "st": "1.pr.26"}, {"sp": "N", "t": "Sunt et alia ingenita cuique adiumenta, vox, latus patiens laboris, valetudo, constantia, decor; quae si modica obtigerunt, possunt ratione ampliari, sed nonnunquam ita desunt, ut bona etiam ingenii studiique corrumpant; sicut et haec ipsa sine doctore perito, studio pertinaci, scribendi, legendi, dicendi multa et continua exercitatione per se nihil prosunt.", "st": "1.pr.27"}, {"sp": "N", "t": "Igitur nato filio pater spem de illo primum quam optimam capiat, ita diligentior a principiis fiet. Falsa enim est querela, paucissimis hominibus vim percipiendi, quae tradantur, esse concessam, plerosque vero laborem ac tempora tarditate ingenii perdere. Nam contra plures reperias et faciles in excogitando et ad discendum promptos. Quippe id est homini naturale; ac sicut aves ad volatum, equi ad cursum, ad saevitiam ferae gignuntur; ita nobis propria est mentis agitatio atque sollertia, unde origo animi caelestis creditur.", "st": "1.1.1"}, {"sp": "N", "t": "Hebetes vero et indociles non magis secundum naturam homines eduntur quam prodigiosa corpora et monstris insignia, sed hi pauci admodum fuerunt. Argumentum quod in pueris elucet spes plurimorum, quae cum emoritur aetate, manifestum est, non naturam defecisse sed curam. Praestat tamen ingenio alius alium.", "st": "1.1.2"}, {"sp": "N", "t": "Concedo; sed plus efficiet aut minus; nemo reperitur, qui sit studio nihil consecutus. Hoc qui perviderit, protinus ut erit parens factus, acrem quam maxime curam spei futuri oratoris impendat.", "st": "1.1.3"}, {"sp": "N", "t": "Ante omnia ne sit vitiosus sermo nutricibus, quas si fieri posset sapientes Chrysippus optavit, certe quantum res pateretur optimas eligi voluit. Et morum quidem in his haud dubie prior ratio est, recte tamen etiam loquantur.", "st": "1.1.4"}, {"sp": "N", "t": "Has primum audiet puer, harum verba effingere imitando conabitur. Et natura tenacissimi sumus eorum, quae rudibus animis percepimus; ut sapor, quo nova imbuas, durat, nec lanarum colores, quibus simplex ille candor mutatus est, elui possunt. Et haec ipsa magis pertinaciter haerent, quo deteriora sunt. Nam bona facile mutantur in peius; num quando in bonum verteris vitia? Non assuescat ergo, ne dum infans quidem est, sermoni qui dediscendus sit.", "st": "1.1.5"}, {"sp": "N", "t": "In parentibus vero quam plurimum esse eruditionis optaverim, nec de patribus tantum loquor. Nam Gracchorum eloquentiae multum contulisse accepimus Corneliam matrem, cuius doctissimus sermo in posteros quoque est epistolis traditus: et Laelia C. filia reddidisse in loquendo paternam elegantiam dicitur, et Hortensiae Q. filiae oratio apud Triumviros habita legitur non tantum in sexus honorem.", "st": "1.1.6"}, {"sp": "N", "t": "Nec tamen ii, quibus discere ipsis non contigit, minorem curam docendi liberos habeant; sed sint propter hoc ipsum ad cetera magis diligentes.", "st": "1.1.7"}, {"sp": "N", "t": "De pueris, inter quos educabitur ille huic spei destinatus, idem quod de nutricibus dictum sit. De paedagogis hoc amplius, ut aut sint eruditi plene, quam primam esse curam velim, aut se non esse eruditos sciant. Nihil est peius iis, qui paulum aliquid ultra primas litteras progressi falsam sibi scientiae persuasionem induerunt. Nam et cedere praecipiendi partibus indignantur et velut iure quodam potestatis, quo fere hoc hominum genus intumescit, imperiosi atque interim saevientes stultitiam suam perdocent.", "st": "1.1.8"}, {"sp": "N", "t": "Nec minus error eorum nocet moribus; siquidem Leonides Alexandri paedagogus, ut a Babylonio Diogene traditur, quibusdam eum vitiis imbuit, quae robustum quoque et iam maximum regem ab illa institutione puerili sunt persecuta.", "st": "1.1.9"}, {"sp": "N", "t": "Si cui multa videor exigere, cogitet oratorem institui, rem arduam, etiam cum ei formando nihil defuerit; praeterea plura ac difficiliora superesse. Nam et studio perpetuo et praestantissimis praeceptoribus et plurimis disciplinis opus est.", "st": "1.1.10"}, {"sp": "N", "t": "Quapropter praecipienda sunt optima; quae si quis gravabitur, non rationi defuerint sed homini. Si tamen non continget, quales maxime velim nutrices, pueros, paedagogos habere, at unus certe sit assiduus loquendi non imperitus, qui, si qua erunt ab his praesente alumno dicta vitiose, corrigat protinus nec insidere illi sinat; dum tamen intelligatur, id, quod prius dixi, bonum esse, hoc remedium.", "st": "1.1.11"}, {"sp": "N", "t": "A sermone Graeco puerum incipere malo, quia Latinum, qui pluribus in usu est, vel nobis nolentibus perbibet, simul quia disciplinis quoque Graecis prius instituendus est, unde et nostrae fluxerunt.", "st": "1.1.12"}, {"sp": "N", "t": "Non tamen hoc adeo superstitiose fieri velim, ut diu tantum Graece loquatur aut discat, sicut plerisque moris est. Hoc enim accidunt et oris plurima vitia in peregrinum sonum corrupti et sermonis; cui cum Graecae figurae assidua consuetudine haeserunt, in diversa quoque loquendi ratione pertinacissime durant.", "st": "1.1.13"}, {"sp": "N", "t": "Non longe itaque Latina subsequi debent et cito pariter ire. Ita fiet, ut, cum aequali cura linguam utramque tueri coeperimus, neutra alteri officiat.", "st": "1.1.14"}, {"sp": "N", "t": "Quidam litteris instituendos, qui minores septem annis essent, non putaverunt, quod illa primum aetas et intellectum disciplinarum capere et laborem pati posset. In qua sententia Hesiodum esse plurimi tradunt qui ante grammaticum Aristophanen fuerunt; nam is primus ὑποθήκας, in quo libro scriptum hoc invenitur, negavit esse huius poëtae.", "st": "1.1.15"}, {"sp": "N", "t": "Sed alii quoque auctores, inter quos Eratosthenes, idem praeceperunt. Melius autem, qui nullum tempus vacare cura volunt, ut Chrysippus. Nam is, quamvis nutricibus triennium dederit, tamen ab illis quoque iam formandam quam optimis institutis mentem infantium iudicat.", "st": "1.1.16"}, {"sp": "N", "t": "Cur autem non pertineat ad litteras aetas, quae ad mores iam pertinet? Neque ignoro, toto illo, de quo loquor, tempore vix tantum effici, quantum conferre unus postea possit annus; sed tamen mihi, qui dissenserunt, videntur non tam discentibus in hac parte quam docentibus pepercisse.", "st": "1.1.17"}, {"sp": "N", "t": "Quid melius alioqui facient, ex quo loqui poterunt? Faciant enim aliquid necesse est. Aut cur hoc, quantulumcunque est, usque ad septem annos lucrum fastidiamus? Nam certe quamlibet parvum sit, quod contulerit aetas prior, maiora tamen aliqua discet puer ipso illo anno, quo minora didicisset.", "st": "1.1.18"}, {"sp": "N", "t": "Hoc per singulos prorogatum in summam proficit, et quantum in infantia praesumptum est temporis, adolescentiae adquiritur. Idem etiam de sequentibus annis praeceptum sit, ne, quod cuique discendum est, sero discere incipiat. Non ergo perdamus primum statim tempus, atque eo minus, quod initia litterarum sola memoria constant, quae non modo iam est in parvis sed tum etiam tenacissima est.", "st": "1.1.19"}, {"sp": "N", "t": "Nec sum adeo aetatum imprudens, ut instandum protinus teneris acerbe putem exigendamque plane operam. Nam id in primis cavere oportebit, ne studia, qui amare nondum potest, oderit et amaritudinem semel perceptam etiam ultra rudes annos reformidet. Lusus hic sit; et rogetur et laudetur et numquam non fecisse se gaudeat, aliquando ipso nolente doceatur alius, cui invideat; contendat interim et saepius vincere se putet; praemiis etiam, quae capit illa aetas, evocetur.", "st": "1.1.20"}, {"sp": "N", "t": "Parva docemus oratorem instituendum professi, sed est sua etiam studiis infantia; et ut corporum mox fortissimorum educatio a lacte cunisque initium ducit, ita futurus eloquentissimus edidit aliquando vagitum et loqui primum incerta voce temptavit et haesit circa formas litterarum. Nec si quid discere satis non est, ideo nec necesse est.", "st": "1.1.21"}, {"sp": "N", "t": "Quodsi nemo reprehendit patrem, qui haec non negligenda in suo filio putet, cur improbetur, si quis ea, quae domi suae recte faceret, in publicum promit? Atque eo magis, quod minora etiam facilius minores percipiunt, et ut corpora ad quosdam membrorum flexus formari nisi tenera non possunt, sic animos quoque ad pleraque duriores robur ipsum facit.", "st": "1.1.22"}, {"sp": "N", "t": "An Philippus Macedonum rex Alexandro filio suo prima litterarum elementa tradi ab Aristotele, summo eius aetatis philosopho, voluisset, aut ille suscepisset hoc officium, si non studiorum initia et a perfectissimo quoque optime tractari et pertinere ad summam credidisset?", "st": "1.1.23"}, {"sp": "N", "t": "Fingamus igitur Alexandrum dari nobis impositum gremio, dignum tanta cura infantem (quanquam suus cuique dignus est): pudeatne me in ipsis statim elementis etiam brevia docendi monstrare compendia? Neque enim mihi illud saltem placet, quod fieri in plurimis video, ut litterarum nomina et contextum prius quam formas parvuli discant.", "st": "1.1.24"}, {"sp": "N", "t": "Obstat hoc agnitioni earum non intendentibus mox animum ad ipsos ductus, dum antecedentem memoriam sequuntur. Quae causa est praecipientibus, ut etiam, cum satis adfixisse eas pueris recto illo quo primum scribi solent contextu videntur, retro agant rursus et varia permutatione turbent, donec litteras qui instituuntur facie norint non ordine. Quapropter optime sicut hominum pariter et habitus et nomina edocebuntur.", "st": "1.1.25"}, {"sp": "N", "t": "Sed quod in litteris obest, in syllabis non nocebit. Non excludo autem, id quod est inventum irritandae ad discendum infantiae gratia eburneas etiam litterarum formas in lusum offerre; vel si quid aliud, quo magis illa aetas gaudeat, inveniri potest, quod tractare, intueri, nominare iucundum sit.", "st": "1.1.26"}, {"sp": "N", "t": "Cum vero iam ductus sequi coeperit, non inutile erit eas tabellae quam optime insculpi, ut per illos velut sulcos ducatur stilus. Nam neque errabit, quemadmodum in ceris (continebitur enim utrinque marginibus neque extra praescriptum egredi poterit) et celerius ac saepius sequendo certa vestigia firmabit articulos, neque egebit adiutorio manum suam manu superimposita regentis.", "st": "1.1.27"}, {"sp": "N", "t": "Non est aliena res, quae fere ab honestis negligi solet, cura bene ac velociter scribendi. Nam cum sit in studiis praecipuum, quoque solo verus ille profectus et altis radicibus nixus paretur, scribere ipsum, tardior stilus cogitationem moratur, rudis et confusus intellectu caret; unde sequitur alter dictandi, quae transferenda sunt, labor.", "st": "1.1.28"}, {"sp": "N", "t": "Quare cum semper et ubique tum praecipue in epistolis secretis et familiaribus delectabit ne hoc quidem neglectum reliquisse.", "st": "1.1.29"}, {"sp": "N", "t": "Syllabis nullum compendium est; perdiscendae omnes nec, ut fit plerumque, difficillima quaeque earum differenda, ut in nominibus scribendis deprehendantur.", "st": "1.1.30"}, {"sp": "N", "t": "Quin immo ne primae quidem memoriae temere credendum; repetere et diu inculcare fuerit utilius, et in lectione quoque non properare ad continuandam eam vel accelerandam, nisi cum inoffensa atque indubitata litterarum inter se coniunctio suppeditare sine ulla cogitandi saltem mora poterit. Tunc ipsis syllabis verba complecti et his sermonem connectere incipiat.", "st": "1.1.31"}, {"sp": "N", "t": "Incredibile est, quantum morae lectioni festinatione adiiciatur. Hinc enim accidit dubitatio, intermissio, repetitio plus quam possunt audentibus, deinde, cum errarunt, etiam iis quae iam sciunt diffidentibus.", "st": "1.1.32"}, {"sp": "N", "t": "Certa sit ergo in primis lectio, deinde coniuncta et diu lentior, donec exercitatione contingat emendata velocitas.", "st": "1.1.33"}, {"sp": "N", "t": "Nam prospicere in dextrum (quod omnes praecipiunt) et providere, non rationis modo sed usus quoque est; quoniam sequentia intuenti priora dicenda sunt, et, quod difficillimum est, dividenda intentio animi, ut aliud voce aliud oculis agatur. Illud non paenitebit curasse, cum scribere nomina puer (quemadmodum moris est) coeperit, ne hanc operam in vocabulis vulgaribus et forte occurrentibus perdat.", "st": "1.1.34"}, {"sp": "N", "t": "Protinus enim potest interpretationem linguae secretioris, quas Graeci γλώσσας vocant, dum aliud agitur, ediscere et inter prima elementa consequi rem postea proprium tempus desideraturam. Et quoniam circa res adhuc tenues moramur, ii quoque versus, qui ad imitationem scribendi proponentur, non otiosas velim sententias habeant sed honestum aliquid monentes.", "st": "1.1.35"}, {"sp": "N", "t": "Prosequitur haec memoria in senectutem et impressa animo rudi usque ad mores proficiet. Etiam dicta clarorum virorum et electos ex poëtis maxime (namque eorum cognitio parvis gratior est) locos ediscere inter lusum licet. Nam et maxime necessaria est oratori (sicut suo loco dicam) memoria, et ea praecipue firmatur atque alitur exercitatione, et in his, de quibus nunc loquimur, aetatibus, quae nihildum ipsae generare ex se queunt, prope sola est, quae iuvari cura docentium possit.", "st": "1.1.36"}, {"sp": "N", "t": "Non alienum fuerit exigere ab his aetatibus, quo sit absolutius os et expressior sermo, ut nomina quaedam versusque adfectatae difficultatis ex pluribus et asperrime coeuntibus inter se syllabis catenatos et velut confragosos quam citatissime volvant; χαλινοί Graece vocantur. Res modica dictu, qua tamen omissa multa linguae vitia, nisi primis eximuntur annis, inemendabili in posterum pravitate durantur.", "st": "1.1.37"}, {"sp": "N", "t": "Sed nobis iam paulatim adcrescere puer et exire de gremio et discere serio incipiat. Hoc igitur potissimum loco tractanda quaestio est, utiliusne sit domi atque intra privatos parietes studentem continere an frequentiae scholarum et velut publicis praeceptoribus tradere.", "st": "1.2.1"}, {"sp": "N", "t": "Quod quidem cum iis, a quibus clarissimarum civitatium mores sunt instituti, tum eminentissimis auctoribus video placuisse. Non est tamen dissimulandum, esse nonnullos, qui ab hoc prope publico more privata quadam persuasione dissentiant. Hi duas praecipue rationes sequi videntur: unam, quod moribus magis consulant fugiendo turbam hominum eius aetatis, quae sit ad vitia maxime prona, unde causas turpium factorum saepe extitisse utinam falso iactaretur; alteram, quod, quisquis futurus est ille praeceptor, liberalius tempora sua impensurus uni videtur, quam si eadem in plures partiatur.", "st": "1.2.2"}, {"sp": "N", "t": "Prior causa prorsus gravis. Nam si studiis quidem scholas prodesse, moribus autem nocere constaret, potior mihi ratio vivendi honeste quam vel optime dicendi videretur. Sed mea quidem sententia iuncta ista atque indiscreta sunt. Neque enim esse oratorem nisi bonum virum iudico, et fieri etiamsi potest nolo. De hac re igitur prius.", "st": "1.2.3"}, {"sp": "N", "t": "Corrumpi mores in scholis putant; nam et corrumpuntur interim, sed domi quoque, et sunt multa eius rei exempla tam hercule quam conservatae sanctissime utrobique opinionis. Natura cuiusque totum curaque distat. Da mentem ad peiora facilem, da negligentiam formandi custodiendique in aetate prima pudoris: non minorem flagitiis occasionem secreta praebuerint. Nam et potest turpis esse domesticus ille praeceptor, nec tutior inter servos malos quam ingenuos parum modestos conversatio est.", "st": "1.2.4"}, {"sp": "N", "t": "At si bona ipsius indoles, si non caeca ac sopita parentum socordia est, et praeceptorem eligere sanctissimum quemque (cuius rei praecipua prudentibus cura est) et disciplinam, quae maxime severa fuerit, licet, et nihilominus amicum gravem virum aut fidelem libertum lateri filii sui adiungere, cuius assiduus comitatus etiam illos meliores faciat, qui timebantur.", "st": "1.2.5"}, {"sp": "N", "t": "Facile erat huius metus remedium. Utinam liberorum nostrorum mores non ipsi perderemus. Infantiam statim deliciis solvimus. Mollis illa educatio, quam indulgentiam vocamus, nervos omnes mentis et corporis frangit. Quid non adultus concupiscet, qui in purpuris repit? Nondum prima verba exprimit, iam coccum intelligit, iam conchylium poscit. Ante palatum eorum quam os instituimus.", "st": "1.2.6"}, {"sp": "N", "t": "In lecticis crescunt; si terram attigerint, e manibus utrinque sustinentium pendent. Gaudemus, si quid licentius dixerint: verba ne Alexandrinis quidem permittenda deliciis risu et osculo excipimus. Nec mirum: nos docuimus, ex nobis audiunt.", "st": "1.2.7"}, {"sp": "N", "t": "Nostras amicas, nostros concubinos vident, omne convivium obscenis canticis strepit, pudenda dictu spectantur. Fit ex his consuetudo, inde natura. Discunt haec miseri, antequam sciant vitia esse; inde soluti ac fluentes non accipiunt ex scholis mala ista sed in scholas adferunt.", "st": "1.2.8"}, {"sp": "N", "t": "Verum in studiis magis vacabit unus uni. Ante omnia nihil prohibet esse illum nescio quem unum etiam cum eo, qui in scholis eruditur. Sed etiamsi iungi utrumque non posset, lumen tamen illud conventus honestissimi tenebris ac solitudini praetulissem. Nam optimus quisque praeceptor frequentia gaudet ac maiore se theatro dignum putat.", "st": "1.2.9"}, {"sp": "N", "t": "At fere minores ex conscientia suae infirmitatis haerere singulis et officio fungi quodam modo paedagogorum non indignantur.", "st": "1.2.10"}, {"sp": "N", "t": "Sed praestat alicui vel gratia vel pecunia vel amicitia, ut doctissimum atque incomparabilem magistrum domi habeat: num tamen ille totum in uno diem consumpturus est? aut potest esse ulla tam perpetua discentis intentio, quae non ut visus oculorum obtutu continuo fatigetur? cum praesertim multo plus secreti temporis studia desiderent.", "st": "1.2.11"}, {"sp": "N", "t": "Neque enim scribenti, ediscenti, cogitanti praeceptor adsistit, quorum aliquid agentibus cuiuscunque interventus impedimento est. Lectio quoque non omnis nec semper praeeunte vel interpretante eget. Quando enim tot auctorum notitia contingeret? Modicum ergo tempus est, quo in totum diem velut opus ordinetur ideoque per plures ire possunt etiam quae singuli tradenda sunt.", "st": "1.2.12"}, {"sp": "N", "t": "Pleraque vero hanc condicionem habent, ut eadem voce ad omnes simul perferantur Taceo de partitionibus et declamationibus rhetorum quibus certe quantuscunque numerus adhibeatur, tamen unusquisque totum feret.", "st": "1.2.13"}, {"sp": "N", "t": "Non enim vox illa praeceptoris ut cena minus pluribus sufficit, sed ut sol universis idem lucis calorisque largitur. Grammaticus quoque si de loquendi ratione disserat, si quaestiones explicet, historias exponat, poemata enarret, tot illa discent quot audient.", "st": "1.2.14"}, {"sp": "N", "t": "At enim emendationi praelectionique numerus obstat. Sit incommodum, (nam quid fere undique placet?) mox illud comparabimus commodis. Nec ego tamen eo mitti puerum volo, ubi negligatur. Sed neque praeceptor bonus maiore se turba, quam ut sustinere eam possit, oneraverit; et in primis ea habenda cura est, ut is omni modo fiat nobis familiariter amicus, nec officium in docendo spectet sed adfectum.", "st": "1.2.15"}, {"sp": "N", "t": "Ita nunquam erimus in turba. Nec sane quisquam litteris saltem leviter imbutus eum, in quo studium ingeniumque perspexerit, non in suam quoque gloriam peculiariter fovebit. Et ut fugiendae sint magnae scholae (cui ne ipsi quidem rei adsentior, si ad aliquem merito concurritur), non tamen hoc eo valet, ut fugiendae sint omnino scholae. Aliud est enim vitare eas, aliud eligere.", "st": "1.2.16"}, {"sp": "N", "t": "Et si refutavimus quae contra dicuntur, iam explicemus, quid ipsi sequamur.", "st": "1.2.17"}, {"sp": "N", "t": "Ante omnia futurus orator, cui in maxima celebritate et in media rei publicae luce vivendum est, adsuescat iam a tenero non reformidare homines neque illa solitaria et velut umbratica vita pallescere. Excitanda mens et adtollenda semper est, quae in eiusmodi secretis aut languescit et quendam velut in opaco situm ducit, aut contra tumescit inani persuasione; necesse est enim nimium tribuat sibi, qui se nemini comparat.", "st": "1.2.18"}, {"sp": "N", "t": "Deinde cum proferenda sunt studia, caligat in sole et omnia nova offendit, ut qui solus didicerit quod inter multos faciendum est.", "st": "1.2.19"}, {"sp": "N", "t": "Mitto amicitias, quae ad senectutem usque firmissime durant religiosa quadam necessitudine imbutae. Neque enim est sanctius sacris iisdem quam studiis initiari. Sensum ipsum, qui communis dicitur, ubi discet, cum se a congressu, qui non hominibus solum sed mutis quoque animalibus naturalis est, segregarit?", "st": "1.2.20"}, {"sp": "N", "t": "Adde quod domi ea sola discere potest, quae ipsi praecipientur, in schola etiam quae aliis. Audiet multa cotidie probari, multa corrigi; proderit alicuius obiurgata desidia, proderit laudata industria, excitabitur laude aemulatio,", "st": "1.2.21"}, {"sp": "N", "t": "turpe ducet cedere pari, pulchrum superasse maiores. Accendunt omnia haec animos, et licet ipsa vitium sit ambitio, frequenter tamen causa virtutum est.", "st": "1.2.22"}, {"sp": "N", "t": "Non inutilem scio servatum esse a praeceptoribus meis morem, qui, cum pueros in classes distribuerant, ordinem dicendi secundum vires ingenii dabant; et ita superiore loco quisque declamabat, ut praecedere profectu videbatur.", "st": "1.2.23"}, {"sp": "N", "t": "Huius rei iudicia praebebantur; ea nobis ingens palma, ducere vero classem multo pulcherrimum. Nec de hoc semel decretum erat; tricesimus dies reddebat victo certaminis potestatem. Ita nec superior successu curam remittebat et dolor victum ad depellendam ignominiam concitabat.", "st": "1.2.24"}, {"sp": "N", "t": "Id nobis acriores ad studia dicendi faces subdidisse quam exhortationem docentium, paedagogorum custodiam, vota parentum, quantum animi mei coniectura colligere possum, contenderim.", "st": "1.2.25"}, {"sp": "N", "t": "Sed sicut firmiores in litteris profectus alit aemulatio, ita incipientibus atque adhuc teneris condiscipulorum quam praeceptoris iucundior hoc ipso quod facilior imitatio est. Vix enim se prima elementa ad spem tollere effingendae, quam summam putant, eloquentiae audebunt; proxima amplectentur magis, ut vites arboribus applicitae inferiores prius apprehendendo ramos in cacumina evadunt.", "st": "1.2.26"}, {"sp": "N", "t": "Quod adeo verum est, ut ipsius etiam magistri, si tamen ambitiosis utilia praeferet, hoc opus sit, cum adhuc rudia tractabit ingenia, non statim onerare infirmitatem discentium, sed temperare vires suas et ad intellectum audientis descendere.", "st": "1.2.27"}, {"sp": "N", "t": "Nam ut vascula oris angusti superfusam humoris copiam respuunt, sensim autem influentibus vel etiam instillatis complentur, sic animi puerorum quantum excipere possint videndum est. Nam maiora intellectu velut parum apertos ad percipiendum animos non subibunt.", "st": "1.2.28"}, {"sp": "N", "t": "Utile igitur habere, quos imitari primum, mox vincere velis. Ita paulatim et superiorum spes erit. His adiicio, praeceptores ipsos non idem mentis ac spiritus in dicendo posse concipere singulis tantum praesentibus quod illa celebritate audientium instinctos.", "st": "1.2.29"}, {"sp": "N", "t": "Maxima enim pars eloquentiae constat animo. Hunc adfici, hunc concipere imagines rerum et transformari quodammodo ad naturam eorum, de quibus loquimur, necesse est. Is porro, quo generosior celsiorque est, hoc maioribus velut organis commovetur; ideoque et laude crescit et impetu augetur et aliquid magnum agere gaudet.", "st": "1.2.30"}, {"sp": "N", "t": "Est quaedam tacita dedignatio, vim dicendi tantis comparatam laboribus ad unum auditorem demittere: pudet supra modum sermonis attolli. Et sane concipiat quis mente vel declamantis habitum vel orantis vocem, incessum, pronuntiationem, illum denique animi et corporis motum, sudorem, ut alia praeteream, et fatigationem, audiente uno: nonne quiddam pati furori simile videatur? Non esset in rebus humanis eloquentia, si tantum cum singulis loqueremur.", "st": "1.2.31"}, {"sp": "N", "t": "Tradito sibi puero docendi peritus ingenium eius in primis naturamque perspiciet. Ingenii signum in parvis praecipuum memoria est. Eius duplex virtus, facile percipere et fideliter continere. Proximum imitatio; nam id quoque est docilis naturae, sic tamen, ut ea quae discit effingat, non habitum forte et ingressum et si quid in peius notabile est.", "st": "1.3.1"}, {"sp": "N", "t": "Non dabit mihi spem bonae indolis, qui hoc imitandi studio petet, ut rideatur. Nam probus quoque in primis erit ille vere ingeniosus; alioqui non peius duxerim tardi esse ingenii quam mali. Probus autem ab illo segni et iacente plurimum aberit.", "st": "1.3.2"}, {"sp": "N", "t": "Hic meus quae tradentur non difficulter accipiet, quaedam etiam interrogabit, sequetur tamen magis quam praecurret. Illud ingeniorum velut praecox genus non temere unquam pervenit ad frugem.", "st": "1.3.3"}, {"sp": "N", "t": "Hi sunt, qui parva facile faciunt et audacia provecti, quidquid illud possunt, statim ostendunt. Possunt autem id demum, quod in proximo est; verba continuant, haec vultu interrito, nulla tardati verecundia proferunt. Non multum praestant sed cito.", "st": "1.3.4"}, {"sp": "N", "t": "Non subest vera vis nec penitus immissis radicibus nititur; ut, quae summo solo sparsa sunt semina, celerius se effundunt, et imitatae spicas herbulae inanibus aristis ante messem flavescunt. Placent haec annis comparata; deinde stat profectus, admiratio decrescit.", "st": "1.3.5"}, {"sp": "N", "t": "Haec cum animadverterit, perspiciat deinceps, quonam modo tractandus sit discentis animus. Sunt quidam, nisi institeris, remissi, quidam imperia indignantur. quosdam continet metus, quosdam debilitat, alios continuatio extundit, in aliis plus impetus facit.", "st": "1.3.6"}, {"sp": "N", "t": "Mihi ille detur puer, quem laus excitet, quem gloria iuvet, qui victus fleat. Hic erit alendus ambitu, hunc mordebit obiurgatio, hunc honor excitabit, in hoc desidiam nunquam verebor.", "st": "1.3.7"}, {"sp": "N", "t": "Danda est tamen omnibus aliqua remissio; non solum quia nulla res est, quae perferre possit continuum laborem, atque ea quoque, quae sensu et anima carent, ut servare vim suam possint, velut quiete alterna retenduntur; sed quod studium discendi voluntate, quae cogi non potest, constat.", "st": "1.3.8"}, {"sp": "N", "t": "Itaque et virium plus adferunt ad discendum renovati ac recentes et acriorem animum, qui fere necessitatibus repugnat.", "st": "1.3.9"}, {"sp": "N", "t": "Nec me offenderit lusus in pueris; est et hoc signum alacritatis; neque illum tristem semperque demissum sperare possim erectae circa studia mentis fore, cum in hoc quoque maxime naturali aetatibus illis impetu iaceat.", "st": "1.3.10"}, {"sp": "N", "t": "Modus tamen sit remissionibus, ne aut odium studiorum faciant negatae aut otii consuetudinem nimiae. Sunt etiam nonnulli acuendis puerorum ingeniis non inutiles lusus, cum positis invicem cuiusque generis quaestiunculis aemulantur.", "st": "1.3.11"}, {"sp": "N", "t": "Mores quoque se inter ludendum simplicius detegunt; modo nulla videatur aetas tam infirma, quae non protinus quid rectum pravumque sit discat, tum vel maxime formanda, cum simulandi nescia est et praecipientibus facillime cedit. Frangas enim citius quam corrigas, quae in pravum induruerunt.", "st": "1.3.12"}, {"sp": "N", "t": "Protinus ergo, ne quid cupide, ne quid improbe, ne quid impotenter faciat, monendus est puer; habendumque in animo semper illud Vergilianum:<br>Adeo in teneris consuescere multum est.<br>Caedi vero discentes, quamlibet et receptum sit et Chrysippus non improbet, minime velim. Primum, quia deforme atque servile est et certe,", "st": "1.3.13"}, {"sp": "N", "t": "(quod convenit, si aetatem mutes), iniuria est; deinde, quod, si cui tam est mens illiberalis, ut obiurgatione non corrigatur, is etiam ad plagas ut pessima quaeque mancipia durabitur: postremo, quod ne opus erit quidem hac castigatione, si assiduus studiorum exactor astiterit.", "st": "1.3.14"}, {"sp": "N", "t": "Nunc fere negligentia paedagogorum sic emendari videtur, ut pueri non facere, quae recta sunt, cogantur sed cur non fecerint puniantur. Denique cum parvulum verberibus coegeris, quid iuveni facias, cui nec adhiberi potest hic metus et maiora discenda sunt?", "st": "1.3.15"}, {"sp": "N", "t": "Adde, quod multa vapulantibus dictu deformia et mox verecundiae futura saepe dolore vel metu acciderunt, qui pudor frangit animum et abiicit atque ipsius lucis fugam et taedium dictat.", "st": "1.3.16"}, {"sp": "N", "t": "Iam si minor in eligendis custodum vel praeceptorum moribus fuit cura, pudet dicere, in quae probra nefandi homines isto caedendi iure abutantur, quam det allis quoque nonnunquam occasionem hic miserorum metus. Non morabor in parte hac; nimium est quod intelligitur. Quare hoc dixisse satis est; in aetatem infirmam et iniuriae obnoxiam nemini debet nimium licere.", "st": "1.3.17"}, {"sp": "N", "t": "Nunc quibus instituendus sit artibus, qui sic formabitur, ut fieri possit orator, et quae in quaque aetate inchoanda, dicere ingrediar.", "st": "1.3.18"}, {"sp": "N", "t": "Primus in eo, qui scribendi legendique adeptus erit facultatem, grammatici est locus. Nec refert, de Graeco an de Latino loquar, quanquam Graecum esse priorem placet.", "st": "1.4.1"}, {"sp": "N", "t": "Utrique eadem via est. Haec igitur professio, cum brevissime in duas partes dividatur, recte loquendi scientiam et poetarum enarrationem, plus habet in recessu quam fronte promittit.", "st": "1.4.2"}, {"sp": "N", "t": "Nam et scribendi ratio coniuncta cum loquendo est, et enarrationem praecedit emendata lectio, et mixtum his omnibus iudicium est; quo quidem ita severe sunt usi veteres grammatici, ut non versus modo censoria quadam virgula notare et libros, qui falso viderentur inscripti, tanquam subditos summovere familia permiserint sibi, sed auctores alios in ordinem redegerint, alios omnino exemerint numero.", "st": "1.4.3"}, {"sp": "N", "t": "Nec poetas legisse satis est: excutiendum omne scriptorum genus non propter historias modo sed verba, quae frequenter ius ab auctoribus sumunt. Tum neque citra musicen grammatice potest esse perfecta, cum ei de metris rhythmisque dicendum sit, nec, si rationem siderum ignoret, poetas intelligat, qui (ut alia omittam) totiens ortu occasuque signorum in declarandis temporibus utantur; nec ignara philosophiae, cum propter plurimos in omnibus fere carminibus locos ex intima naturalium quaestionum subtilitate repetitos, tum vel propter Empedoclea in Graecis, Varronem ac Lucretium in Latinis, qui praecepta sapientiae versibus tradiderunt.", "st": "1.4.4"}, {"sp": "N", "t": "Eloquentia quoque non mediocri est opus, ut de unaquaque earum, quas demonstravimus, rerum dicat proprie et copiose. Quo minus sunt ferendi, qui hanc artem ut tenuem atque ieiunam cavillantur, quae nisi oratoris futuri fundamenta fideliter iecit, quidquid superstruxeris, corruet; necessaria pueris, iucunda senibus, dulcis secretorum comes et quae vel sola in omni studiorum genere plus habeat operis quam ostentationis.", "st": "1.4.5"}, {"sp": "N", "t": "Ne quis igitur tanquam parva fastidiat grammatices elementa, non quia magnae sit operae consonantes a vocalibus discernere ipsasque eas in semivocalium numerum mutarumque partiri, sed quia interiora velut sacri huius adeuntibus apparebit multa rerum subtilitas, quae non modo acuere ingenia puerilia sed exercere altissimam quoque eruditionem ac scientiam possit.", "st": "1.4.6"}, {"sp": "N", "t": "An cuiuslibet auris est exigere litterarum sonos? non hercule magis quam nervorum. At grammatici saltem omnes in hanc descendent rerum tenuitatem, desintne aliquae nobis necessariae litterarum, non cum Graeca scribimus (tum enim ab iisdem duas mutuamur) sed propriae,", "st": "1.4.7"}, {"sp": "N", "t": "in Latinis, ut in his <em>seruus<\/em> et <em>uulgus<\/em> Aeolicum digammon desideratur, et medius est quidam V et I litterae sonus; non enim sic <em>optimum<\/em> dicimus ut <em>opimum,<\/em> et in <em>here<\/em> neque E plane neque I auditur;", "st": "1.4.8"}, {"sp": "N", "t": "an rursus aliae redundent, praeter notam aspirationis, (quae si necessaria est, etiam contrariam sibi poscit) ut K, quae et ipsa quorundam nominum nota est, et Q, cuius similis effectu specieque, nisi quod paulum a nostris obliquatur, Coppa apud Graecos nunc tantum in numero manet, et nostrarum ultima, qua tam carere potuimus quam ψ non quaerimus?", "st": "1.4.9"}, {"sp": "N", "t": "Atque etiam in ipsis vocalibus grammatici est videre, an aliquas pro consonantibus usus acceperit, quia <em>iam<\/em> sicut <em>etiam<\/em> scribitur et <em>nos<\/em> ut <em>luos.<\/em> At quae ut vocales iunguntur aut unam longam faciunt, ut veteres scripserunt qui geminatione earum velut apice utebantur, aut duas; nisi quis putat etiam ex tribus vocalibus syllabam fieri, si non aliquae officio consonantium fungantur.", "st": "1.4.10"}, {"sp": "N", "t": "Quaeret hoc etiam, quomodo duabus demum vocalibus in se ipsas coeundi natura sit, cum consonantium nulla nisi alteram frangat. Atqui littera I sibi insidit, <em>coniicit<\/em> enim est ab illo <em>iacit,<\/em> et V, quomodo nunc scribitur <em>uulgus<\/em> et <em>seruus.<\/em> Sciat etiam Ciceroni placuisse <em>aiio Maiiamque<\/em> geminata I scribere; quod si est, etiam iungetur ut consonans.", "st": "1.4.11"}, {"sp": "N", "t": "Quare discat puer, quid in litteris proprium, quid commune, quae cum quibus cognatio; nec miretur, cur ex <em>scamno<\/em> fiat <em>scabillum<\/em> aut a <em>pinno<\/em> (quod est acutum) securis utrinque habens aciem <em>bipennis;<\/em> ne illorum sequatur errorem, qui, quia a pennis duabus hoc esse nomen existimant, <em>pennas<\/em> avium dici volunt.", "st": "1.4.12"}, {"sp": "N", "t": "Neque has modo noverit mutationes, quas adferunt declinatio aut praepositio, ut <em>secat secuit, cadit excidit, caedit excidit, calcat exculcat<\/em> (et fit a <em>lavando lotus<\/em> et inde rursus <em>inlutus<\/em> et mille talia), sed quae rectis quoque casibus aetate transierunt. Nam ut <em>Valesii Fusii<\/em> in <em>Valerios Furiosque<\/em> venerunt: ita <em>arbos, labos, vapos<\/em> etiam et <em>clamos<\/em> ac <em>lases<\/em> fuerunt.", "st": "1.4.13"}, {"sp": "N", "t": "Atque haec ipsa S littera ab his nominibus exclusa in quibusdam ipsa alteri successit, nam <em>mertare<\/em> atque <em>pultare<\/em> dicebant, quin <em>fordeum faedosque<\/em> pro aspiratione F velut simili littera utentes; nam contra Graeci aspirare F ut φ solent, ut pro Fundanio Cicero testem, qui primam eius litteram dicere non possit, irridet.", "st": "1.4.14"}, {"sp": "N", "t": "Sed B quoque in locum aliarum dedimus aliquando, unde <em>Burrus<\/em> et <em>Bruges<\/em> et <em>Balaena.<\/em> Nec non eadem fecit ex <em>duello bellum,<\/em> unde <em>Duellios<\/em> quidam dicere <em>Bellios<\/em> ausi.", "st": "1.4.15"}, {"sp": "N", "t": "Quid <em>stlocum stlitesque?<\/em> Quid T litterae cum D quaedam cognatio? Quare minus mirum, si in vetustis operibus urbis nostrae et celebribus templis legantur <em>Alexanter<\/em> et <em>Cassantra.<\/em> Quid O atque V permutatae invicem, ut <em>Hecoba<\/em> et <em>nutrix Culchidis<\/em> et <em>Pulixena<\/em> scriberentur, ac, ne in Graecis id tantum notetur, <em>dederont<\/em> ac <em>probaveront?<\/em> Sic Ὀδυσσεύς, quem Ὀλισσέα fecerant Aeolis, ad <em>Ulixem<\/em> deductus est.", "st": "1.4.16"}, {"sp": "N", "t": "Quid? non E quoque I loco fuit? <em>Μenerva<\/em> et <em>leber<\/em> et <em>magester<\/em> et <em>Diiove Victore<\/em> non <em>Diiovi Victori?<\/em> Sed mihi locum signare satis est, non enim doceo, sed admoneo docturos. Inde in syllabas cura transibit, de quibus in orthographia pauca adnotabo. Tum videbit, ad quem hoc pertinet, quot et quae partes orationis; quanquam de numero parum convenit.", "st": "1.4.17"}, {"sp": "N", "t": "Veteres enim, quorum fuerunt Aristoteles quoque atque Theodectes, verba modo et nomina et convinctiones tradiderunt; videlicet quod in verbis vim sermonis, in nominibus materiam (quia alterum est quod loquimur, alterum de quo loquimur), in convinctionibus autem complexus eorum esse iudicaverunt: quas coniunctiones a plerisque dici scio, sed haec videtur ex συνδέσμῳ magis propria translatio.", "st": "1.4.18"}, {"sp": "N", "t": "Paulatim a philosophis ac maxime Stoicis auctus est numerus, ac primum convinctionibus articuli adiecti, post praepositiones, nominibus appellatio, deinde pronomen, deinde mixtum verbo participium, ipsis verbis adverbia. Noster sermo articulos non desiderat, ideoque in alias partes orationis sparguntur, sed accedit superioribus interiectio.", "st": "1.4.19"}, {"sp": "N", "t": "Alii tamen ex idoneis dumtaxat auctoribus octo partes secuti sunt ut Aristarchus et aetate nostra Palaemon, qui vocabulum sive appellationem nomini subiecerunt tanquam speciem eius. At ii, qui aliud nomen aliud vocabulum faciunt, novem. Nihilominus fuerunt, qui ipsum adhuc vocabulum ab appellatione deducerent, ut esset vocabulum corpus visu tactuque manifestum, <em>domus, lectus,<\/em> appellatio, cui vel alterum deesset vel utrumque, <em>ventus, caelum, deus, virtus.<\/em> Adiiciebant et asseverationem ut <em>eheu,<\/em> et tractationem ut <em>fasciatim;<\/em> quae mihi non approbantur.", "st": "1.4.20"}, {"sp": "N", "t": "Vocabulum an appellatio dicenda sit προσηγορία et subiicienda nomini necne, quia parvi refert, liberum opinaturis relinquo.", "st": "1.4.21"}, {"sp": "N", "t": "Nomina declinare et verba in primis pueri sciant, neque enim aliter pervenire ad intellectum sequentium possunt; quod etiam monere supervacuum erat, nisi ambitiosa festinatione plerique a posterioribus inciperent et, dum ostentare discipulos circa speciosiora malunt, compendio morarentur.", "st": "1.4.22"}, {"sp": "N", "t": "Atqui si quis et didicerit satis et (quod non minus deesse interim solet) voluerit docere quae didicit, non erit contentus tradere in nominibus tria genera et quae sunt duobus omnibusve communia.", "st": "1.4.23"}, {"sp": "N", "t": "Nec statim diligentem putabo, qui promiscua, quae ἐπίκοινα dicuntur, ostenderit, in quibus sexus uterque per alterum apparet; aut quae feminina positione mares aut neutrali feminas significant, qualia sunt <em>Murena<\/em> et <em>Glycerium.<\/em>", "st": "1.4.24"}, {"sp": "N", "t": "Scrutabitur ille praeceptor acer atque subtilis origines nominum, quae ex habitu corporis <em>Rufos Longosque<\/em> fecerunt; ubi erit aliud secretius, <em>Sullae, Burri, Galbae, Plauti, Pansae, Scauri<\/em> taliaque; et ex casu nascentium; hic <em>Agrippa<\/em> et <em>Opiter<\/em> et <em>Cordus<\/em> et <em>Postumus<\/em> erunt; et ex iis, quae post natos eveniunt, unde <em>Vopiscus.<\/em> Iam <em>Cottae, Scipiones, Laenates, Serani<\/em> sunt ex variis causis.", "st": "1.4.25"}, {"sp": "N", "t": "Gentes quoque ac loca et alia multa reperias inter nominum causas. In servis iam intercidit illud genus, quod ducebatur a domino, unde <em>Marcipores Publiporesque.<\/em> Quaerat etiam, sitne apud Graecos vis quaedam sexti casus et apud nos quoque septimi. Nam cum dico <em>hasta percussi,<\/em> non utor ablativi natura; nec, si idem Graece dicam, dativi.", "st": "1.4.26"}, {"sp": "N", "t": "Sed in verbis quoque quis est adeo imperitus, ut ignoret genera et qualitates et personas et numeros? Litterarii paene ista sunt ludi et trivialis scientiae. Iam quosdam illa turbabunt, quae declinationibus non tenentur. Nam et quaedam participia an verba an appellationes sint, dubitari potest, quia aliud alio loco valent,", "st": "1.4.27"}, {"sp": "N", "t": "ut <em>lectum<\/em> et <em>sapiens<\/em> et quaedam verba appellationibus similia, ut fraudator, nutritor. Iam itur in antiquam <em>silvam<\/em> nonne propriae cuiusdam rationis est? nam quod initium eius invenias? cui simile <em>fletur.<\/em> Accipimus aliter, ut <em>panditur interea domus omnipotentis Olympi,<\/em> aliter ut <em>totis usque adeo turbatur agris.<\/em> Est etiam quidam tertias modus, ut <em>urbs habitatur,<\/em> unde et <em>campus curritur, mare navigator.<\/em>", "st": "1.4.28"}, {"sp": "N", "t": "<em>Pransus<\/em> quoque ac <em>potus<\/em> diversum valet quam indicat. Quid? quod multa verba non totum declinationis ordinem ferunt? Quaedam etiam mutantur ut <em>fero<\/em> in praeterito, quaedam tertiae demum personae figura dicuntur ut <em>licet, piget,<\/em> quaedam simile quiddam patiuntur vocabulis quae in adverbium transeunt? Nam ut <em>noctu<\/em> et <em>diu<\/em> ita <em>dictu factuque.<\/em> Sunt enim haec quoque verba participialia quidem, non tamen qualia <em>dicto factoque.<\/em>", "st": "1.4.29"}, {"sp": "N", "t": "Iam cum omnis oratio tris habeat virtutes, ut emendata, ut dilucida, ut ornata sit (quia dicere apte, quod est praecipuum, plerique ornatui subiiciunt), totidem vitia, quae sunt supra dictis contraria, emendate loquendi regulam, quae grammatices prior pars est, examinet.", "st": "1.5.1"}, {"sp": "N", "t": "Haec exigitur verbis aut singulis aut pluribus. <em>Verba<\/em> nunc generaliter accipi volo, nam duplex eorum intellectus est; alter, qui omnia per quae sermo nectitur significat, ut apud Horatium: <em>verbaque provisam rem non invita sequentur;<\/em> alter, in quo est una pars orationis, <em>lego, scribo.<\/em> Quam vitantes ambiguitatem quidam dicere maluerunt <em>voces, locutiones, dictiones.<\/em>", "st": "1.5.2"}, {"sp": "N", "t": "Singula sunt aut nostra aut peregrina, aut simplicia aut composita, aut propria aut translata, aut usitata aut ficta. Uni verbo vitium saepius quam virtus inest. Licet enim dicamus aliquod proprium, speciosum, sublime: nihil tamen horum nisi in complexu loquendi serieque contingit; laudamus enim verba rebus bene accommodata.", "st": "1.5.3"}, {"sp": "N", "t": "Sola est, quae notari possit velut <em>vocalitas,<\/em> quae εὐφωνία dicitur; cuius in eo delectus est, ut inter duo, quae idem significant ac tantundem valent, quod melius sonet malis.", "st": "1.5.4"}, {"sp": "N", "t": "Prima barbarismi ac soloecismi foeditas absit. Sed quia interim excusantur haec vitia aut consuetudine aut auctoritate aut vetustate aut denique vicinitate virtutum (nam saepe a figuris ea separare difficile est), ne qua tam lubrica observatio fallat, acriter se in illud tenue discrimen grammaticus intendat, de quo nos latius ibi loquemur, ubi de figuris orationis tractandum erit.", "st": "1.5.5"}, {"sp": "N", "t": "Interim vitium, quod fit in singulis verbis, sit barbarismus. Occurrat mihi forsan aliquis, quid hic promisso tanti operis dignum? aut quis hoc nescit, alios barbarismos scribendo fieri alios loquendo;—quia, quod male scribitur, male etiam dici necesse est; quae vitiose dixeris, non utique et scripto peccant—illud prius adiectione, detractione, immutatione, transmutatione, hoc secundum divisione, complexione, aspiratione, sono contineri?", "st": "1.5.6"}, {"sp": "N", "t": "Sed ut parva sint haec, pueri docentur adhuc, et grammaticos officii sui commonemus. Ex quibus si quis erit plane impolitus et vestibulum modo artis huius ingressus, intra haec, quae profitentium commentariolis vulgata sunt, consistet, doctiores multa adiicient, vel hoc primum, quod barbarismum pluribus modis accipimus.", "st": "1.5.7"}, {"sp": "N", "t": "Unum gente, quale est, si quis Afrum vel Hispanum Latinae orationi nomen inserat, ut ferrum, quo rotae vinciuntur, dici solet <em>cantus,<\/em> quanquam eo tanquam recepto utitur Persius; sicut Catullus <em>ploxenum<\/em> circa Padum invenit, et in oratione Labieni (sive illa Cornelii Galli est) in Pollionem <em>casamo<\/em> adsectator e Gallia ductum est; nam <em>mastrucam,<\/em> quod Sardum est, irridens Cicero ex industria dixit.", "st": "1.5.8"}, {"sp": "N", "t": "Alterum genus barbarismi accipimus, quod fit animi natura, ut is, a quo insolenter quid aut minaciter aut crudeliter dictum sit, barbare locutus existimatur.", "st": "1.5.9"}, {"sp": "N", "t": "Tertium est illud vitium barbarismi, cuius exempla vulgo sunt plurima, sibi etiam quisque fingere potest, ut verbo, cui libebit, adiiciat litteram syllabamve vel detrahat, aut aliam pro alia aut eandem alio quam rectum est loco ponat.", "st": "1.5.10"}, {"sp": "N", "t": "Sed quidam fere in iactationem eruditionis sumere illa ex poetis solent et auctores quos praelegunt criminantur. Scire autem debet puer, haec apud scriptores carminum aut venia digna aut etiam laude duci, potiusque illa docendi erunt minus vulgata.", "st": "1.5.11"}, {"sp": "N", "t": "Nam duos in uno nomine faciebat barbarismos Tinga Placentinus (si reprehendenti Hortensio credimus) <em>preculam<\/em> pro <em>pergula<\/em> dicens, et immutatione cum <em>c<\/em> pro <em>g<\/em> uteretur, et transmutatione cum <em>r<\/em> praeponeret <em>e<\/em> antecedenti. At in eiusdem vitii geminatione <em>Mettoeoque Fufetioeo<\/em> dicens Ennius poetico iure defenditur.", "st": "1.5.12"}, {"sp": "N", "t": "Sed in prosa quoque est quaedam iam recepta immutatio. Nam Cicero <em>Canopitarum<\/em> exercitum dicit, ipsi <em>Canobon<\/em> vocant; et <em>Trasumennum<\/em> pro <em>Tarsumenno<\/em> multi auctores, etiamsi est in eo transmutatio, vindicaverunt. Similiter alia; nam sive est <em>adsentior,<\/em> Sisenna dixit <em>adsentio<\/em> multique et hunc et analogian secuti, sive illud verum est, haec quoque pars consensu defenditur.", "st": "1.5.13"}, {"sp": "N", "t": "At ille pexus pinguisque doctor aut illic detractionem aut hic adiectionem putabit. Quid quod quaedam, quae singula procul dubio vitiosa sunt, iuncta sine reprehensione dicuntur?", "st": "1.5.14"}, {"sp": "N", "t": "Nam et <em>dua<\/em> et <em>tre<\/em> [et <em>pondo<\/em>] diversorum generum sunt barbarismi; at <em>duapondo<\/em> et <em>trepondo<\/em> usque ad nostram aetatem ab omnibus dictum est, et recte dici Messala confirmat.", "st": "1.5.15"}, {"sp": "N", "t": "Absurdum forsitan videatur dicere, barbarismum, quod est unius verbi vitium, fieri per numeros aut genera sicut soloecismum: <em>scala<\/em> tamen et <em>scopa<\/em> contraque <em>hordea<\/em> et <em>mulsa,<\/em> licet litterarum mutationem, detractionem, adiectionem habeant, non alio vitiosa sunt, quam quod pluralia singulariter et singularia pluraliter efferuntur; et <em>gladia<\/em> qui dixerunt, genere exciderunt.", "st": "1.5.16"}, {"sp": "N", "t": "Sed hoc quoque notare contentus sum, ne arti culpa quorundam pervicacium perplexae videar et ipse quaestionem addidisse. Plus exigunt subtilitatis quae accidunt in dicendo vitia, quia exempla eorum tradi scripto non possunt, nisi cum in versus inciderunt, ut divisio <em>Europaï Asiaï<\/em> et ei contrarium vitium, quod συναίρεσιν et συναλοιφὴν Graeci vocant, nos complexionem dicamus, qualis est apud P. Varronem <em>tum te flagrant deiectum fulmine Phaethon.<\/em>", "st": "1.5.17"}, {"sp": "N", "t": "Nam si esset prosa oratio, easdem litteras enuntiare veris syllabis licebat. Praeterea quae fiunt spatio, sive cum syllaba correpta producitur, ut <em>Italiam fato profugus,<\/em> seu longa corripitur, ut <em>unius ob noxam et furias,<\/em> extra carmen non deprehendas; sed nec in carmine vitia dicenda sunt.", "st": "1.5.18"}, {"sp": "N", "t": "Illa vero non nisi aure exiguntur, quae fiunt per sonos; quanquam per aspirationem, sive adiicitur vitiose sive detrahitur, apud nos potest quaeri an in scripto sit vitium, si <em>h<\/em> littera est, non nota. Cuius quidem ratio mutata cum temporibus est saepius.", "st": "1.5.19"}, {"sp": "N", "t": "Parcissime ea veteres usi etiam in vocalibus, cum <em>aedos ircosque<\/em> dicebant; diu deinde servatum, ne consonantibus aspirarent, <em>ut<\/em> in <em>Graccis<\/em> et in <em>triumpis;<\/em> erupit brevi tempore nimius usus, ut <em>choronae, chenturiones, praechones<\/em> adhuc quibusdam in inscriptionibus maneant, qua de re Catulli nobile epigramma est.", "st": "1.5.20"}, {"sp": "N", "t": "Inde durat ad nos usque <em>vehementer<\/em> et <em>comprehendere<\/em> et <em>mihi,<\/em> nam <em>mehe<\/em> quoque pro <em>me<\/em> apud antiquos tragoediarum praecipue scriptores in veteribus libris invenimus.", "st": "1.5.21"}, {"sp": "N", "t": "Adhuc difficilior observatio est per tenores (quos quidem ab antiquis dictos <em>tonores<\/em> comperi videlicet declinato a Graecis verbo, qui τόνους dicunt), vel adcentus, quas Graeci προσῳδίας vocant, cum acuta et gravis alia pro alia ponuntur, ut in hoc <em>Camillus,<\/em> si acuitur prima:", "st": "1.5.22"}, {"sp": "N", "t": "aut gravis pro flexa, ut <em>Cethegus,<\/em> et hic prima acuta (nam sic media mutatur); aut flexa pro gravi, ut <em>Appi<\/em> circumducta sequenti, quam ex duabus syllabis in unam cogentes et deinde flectentes dupliciter peccant.", "st": "1.5.23"}, {"sp": "N", "t": "Sed id saepius in Graecis nominibus accidit, ut <em>Atreus,<\/em> quem nobis iuvenibus doctissimi senes acuta prima dicere solebant, ut necessario secunda gravis esset, item <em>Nerei Tereique.<\/em> Haec de accentibus tradita.", "st": "1.5.24"}, {"sp": "N", "t": "Ceterum scio iam quosdam eruditos, nonnullos etiam grammaticos sic docere ac loqui, ut propter quaedam vocum discrimina verbum interim acuto sono finiant,", "st": "1.5.25"}, {"sp": "N", "t": "ut in illis <em>quae circum littora, circum piscosos scopulos,<\/em> ne, si gravem posuerint secundam, <em>circus<\/em> dici videatur non <em>circuitus.<\/em> Itemque cum <em>quale<\/em> interrogantes gravi, comparantes acuto tenore concludunt; quod tamen in adverbiis fere solis ac pronominibus vindicant, in ceteris veterem legem sequuntur.", "st": "1.5.26"}, {"sp": "N", "t": "Mihi videtur condicionem mutare, quod his locis verba coniungimus. Nam cum dico <em>circum litora,<\/em> tanquam unum enuntio dissimulata distinctione, itaque tanquam in una voce una est acuta, quod idem accidit in illo <em>Troiae qui primus ab oris.<\/em>", "st": "1.5.27"}, {"sp": "N", "t": "Evenit, ut metri quoque condicio mutet accentum, ut <em>Pecudes pictaeque volucres;<\/em> nam volucres media acuta legam, quia, etsi natura brevis, tamen positione longa est, ne faciat iambum, quem non recipit versus herous.", "st": "1.5.28"}, {"sp": "N", "t": "Separata vero haec a praecepto non recedent, aut si consuetudo vicerit, vetus lex sermonis abolebitur; cuius difficilior apud Graecos observatio est, quia plura illis loquendi genera, quas διαλέκτους vocant, et quod alia vitiosum interim alia rectum est; apud nos vero brevissima ratio.", "st": "1.5.29"}, {"sp": "N", "t": "Namque in omni voce acuta intra numerum trium syllabarum continetur, sive eae sunt in verbo sole sive ultimae, et in iis aut proxima extremae aut ab ea tertia. Trium porro, de quibus loquor, media longa aut acuta aut flexa erit; eodem loco brevis utique gravem habebit sonum, ideoque positam ante se id est ab ultima tertiam acuet.", "st": "1.5.30"}, {"sp": "N", "t": "Est autem in omni voce utique acuta sed nunquam plus una nec unquam ultima ideoque in disyllabis prior. Praeterea nunquam in eadem flexa et acuta, quoniam est in flexa et acuta, itaque neutra claudet vocem Latinam. Ea vero, quae sunt syllabae unius, erunt acuta aut flexa, ne sit aliqua vox sine acuta.", "st": "1.5.31"}, {"sp": "N", "t": "Et illa per sonos accidunt, quae demonstrari scripto non possunt, vitia oris et linguae: ἰωτακισμοὺς et λαμβδακισμοὺς et ἰσχνότητας et πλατειασμοὺς feliciores fingendis nominibus Graeci vocant, sicut κοιλοστομίαν, cum vox quasi in recessu oris auditor.", "st": "1.5.32"}, {"sp": "N", "t": "Sunt etiam proprii quidam et inenarrabiles soni, quibus nonnunquam nationes reprehendimus. Remotis igitur omnibus, de quibus supra dixi, vitiis erit illa quae vocatur ὀρθοέπεια, id est emendata cum suavitate vocum explanatio: nam sic accipi potest recta.", "st": "1.5.33"}, {"sp": "N", "t": "Cetera vitia omnia ex pluribus vocibus sunt, quorum est soloecismus, quanquam circa hoc quoque disputatum est. Nam etiam qui complexu orationis accidere eum confitentur, quia tamen unius emendatione verbi corrigi possit, in verbo esse vitium non in sermone contendunt;", "st": "1.5.34"}, {"sp": "N", "t": "cum, sive <em>amarae corticis<\/em> seu <em>medio cortice<\/em> per genus facit soloecismum (quorum neutrum quidem reprehendo, cum sit utriusque Vergilius auctor; sed fingamus utrumlibet non recte dictum), mutatio vocis alterius, in qua vitium erat, rectam loquendi rationem sit redditura, ut <em>amari corticis<\/em> fiat vel <em>media cortice.<\/em> Quod manifestae calumniae est; neutrum enim vitiosum est separatum, sed compositione peccatur, quae iam sermonis est.", "st": "1.5.35"}, {"sp": "N", "t": "Illud eruditius quaeritur, an in singulis quoque verbis possit fieri soloecismus, uti si unum quis ad se vocans dicat <em>venite,<\/em> aut si plures a se dimittens ita loquatur <em>abi<\/em> aut <em>discede.<\/em> Nec non cum responsum ab interrogante dissentit, ut si dicenti <em>Quem video?<\/em> ita occurras <em>Ego.<\/em> In gestu etiam nonnulli putant idem vitium inesse, cum aliud voce aliud nutu vel manu demonstratur.", "st": "1.5.36"}, {"sp": "N", "t": "Huic opinioni neque omnino accedo neque plane dissentio. Nam id fateor accidere voce una non tamen aliter, quam si sit aliquid, quod vim alterius vocis obtineat, ad quod vox illa referatur, ut soloecismus ex complexu fiat eorum, quibus res significantur et voluntas ostenditur.", "st": "1.5.37"}, {"sp": "N", "t": "Atque ut omnem effugiam cavillationem, sit aliquando in uno verbo nunquam in solo verbo. Per quot autem et per quas accidat species, non satis convenit. Qui plenissime, quadripertitam volunt esse rationem nec aliam quam barbarismi, ut fiat adiectione <em>nam enim, de susum, in Alexandriam;<\/em> detractione <em>ambulo viam, Aegypto venio, ne hoc fecit;<\/em>", "st": "1.5.38"}, {"sp": "N", "t": "transmutatione, qua ordo turbatur, <em>quoque ego, enim hoc voluit, autem non habuit.<\/em> Ex quo genere an sit <em>igitur<\/em> initio sermonis positum, dubitari potest, quia maximos auctores in diversa fuisse opinione video, cum apud alios sit etiam frequens, apud alios nunquam reperiatur.", "st": "1.5.39"}, {"sp": "N", "t": "Haec tria genera quidam deducunt a soloecismo, et adiectionis vitium πλεονασμόν, detractionis ἔλλειψιν, inversionis ἀναστροφήν vocant, quae si in speciem soloecismi cadat, ὑπερβατόν quoque eodem appellari modo posse.", "st": "1.5.40"}, {"sp": "N", "t": "Immutatio sine controversia est, cum aliud pro alio ponitur. Id per omnes orationis partes deprehendimus, frequentissime in verbo, quia plurima huic accidunt; ideoque in eo fiunt soloecismi per genera, tempora, personas, modos, sive cui <em>status eos<\/em> dici seu <em>qualitates<\/em> placet, vel sex vel, ut alii volunt, octo;—nam totidem vitiorum erunt formae, in quot species eorum quidque, de quibus supra dictum est, diviseris praeterea numeros,", "st": "1.5.41"}, {"sp": "N", "t": "in quibus nos singularem ac pluralem habemus Graeci et δυϊκόν. Quanquam fuerunt, qui nobis quoque adiicerent dualem <em>scripsere, legere;<\/em> quod evitandae asperitatis gratia mollitum est, ut apud veteres pro <em>male mereris, male merere.<\/em> Ideoque quod vocant <em>dualem,<\/em> in illo solo genere consistit, cum apud Graecos et in verbi tota fere ratione et in nominibus deprehendatur, et sic quoque rarissimus eius sit usus,", "st": "1.5.42"}, {"sp": "N", "t": "apud nostrorum vero neminem haec observatio reperiatur, quin e contrario <em>devenere locos<\/em> et <em>conticuere omnes<\/em> et <em>consedere duces<\/em> aperte nos doceant, nihil horum ad duos pertinere; <em>dixere<\/em> quoque, quamquam id Antonius Rufus ex diverso ponit exemplum, de pluribus patronis praeco pronuntiet.", "st": "1.5.43"}, {"sp": "N", "t": "Quid? non Livius circa initia statim primi libri, <em>Tenuere,<\/em> inquit, <em>arcem Sabini?<\/em> et mox, <em>in adversum Romani subiere?<\/em> Sed quem potius ego quam M. Tullium sequar? qui in Oratore, <em>Non reprehendo,<\/em> inquit, <em>scripsere; scripserunt esse verius sentio.<\/em>", "st": "1.5.44"}, {"sp": "N", "t": "Similiter in vocabulis et nominibus fit soloecismus genere, numero, proprie autem casibus, quidquid horum alteri succedet. Huic parti subiungatur licet per comparationes et superlationes, itemque in quibus patrium pro possessivo dicitur vel contra.", "st": "1.5.45"}, {"sp": "N", "t": "Nam vitium, quod fit per quantitatem ut <em>magnum peculiolum,<\/em> erunt qui soloecismum putent quia pro nomine integro positum sit deminutum. Ego dubito, an id improprium potius appellem, significatione enim deerrat; soloecismi porro uitium non est in sensu sed in complexu.", "st": "1.5.46"}, {"sp": "N", "t": "In participio per genus et casum, ut in vocabulo, per tempora, ut in verbo, per numerum, ut in utroque, peccatur. Pronomen quoque genus, numerum, casus habet, quae omnia recipiunt huiusmodi errorem.", "st": "1.5.47"}, {"sp": "N", "t": "Fiunt soloecismi et quidem plurimi per partes orationis; sed id tradere satis non est, ne ita demum vitium esse credat puer, si pro alia ponatur alia, ut verbum, ubi nomen esse debuerit, vel adverbium, ubi pronomen, et similia.", "st": "1.5.48"}, {"sp": "N", "t": "Nam sunt quaedam cognata, ut dicunt, id est eiusdem generis, in quibus, qui alia specie quam oportet utetur, non minus quam ipso genere permutato deliquerit.", "st": "1.5.49"}, {"sp": "N", "t": "Nam et <em>an<\/em> et <em>aut<\/em> coniunctiones sunt, male tamen interroges, <em>hic aut ille sit;<\/em> et <em>ne<\/em> ac <em>non<\/em> adverbia; qui tamen dicat pro illo <em>ne feceris non feceris,<\/em> in idem incidat vitium, quia alterum negandi est alterum vetandi. Hoc amplius <em>intro<\/em> et <em>intus<\/em> loci adverbia, <em>eo<\/em> tamen <em>intus<\/em> et <em>intro sum<\/em> soloecismi sunt.", "st": "1.5.50"}, {"sp": "N", "t": "Eadem in diversitate pronominum, interiectionum, praepositionum accident; est etiam soloecismus in oratione comprehensionis unius sequentium ac priorum inter se inconveniens position.", "st": "1.5.51"}, {"sp": "N", "t": "Quaedam tamen et faciem soloecismi habent et dici vitiosa non possunt, ut <em>tragoedia Thyestes<\/em> et <em>ludi Floralia ac Megalensia,<\/em> quanquam haec sequenti tempore interciderunt numquam aliter a veteribus dicta. Schemata igitur nominabuntur, frequentiora quidem apud poetas sed oratoribus quoque permissa.", "st": "1.5.52"}, {"sp": "N", "t": "Verum schema fere habebit aliquam rationem, ut docebimus eo, quem paulo ante promisimus, loco. Sed id quoque, quod schema vocatur, si ab aliquo per imprudentiam factum erit, soloecismi vitio non carebit.", "st": "1.5.53"}, {"sp": "N", "t": "In eadem specie sunt sed schemate carent, ut supra dixi, nomina feminina, quibus mares utuntur, et neutralia, quibus feminae. Hactenus de soloecismo. Neque enim artem grammaticam componere aggressi sumus, sed cum in ordinem incurreret, inhonoratam transire noluimus.", "st": "1.5.54"}, {"sp": "N", "t": "Hoc amplius, ut institutum ordinem sequar, verba aut Latina aut peregrina sunt. Peregrina porro ex omnibus prope dixerim gentibus ut homines, ut instituta etiam multa venerunt.", "st": "1.5.55"}, {"sp": "N", "t": "Taceo de Tuscis et Sabinis et Praenestinis quoque; nam ut eorum sermone utentem Vettium Lucilius insectatur, quemadmodum Pollio reprehendit in Livio Patavinitatem, licet omnia Italica pro Romanis habeam.", "st": "1.5.56"}, {"sp": "N", "t": "Plurima Gallica evaluerunt ut <em>raeda<\/em> ac <em>petorritum,<\/em> quorum altero tamen Cicero altero Horatius utitur. Et <em>mappam<\/em> circo quoque usitatum nomen Poeni sibi vindicant, et <em>gurdos,<\/em> quos pro stolidis accipit vulgus, ex Hispania duxisse originem audivi.", "st": "1.5.57"}, {"sp": "N", "t": "Sed haec divisio mea ad Graecum sermonem praecipue pertinet, nam et maxima ex parte Romanus inde conversus est et confessis quoque Graecis utimur verbis, ubi nostra desunt, sicut illi a nobis nonnunquam mutuantur. Inde illa quaestio exoritur, an eadem ratione per casus duci externa qua nostra conveniat.", "st": "1.5.58"}, {"sp": "N", "t": "Ac si reperias grammaticum veterum amatorem, neget quidquam ex Latina ratione mutandum, quia, cum sit apud nos casus ablativus, quem illi non habent, parum conveniat uno casu nostro quinque Graecis uti;", "st": "1.5.59"}, {"sp": "N", "t": "quin etiam laudet virtutem eorum, qui potentiorem facere linguam Latinam studebant, nec alienis egere institutis fatebantur. Inde <em>Castorem<\/em> media syllaba producta pronuntiarunt, quia hoc omnibus nostris nominibus accidebat, quorum prima positio in easdem quas <em>Castor<\/em> litteras exit; et ut <em>Palaemo<\/em> ac <em>Telamo<\/em> et <em>Plato<\/em> (nam sic eum Cicero quoque appellat) dicerentur, retinuerunt, quia Latinum, quod o et n litteris finiretur, non reperiebant.", "st": "1.5.60"}, {"sp": "N", "t": "Ne in a quidem atque <em>s<\/em> litteras exire temere masculina Graeca nomina recto casu patiebantur, ideoque et apud Caelium legimus <em>Pelia cincinnatus<\/em> et apud Messalam <em>bene fecit Euthia<\/em> et apud Ciceronem <em>Hermagora,<\/em> ne miremur, quod ab antiquorum plerisque <em>Aenea<\/em> ut <em>Anchisa<\/em> sit dictus.", "st": "1.5.61"}, {"sp": "N", "t": "Nam si ut <em>Maecenas, Sufenas, Asprenas<\/em> dicerentur, genitivo casu non e littera, sed <em>tis<\/em> syllaba terminarentur. Inde <em>Olympo<\/em> et <em>tyranno<\/em> acutam syllabam mediam dederunt, quia duabus longis insequentibus primam brevem acui noster sermo non patitur.", "st": "1.5.62"}, {"sp": "N", "t": "Sic genitivus <em>Ulixi<\/em> et <em>Achilli<\/em> fecit, sic alia plurima. Nunc recentiores instituerunt Graecis nominibus Graecas declinationes potius dare, quod tamen ipsum non semper fieri potest. Mihi autem placet Latinam rationem sequi, quousque patitur decor. Neque enim iam <em>Calypsonem<\/em> dixerim ut <em>Iunonem,<\/em> quanquam secutus antiquos, C. Caesar utitur hac ratione declinandi. Sed auctoritatem consuetudo superavit.", "st": "1.5.63"}, {"sp": "N", "t": "In ceteris, quae poterunt utroque modo non indecenter efferri, qui Graecam figuram sequi malet, non Latine quidem sed tamen citra reprehensionem loquetur.", "st": "1.5.64"}, {"sp": "N", "t": "Simplices voces prima positione id est natura sua constant, compositae aut praepositionibus subiunguntur ut <em>innocens<\/em> (dum ne pugnantibus inter se duabus, quale est <em>inperterritus;<\/em> alioqui possunt aliquando continuari duae ut <em>incompositus, reconditus<\/em> et quo Cicero utitur <em>subabsurdum<\/em>), aut e duobus quasi corporibus coalescunt, ut <em>maleficus.<\/em>", "st": "1.5.65"}, {"sp": "N", "t": "Nam ex tribus nostrae utique linguae non concesserim; quamvis <em>capsis<\/em> Cicero dicat compositum esse ex <em>cape si vis,<\/em> et inveniantur qui <em>Lupercalia<\/em> aeque tres partes orationis esse contendant,", "st": "1.5.66"}, {"sp": "N", "t": "quasi <em>luere per caprum;<\/em> nam <em>Solitaurilia<\/em> iam persuasum est esse <em>Suouetaurilia,<\/em> et sane ita se habet sacrum, quale apud Homerum quoque est. Sed haec non tam ex tribus quam ex particulis trium coeunt. Ceterum etiam ex praepositione et duobus vocabulis dure videtur struxisse Pacuvius <em>Nerei repandirostrum, incuruiceruicum pecus.<\/em>", "st": "1.5.67"}, {"sp": "N", "t": "Iunguntur autem aut ex duobus Latinis integris ut <em>superfui, subterfugi<\/em> (quanquam ex integris an composita sint quaeritur), aut ex integro et corrupto ut <em>malevolus,<\/em> aut ex corrupto et integro ut <em>noctivagus,<\/em> aut ex duobus corruptis ut <em>pedisecus,<\/em> aut ex nostro et peregrino ut <em>biclinium,<\/em> aut contra ut <em>epitogium<\/em> et <em>Anticato,<\/em> aliquando et ex duobus peregrinis ut <em>epiraedium.<\/em> Nam cum sit praepositio Graeca, <em>raeda<\/em> Gallicum: neque Graecus tamen neque Gallus utitur composito; Romani suum ex alieno utroque fecerunt.", "st": "1.5.68"}, {"sp": "N", "t": "Frequenter autem praepositiones quoque compositio ista corrumpit: inde abstulit, aufugit, amisit, cum praepositio sit <em>ab<\/em> sola; et <em>coit,<\/em> cum sit praepositio <em>con;<\/em> sic <em>ignaui<\/em> et <em>erepublica<\/em> et similia.", "st": "1.5.69"}, {"sp": "N", "t": "Sed res tota magis Graecos decet, nobis minus succedit, nec id fieri natura puto, sed alienis favemus; ideoque cum κυρταύχενα mirati simus, <em>incurvicervicum<\/em> vix a risu defendimus.", "st": "1.5.70"}, {"sp": "N", "t": "Propria sunt verba, cum id significant, in quod primo denominata sunt; translata, cum alium natura intellectum alium loco praebent. Usitatis tutius utimur, nova non sine quodam periculo fingimus. Nam si recepta sunt, modicam laudem adferunt orationi, repudiata etiam in iocos exeunt.", "st": "1.5.71"}, {"sp": "N", "t": "Audendum tamen; namque, ut Cicero ait, etiam quae primo dura visa sunt, usu molliuntur. Sed minime nobis concessa est ὀνοματοποιία quis enim ferat, si quid simile illis merito laudatis λίγξε βιός et σίζ ὀφθαλμός fingere audeamus? Nam ne <em>balare<\/em> quidem aut <em>hinnire<\/em> fortiter diceremus, nisi iudicio vetustatis niterentur.", "st": "1.5.72"}, {"sp": "N", "t": "Est etiam sua loquentibus observatio, sua scribentibus. Sermo constat ratione vel vetustate, auctoritate, consuetudine. Rationem praestat praecipue analogia, nonnunquam et etymologia. Vetera maiestas quaedam et, ut sic dixerim, religio commendat.", "st": "1.6.1"}, {"sp": "N", "t": "Auctoritas ab oratoribus vel historicis peti solet; nam poetas metri necessitas excusat, nisi si quando nihil impediente in utroque modulatione pedum alterum malunt, qualia sunt, <em>imo de stirpe recisum, et aëriae quo congessere palumbes et silice in nuda<\/em> et similia; cum summorum in eloquentia virorum iudicium pro ratione, et velut error honestus est magnos duces sequentibus.", "st": "1.6.2"}, {"sp": "N", "t": "Consuetudo vero certissima loquendi magistra, utendumque plane sermone ut nummo, cui publica forma est. Omnia tamen haec exigunt acre iudicium, analogia praecipue, quam proxime ex Graeco transferentes in Latinum proportionem vocaverunt.", "st": "1.6.3"}, {"sp": "N", "t": "Eius haec vis est, ut id quod dubium est ad aliquid simile, de quo non quaeritur, referat et incerta certis probet. Quod efficitur duplici via: comparatione similium in extremis maxime syllabis, propter quod ea quae sunt e singulis negantur debere rationem, et deminutione.", "st": "1.6.4"}, {"sp": "N", "t": "Comparatio in nominibus aut genus deprehendit aut declinationem; genus, ut si quaeratur, <em>funis<\/em> masculinum sit an femininum, simile illi sit <em>panis;<\/em> declinationem, ut si veniat in dubium, <em>hac domu<\/em> dicendum sit an <em>hac domo<\/em> et <em>domuum<\/em> an <em>domorum:<\/em>", "st": "1.6.5"}, {"sp": "N", "t": "similia sint [domus] <em>anus, manus.<\/em> Deminutio genus modo detegit, et, ne ab eodem exemplo recedam, <em>funem<\/em> masculinum esse <em>funiculus<\/em> ostendit.", "st": "1.6.6"}, {"sp": "N", "t": "Eadem in verbis quoque ratio comparationis, ut, si quis antiques secutus <em>fervere<\/em> brevi media syllaba dicat, deprehendatur vitiose loqui, quod omnia, quae e et o litteris fatendi modo terminantur, eadem, si infinitis <em>e<\/em> litteram media syllaba acceperunt, utique productam habent: <em>prandeo pendeo spondeo, prandere pendere spondere.<\/em>", "st": "1.6.7"}, {"sp": "N", "t": "At quae <em>o<\/em> solam habent, dummodo per eandem litteram in infinito exeant, brevia fiunt: <em>lego dico curro, legere dicere currere;<\/em> etiamsi est apud Lucilium <em>Fervit aqua et fervet, fervit nunc, fervet ad annum.<\/em>", "st": "1.6.8"}, {"sp": "N", "t": "Sed pace dicere hominis eruditissimi liceat, si <em>fervit<\/em> putat illi simile <em>currit<\/em> et <em>legit, fervo<\/em> dicetur ut <em>lego<\/em> et <em>curro,<\/em> quod nobis inauditum est. Sed non est haec vera comparatio; nam <em>fervit<\/em> est illi simile <em>servit,<\/em> quam proportionem sequenti dicere necesse est <em>fervire<\/em> ut <em>servire.<\/em>", "st": "1.6.9"}, {"sp": "N", "t": "Prima quoque aliquando positio ex obliquis invenitur, ut memoria repeto convictos a me, qui reprehenderant, quod hoc verbo usus essem, <em>pepigi;<\/em> nam id quidem dixisse summos auctores confitebantur, rationem tamen negabant permittere, quia prima positio <em>paciscor,<\/em> cum haberet naturam patiendi, faceret tempore praeterito <em>pactus sum.<\/em>", "st": "1.6.10"}, {"sp": "N", "t": "Nos praeter auctoritatem oratorum atque historicorum analogia quoque dictum hoc tuebamur. Nam cum legeremus in XII tabulis <em>ni ita pagunt,<\/em> inveniebamus simile huic <em>cadunt,<\/em> inde prima positio, etiamsi vetustate exoleverat, apparebat <em>paco<\/em> ut <em>cado,<\/em> unde non erat dubium sic <em>pepigi<\/em> nos dicere ut <em>cecidi.<\/em>", "st": "1.6.11"}, {"sp": "N", "t": "Sed meminerimus non per omnia duci analogiae posse rationem, cum et sibi ipsa plurimis in locis repugnet. Quaedam sine dubio conantur eruditi defendere, ut, cum deprehensum est, <em>lepus<\/em> et <em>lupus<\/em> similia positione quantum casibus numerisque dissentiant: ista respondent non esse paria, quia <em>lepus<\/em> epicoenon sit, <em>lupus<\/em> masculinum; quanquam Varro in eo libro, quo initia Romanae urbis enarrat, <em>lupum feminam<\/em> dicit Ennium Pictoremque Fabium secutus.", "st": "1.6.12"}, {"sp": "N", "t": "Illi autem iidem, cum interrogantur, cur <em>aper apri<\/em> et <em>pater patris<\/em> faciat, illud nomen positum, hoc ad aliquid esse contendunt. Praeterea quoniam utrumque a Graeco ductum sit, ad eam rationem recurrunt, ut πατρός <em>patris,<\/em>", "st": "1.6.13"}, {"sp": "N", "t": "κάπρου <em>apri<\/em> faciat. Illa tamen quomodo effugient, ut, nomina quamvis feminina singulari nominativo <em>us<\/em> litteris finita nunquam genitivo casu <em>ris<\/em> syllaba terminentur, faciat tamen <em>Venus Veneris?<\/em> item cum <em>es<\/em> litteris finita per varios exeant genitivos, nunquam tamen eadem <em>ris<\/em> syllaba terminatos, <em>Ceres<\/em> cogat dici <em>Cereris?<\/em>", "st": "1.6.14"}, {"sp": "N", "t": "Quid vero? quod tota positionis eiusdem in diversos flexus eunt? cum <em>Alba faciat Albanos<\/em> et <em>Albensis, volo volui<\/em> et <em>volavi.<\/em> Nam praeterito quidem tempore varie formari verba prima persona o littera terminata, ipsa analogia confiteatur; siquidem facit <em>cado cecidi, spondeo spopondi, pingo pinxi, lego legi, pono posui, frango fregi, laudo laudavi.<\/em> Non enim, cum primum fingerentur homines, analogia demissa caelo formam loquendi dedit, sed inventa est postquam loquebantur, et notatum in sermone quid quomodo caderet. Itaque non ratione nititur sed exemplo, nec lex est loquendi sed observatio, ut ipsam analogiam nulla res alia fecerit quam consuetudo.", "st": "1.6.15"}, {"sp": "N", "t": "Inhaerent tamen ei quidam molestissima diligentiae perversitate, ut <em>audaciter<\/em> potius dicant quam <em>audacter,<\/em> licet omnes oratores aliud sequantur, et <em>emicavit<\/em> non <em>emicuit<\/em> et <em>conire<\/em> non <em>coire.<\/em> His permittamus et <em>audivisse<\/em> et <em>sciuisse<\/em> et <em>tribunale<\/em> et <em>faciliter<\/em> dicere; <em>frugalis<\/em> quoque sit apud illos <em>non fugi,<\/em> nam quo alio modo fiet <em>frugalitas?<\/em>", "st": "1.6.17"}, {"sp": "N", "t": "Iidem <em>centum milia nummum<\/em> et <em>fidem Deum<\/em> ostendant duplices quoque soloecismos esse, quando et casum mutant et numerum; nesciebamus enim ac non consuetudini et decori serviebamus, sicut in plurimis, quae M. Tullius in Oratore divine ut omnia exequitur.", "st": "1.6.18"}, {"sp": "N", "t": "Sed Augustus quoque in epistulis ad C. Caesarem scriptis emendat, quod is <em>calidum<\/em> dicere quam <em>caldum<\/em> malit, non quia id non sit Latinum sed quia sit odiosum et, ut ipse Graeco verbo significavit,", "st": "1.6.19"}, {"sp": "N", "t": "περίεργον. Atqui hanc quidam ὀρθοέπειαν solam putant, quam ego minime excludo. Quid enim tam necessarium quam recta locutio? Immo inhaerendum ei iudico, quoad licet, diu etiam mutantibus repugnandum; sed abolita atque abrogata retinere insolentiae cuiusdam est et frivolae in parvis iactantiae.", "st": "1.6.20"}, {"sp": "N", "t": "Multum enim litteratus, qui sine aspiratione et producta secunda syllaba salutarit (<em>avere<\/em> est enim) et <em>calefacere<\/em> dixerit potius, quam quod dicimus, et <em>conservauisse,<\/em> his adiiciat <em>face<\/em> et <em>dice<\/em> et similia. Recta est haec via;", "st": "1.6.21"}, {"sp": "N", "t": "quis negat? sed adiacet et mollior et magis trita. Ego tamen non alio magis angor, quam quod obliquis casibus ducti etiam primas sibi positiones non invenire sed mutare permittunt: ut cum <em>ebur<\/em> et <em>robur,<\/em> ita dicta ac scripta summis auctoribus, in <em>o<\/em> litteram secundae syllabae transferunt, quia sit <em>roboris<\/em> et <em>eboris, sulpur<\/em> autem et <em>guttur u<\/em> litteram in genitivo servent; ideoque <em>iecur<\/em> etiam et <em>femur<\/em> controversiam fecerunt.", "st": "1.6.22"}, {"sp": "N", "t": "Quod non minus est licentiosum, quam si sulpuri et gutturi subiicerent in genitivo litteram <em>o<\/em> mediam, quia esset <em>eboris<\/em> et <em>roboris;<\/em> sicut Antonius Gnipho, qui <em>robur<\/em> quidem et <em>ebur<\/em> atque etiam <em>marmur<\/em> fatetur esse, verum fieri vult ex his <em>robura, ebura, marmura.<\/em>", "st": "1.6.23"}, {"sp": "N", "t": "Quodsi animadverterent litterarum adfinitatem, scirent sic ab eo, quod est <em>robur, roboris<\/em> fieri, quomodo ab eo, quod est <em>miles limes, militis limitis, index vindex, iudicis vindicis,<\/em> et quae supra iam attigi.", "st": "1.6.24"}, {"sp": "N", "t": "Quid vero quod, ut dicebam, similes positiones in longe diversas figures per obliquos casus exeunt, ut <em>virgo Iuno, lusus lusus, cuspis puppis<\/em> et mille alia? cum illud etiam accidat, ut quaedam pluraliter non dicantur, quaedam contra singulari numero, quaedam casibus careant, quaedam a primis statim positionibus tota mutentur, ut <em>Iuppiter.<\/em>", "st": "1.6.25"}, {"sp": "N", "t": "Quod verbis etiam accidit ut illi <em>fero,<\/em> cuius praeteritum perfectum et ulterius non invenitur. Nec plurimum refert, nulla haec an praedura sint. Nam quid <em>progenies<\/em> genitivo singulari, quid plurali <em>spes<\/em> faciet? Quomodo autem <em>quire<\/em> et <em>ruere<\/em> vel in praeterita patiendi modo vel in participia transibunt?", "st": "1.6.26"}, {"sp": "N", "t": "Quid de aliis dicam, cum senatus <em>senati<\/em> an <em>senatus<\/em> faciat, incertum sit? Quare mihi non invenuste dici videtur, aliud esse Latine aliud grammatice loqui. Ac de analogia nimium.", "st": "1.6.27"}, {"sp": "N", "t": "Etymologia, quae verborum originem inquirit, a Cicerone dicta est notatio, quia nomen eius apud Aristotelem invenitur σύμβολον, quod est nota; nam verbum ex verbo ductum, id est veriloquium, ipse Cicero, qui finxit, reformidat. Sunt qui vim potius intuiti originationem vocent.", "st": "1.6.28"}, {"sp": "N", "t": "Haec habet aliquando usum necessarium, quotiens interpretatione res, de qua quaeritur, eget, ut M. Caelius se esse hominem <em>frugi<\/em> vult probare, non quia abstinens sit (nam id ne ementiri quidem poterat), sed quia utilis multis, id est fructuosus, unde sit ducta <em>frugalitas.<\/em> Ideoque in definitionibus assignatur etymologiae locus.", "st": "1.6.29"}, {"sp": "N", "t": "Nonnunquam etiam barbara ab emendatis conatur discernere, ut cum, <em>Triquetram<\/em> dici Siciliam an <em>Triquedram, meridiem<\/em> an <em>medidiem<\/em> oporteat quaeritur,", "st": "1.6.30"}, {"sp": "N", "t": "aliaque quae consuetudini serviunt. Continet autem in se multam eruditionem, sive ex Graecis orta tractemus, quae sunt plurima, praecipueque Aeolica ratione (cui est sermo noster simillimus) declinata, sive ex historiarum veterum notitia nomina hominum, locorum, gentium, urbium requiramus, unde <em>Bruti, Publicolae, Pythici?<\/em> cur <em>Latium, Italia, Beneventum?<\/em> quae <em>Capitolium<\/em> et collem <em>Quirinalem<\/em> et <em>Argiletum<\/em> appellandi ratio?", "st": "1.6.31"}, {"sp": "N", "t": "Iam illa minora, in quibus maxime studiosi eius rei fatigantur, qui verba paulum declinata varie et multipliciter ad veritatem reducunt aut correptis aut porrectis, aut adiectis aut detractis, aut permutatis litteris syllabisve. Inde pravis ingeniis ad foedissima usque ludibria labuntur. Sit enim <em>Consul a<\/em> consulendo vel a iudicando; nam et hoc <em>consulere<\/em> veteres vocaverunt, unde adhuc remanet illud <em>rogat boni consulas,<\/em> id est bonum iudices.", "st": "1.6.32"}, {"sp": "N", "t": "<em>Senatui<\/em> nomen dederit aetas (nam iidem <em>Patres<\/em> sunt), et <em>rex rector<\/em> et alia plurima indubitata; nec abnuerim <em>tegulae regulaeque<\/em> et similium his rationem. iam sit et <em>classis<\/em> a calando et <em>lepus levipes<\/em> et <em>vulpes volipes:<\/em>", "st": "1.6.33"}, {"sp": "N", "t": "etiamne a contrariis aliqua sinemus trahi, ut <em>lucus,<\/em> quia umbra opacus parum luceat, et <em>ludus,<\/em> quia sit longissime a lusu, et <em>Ditis,<\/em> quia minime <em>dives?<\/em> etiamne <em>hominem<\/em> appellari, quia sit <em>humo<\/em> natus (quasi vero non omnibus animalibus eadem origo, aut illi primi mortales ante nomen imposuerint terrae quam sibi), et <em>verba<\/em> ab aere <em>verberato?<\/em>", "st": "1.6.34"}, {"sp": "N", "t": "Pergamus: sic perveniemus eo usque, ut <em>stella<\/em> luminis <em>stilla<\/em> credatur, cuius etymologiae auctorem clarum sane in litteris nominari in ea parte, qua a me reprehenditur, inhumanum est.", "st": "1.6.35"}, {"sp": "N", "t": "Qui vero talia libris complexi sunt, nomina sua ipsi inscripserunt; ingenioseque visus est Gavius <em>caelibes<\/em> dicere veluti <em>caelites,<\/em> quod onere gravissimo vacent, idque Graeco argumento iuvit, ἠϊθέους enim eadem de causa dici affirmat. Nec ei cedit Modestus inventione, nam, quia <em>Caelo<\/em> Saturnus genitalia absciderit, hoc nomine appellatos, qui uxore careant, ait; Aelius <em>pituitam,<\/em> quia <em>petat vitam.<\/em>", "st": "1.6.36"}, {"sp": "N", "t": "Sed cui non post Varronem sit venia, qui <em>agrum,<\/em> quia in eo <em>agatur<\/em> aliquid, et <em>graculos,<\/em> quia <em>gregatim<\/em> volent, dictos Ciceroni persuadere voluit (ad eum enim scribit), cum alterum ex Graeco sit manifestum duci, alterum ex vocibus avium?", "st": "1.6.37"}, {"sp": "N", "t": "Sed hoc tanti fuit vertere, ut <em>merula,<\/em> quia sola volat, quasi <em>mera volans<\/em> nominaretur. Quidam non dubitaverunt etymologine subiicere omnem nominis causam: ut ex habitu, <em>quemadmodum dixi, Longos et Rufos, ex sono strepere, murmurare;<\/em> etiam derivata, ut a <em>uelocitate<\/em> dicitur <em>velox,<\/em> et composita pluraque his similia, quae sine dubio aliunde originem ducunt, sed arte non egent, cuius in hoc opere non est usus nisi in dubiis.", "st": "1.6.38"}, {"sp": "N", "t": "Verba a vetustate repetita non solum magnos assertores habent sed etiam adferunt orationi maiestatem aliquam non sine delectatione; nam et auctoritatem antiquitatis habent et, quia intermissa sunt, gratiam novitati similem parant.", "st": "1.6.39"}, {"sp": "N", "t": "Sed opus est modo, ut neque crebra sint haec neque manifesta, quia nihil est odiosius adfectatione, nec utique ab ultimis et iam oblitteratis repetita temporibus, qualia sunt <em>topper<\/em> et <em>antegerio<\/em> et <em>exanclare<\/em> et <em>prosapia<\/em> et Saliorum carmina vix sacerdotibus suis satis intellecta.", "st": "1.6.40"}, {"sp": "N", "t": "Sed illa mutari vetat religio et consecratis utendum est; oratio vero, cuius summa virtus est perspicuitas, quam sit vitiosa, si egeat interprete? Ergo, ut novorum optima erunt maxime vetera, ita veterum maxime nova.", "st": "1.6.41"}, {"sp": "N", "t": "Similis circa auctoritatem ratio. Nam etiamsi potest videri nihil peccare, qui utitur iis verbis, quae summi auctores tradiderunt, multum tamen refert non solum, quid dixerint, sed etiam quid persuaserint. Neque enim <em>tuburchinabundum<\/em> et <em>lurchinabundum<\/em> iam in nobis quisquam ferat, licet Cato sit auctor, nec <em>hos lodices,<\/em> quanquam id Pollioni placet, nec <em>gladiola,<\/em> atqui Messala dixit, nec <em>parricidatum,<\/em> quod in Caelio vix tolerabile videtur, nec <em>collos<\/em> mihi Calvus persuaserit; quae nec ipsi iam dicerent.", "st": "1.6.42"}, {"sp": "N", "t": "Superest igitur consuetudo; nam fuerit paene ridiculum malle sermonem, quo locuti sint homines, quam quo loquantur. Et sane quid est aliud vetus sermo quam vetus loquendi consuetudo? Sed huic ipsi necessarium est iudicium, constituendumque in primis id ipsum quid sit, quod consuetudinem vocemus.", "st": "1.6.43"}, {"sp": "N", "t": "Quae si ex eo, quod plures faciunt, nomen accipiat, periculosissimum dabit praeceptum, non orationi modo sed (quod maius est) vitae. Unde enim tantum boni, ut pluribus quae recta sunt placeant? Igitur ut velli et comam in gradus frangere et in balneis perpotare, quamlibet haec invaserint civitatem, non erit consuetudo, quia nihil horum caret reprehensione; at lavamur et tondemur et convivimus ex consuetudine: sic in loquendo, non si quid vitiose multis insederit, pro regula sermonis accipiendum erit.", "st": "1.6.44"}, {"sp": "N", "t": "Nam, ut transeam, quemadmodum vulgo imperiti loquantur, tota saepe theatra et omnem circi turbam exclamasse barbare scimus. Ergo consuetudinem sermonis vocabo consensum eruditorum, sicut vivendi consensum bonorum.", "st": "1.6.45"}, {"sp": "N", "t": "Nunc, quoniam diximus, quae sit loquendi regula, dicendum, quae scribentibus custodienda, quod Graeci ὀρθογραφίαν vocant; hoc nos recte scribendi scientiam nominemus. Cuius ars non in hoc posita est, ut noverimus, quibus quaeque syllaba litteris constet (nam id quidem infra grammatici officium est), sed totam, ut mea fert opinio, subtilitatem in dubiis habet.", "st": "1.7.1"}, {"sp": "N", "t": "Ut longis syllabis omnibus apponere apicem ineptissimum est, quia plurimae natura ipsa verbi quod scribitur patent, sed interim necessarium, cum eadem littera alium atque alium intellectum, prout correpta vel producta est, facit; ut <em>malus<\/em> arborem significat an hominem non bonum apice distinguitur,", "st": "1.7.2"}, {"sp": "N", "t": "<em>palus<\/em> aliud priore syllaba longa aliud sequenti significat, et cum eadem littera nominativo casu brevis, ablativo longa est, utrum sequamur, plerumque hac nota monendi sumus.", "st": "1.7.3"}, {"sp": "N", "t": "Similiter putaverunt illa quoque servanda discrimina, ut <em>ex<\/em> praepositionem, si verbum sequeretur <em>specto,<\/em> adiecta secundae syllabae <em>s<\/em> littera, si <em>pecto,<\/em> remota scriberemus.", "st": "1.7.4"}, {"sp": "N", "t": "Illa quoque servata est a multis differentia, ut <em>ad,<\/em> cum esset praepositio, <em>d<\/em> litteram, cum autem coniunctio, <em>t<\/em> acciperet, itemque <em>cum,<\/em> si tempus significaret, per <em>qu,<\/em> si comitem, per <em>c<\/em> ac duas sequentes scriberetur.", "st": "1.7.5"}, {"sp": "N", "t": "Frigidiora his alia, ut <em>quidquid c<\/em> quartam haberet, ne interrogare his videremur; et <em>quotidie<\/em> non <em>cotidie,<\/em> ut sit <em>quot diebus.<\/em> Verum haec iam etiam inter ipsas ineptias evanuerunt.", "st": "1.7.6"}, {"sp": "N", "t": "Quaeri solet, in scribendo praepositiones sonum quem iunctae efficiunt, an quem separatae, observare conveniat: ut, cum dico <em>optinuit<\/em> (secundam enim <em>b<\/em> litteram ratio poscit,", "st": "1.7.7"}, {"sp": "N", "t": "aures magis audiunt <em>p<\/em>) et <em>immunis,<\/em> illud enim, quod veritas exigit, sequentis syllabae sono victum <em>m<\/em> gemina commutatur.", "st": "1.7.8"}, {"sp": "N", "t": "Est et in dividendis verbis observatio, mediam litteram consonantem priori an sequenti syllabae adiungas: <em>haruspex<\/em> enim, quia pars eius posterior a <em>spectando<\/em> est, <em>s<\/em> litteram tertiae dabit; <em>abstemius,<\/em> quia ex abstinentia temeti composita vox est, primae relinquet.", "st": "1.7.9"}, {"sp": "N", "t": "Nam <em>k<\/em> quidem in nullis verbis utendum puto, nisi quae significant, etiam ut sola ponatur. Hoc eo non omisi, quod quidam eam, quotiens <em>a<\/em> sequatur, necessariam credunt, cum sit <em>c<\/em> littera, quae ad omnes vocales vim suam perferat.", "st": "1.7.10"}, {"sp": "N", "t": "Verum orthographia quoque consuetudini servit, ideoque saepe mutata est. Nam illa vetustissima transeo tempora, quibus et pauciores litterae nec similes his nostris earum formae fuerunt et vis quoque diversa, sicut apud Graecos <em>o<\/em> litterae, quae interim longa ac brevis ut apud nos, interim pro syllaba quam nomine suo exprimit posita est;", "st": "1.7.11"}, {"sp": "N", "t": "ut Latinis veteribus <em>d<\/em> plurimis in verbis adiectam ultimam, quod manifestum est etiam ex columna rostrata, quae est Duilio in foro posita; interim <em>g<\/em> quoque, ut in pulvinari Solis, qui colitur iuxta aedem Quirini, <em>vesperug,<\/em> quod <em>vesperuginem<\/em> accipimus.", "st": "1.7.12"}, {"sp": "N", "t": "De mutatione etiam litterarum, de qua supra dixi, nihil repetere hic necesse est, fortasse enim sicut scribebant etiam loquebantur.", "st": "1.7.13"}, {"sp": "N", "t": "Semivocales geminare diu non fuit usitatissimi moris, atque e contrario usque ad Accium et ultra porrectas syllabas geminis, ut dixi, vocalibus scripserunt.", "st": "1.7.14"}, {"sp": "N", "t": "Diutius duravit, ut <em>e<\/em> et <em>i<\/em> iungendis eadem ratione qua Graeci ει uterentur; ea casibus numerisque discreta est, ut Lucilius praecipit: <em>Iam puerei venere, e postremum. facito atque i, Ut pueri plures fiant;<\/em> ac deinceps idem: <em>Mendaci furique addes e, cum dare furi iusseris.<\/em>", "st": "1.7.15"}, {"sp": "N", "t": "Quod quidem cum supervacuum est, quia <em>i<\/em> tam longae quam brevis naturam habet, tum incommodum aliquando. Nam in iis, quae proximam ab ultima litteram <em>e<\/em> habebunt et <em>i<\/em> longa terminabuntur, illam rationem sequentes utemur <em>e<\/em> gemina, qualia sunt haec <em>aurei, argentei<\/em> et his similia.", "st": "1.7.16"}, {"sp": "N", "t": "Idque iis praecipue, qui ad lectionem instituentur, etiam impedimento erit; sicut in Graecis accidit adiectione <em>i<\/em> litterae, quam non solum dativis casibus in parte ultima ascribunt sed quibusdam etiam interponunt, ut in ΛΗΙΣΤΗΙ quia etymologia ex divisione in tris syllabas facta desideret eam litteram.", "st": "1.7.17"}, {"sp": "N", "t": "<em>Ae<\/em> syllabam, cuius secundam nunc e litteram ponimus, varie per <em>a<\/em> et <em>i<\/em> efferebant; quidam semper ut Graeci, quidam singulariter tantum, cum in datiuum vel genitivum casum incidissent, unde <em>pictai vestis<\/em> et <em>aquai<\/em> Vergilius amantissimus vetustatis carminibus inseruit.", "st": "1.7.18"}, {"sp": "N", "t": "In iisdem plurali numero e utebantur, <em>hi Syllae, Galbae.<\/em> Est in hac quoque parte Lucilii praeceptum, quod quia pluribus explicatur versibus, si quis parum credet, apud ipsum in nono requirat.", "st": "1.7.19"}, {"sp": "N", "t": "Quid quod Ciceronis temporibus paulumque infra, fere quotiens s littera media vocalium longarum vel subiecta longis esset, geminabatur, ut <em>caussae, cassus, divissiones?<\/em> quomodo et ipsum et Vergilium quoque scripsisse manus eorum docent.", "st": "1.7.20"}, {"sp": "N", "t": "Atqui paulum superiores etiam illud, quod nos gemina dicimus <em>iussi,<\/em> una dixerunt. Iam <em>optimus maximus,<\/em> ut media <em>i<\/em> litteram, quae veteribus <em>u<\/em> fuerat, acciperent, Gai primum Caesaris inscriptione traditur factum.", "st": "1.7.21"}, {"sp": "N", "t": "<em>Here<\/em> nunc <em>e<\/em> littera terminamus, at veterum comicorum adhuc libris invenio <em>Heri ad me venit;<\/em> quod idem in epistolis Augusti, quas sua manu scripsit aut emendavit, deprehenditur.", "st": "1.7.22"}, {"sp": "N", "t": "Quid? non Cato Censorius <em>dicam et faciam dicem<\/em> et <em>faciem<\/em> scripsit, eundemque in ceteris, quae similiter cadunt, modum tenuit, quod et ex veteribus eius libris manifestum est et a Messala in libro de <em>s<\/em> littera positum?", "st": "1.7.23"}, {"sp": "N", "t": "<em>Sibe<\/em> et <em>quase<\/em> scriptum in multorum libris est, sed an hoc voluerint auctores, nescio; T. Livium ita his usum ex Pediano comperi, qui et ipse eum sequebatur;", "st": "1.7.24"}, {"sp": "N", "t": "haec nos <em>i<\/em> littera finimus. Quid dicam <em>vortices et vorsus<\/em> ceteraque ad eundem modum, quae primus Scipio Africanus in <em>e<\/em> litteram secundam vertisse dicitur?", "st": "1.7.25"}, {"sp": "N", "t": "Nostri praeceptores <em>seruum ceruumque u<\/em> et o litteris scripserunt, quia subiecta sibi vocalis in unum sonum coalescere et confundi nequiret; nunc <em>u<\/em> gemina scribuntur ea ratione, quam reddidi; neutro sane modo vox, quam sentimus, efficitur. Nec inutiliter Claudius Aeolicam illam ad hos usus litteram adiecerat.", "st": "1.7.26"}, {"sp": "N", "t": "Illud nunc melius, quod <em>cui<\/em> tribus, quas praeposui, litteris enotamus; in quo pueris nobis ad pinguem sane sonum <em>qu<\/em> et <em>oi<\/em> utebantur, tantum ut ab illo <em>qui<\/em> distingueretur.", "st": "1.7.27"}, {"sp": "N", "t": "Quid? quae scribuntur aliter quam enuntiantur? Nam et <em>Gaius C<\/em> littera significatur, quae inversa mulierem declarat; quia tam <em>Gaias<\/em> esse vocitatas quam <em>Gaios<\/em> etiam ex nuptialibus sacris apparet.", "st": "1.7.28"}, {"sp": "N", "t": "Nec <em>Gnaeus<\/em> eam litteram in praenominis nota accipit, quae sonat; et <em>columnam<\/em> et <em>consules<\/em> exempta <em>n<\/em> littera legimus; et <em>Subura,<\/em> cum tribus litteris notatur, <em>c<\/em> tertiam ostendit. Multa sunt generis huius; sed haec quoque vereor ne modum tam parvae quaestionis excesserint.", "st": "1.7.29"}, {"sp": "N", "t": "Iudicium autem suum grammaticus interponat his omnibus; nam hoc valere plurimum debet. Ego (nisi quod consuetudo obtinuerit) sic scribendum quidque iudico, quomodo sonat.", "st": "1.7.30"}, {"sp": "N", "t": "Hic enim est usus litterarum, ut custodiant voces et velut depositum reddant legentibus, itaque id exprimere debent quod dicturi sumus.", "st": "1.7.31"}, {"sp": "N", "t": "Hae fere sunt emendate loquendi scribendique partes; duas reliquas significanter ornateque dicendi non equidem grammaticis aufero, sed cum mihi officia rhetoris supersint, maiori operi reservo.", "st": "1.7.32"}, {"sp": "N", "t": "Redit autem illa cogitatio, quosdam fore, qui haec quae diximus parva nimium et impedimenta quoque maius aliquid agentibus putent. Nec ipse ad extremam usque anxietatem et ineptas cavillationes descendendum atque iis ingenia concidi et comminui credo.", "st": "1.7.33"}, {"sp": "N", "t": "Sed nihil ex grammatice nocuerit, nisi quod supervacuum est. An ideo minor est M. Tullius orator, quod idem artis huius diligentissimus fuit et in filio (ut epistolis apparet) recte loquendi asper quoque exactor? aut vim C. Caesaris fregerunt editi de analogia libri?", "st": "1.7.34"}, {"sp": "N", "t": "aut ideo minus Messala nitidus, quia quosdam totos libellos non verbis modo singulis sed etiam litteris dedit? Non obstant hae disciplinae per illas euntibus sed circa illas haerentibus.", "st": "1.7.35"}, {"sp": "N", "t": "Superest lectio, in qua puer ut sciat, ubi suspendere spiritum debeat, quo loco versum distinguere, ubi claudatur sensus, unde incipiat, quando attollenda vel summittenda sit vox, quo quidque flexu, quid lentius, celerius, concitatius, lenius dicendum, demonstrari nisi in opere ipso non potest.", "st": "1.8.1"}, {"sp": "N", "t": "Unum est igitur, quod in hac parte praecipiam: ut omnia ista facere possit, intelligat. Sit autem in primis lectio virilis et cum suavitate quadam gravis et non quidem prosae similis, quia et carmen est et se poetae canere testantur; non tamen in canticum dissoluta nec plasmate (ut nunc a plerisque fit) effeminata; de quo genere optime C. Caesarem praetextatum adhuc accepimus dixisse: <em>Si cantas, male cantas; si legis, cantas.<\/em>", "st": "1.8.2"}, {"sp": "N", "t": "Nec prosopopoeias, ut quibusdam placet, ad comicum morem pronuntiari velim; esse tamen flexum quendam, quo distinguantur ab iis, in quibus poeta persona sua utetur.", "st": "1.8.3"}, {"sp": "N", "t": "Cetera admonitione magna egent, in primis, ut tenerae mentes tracturaeque altius, quidquid rudibus et omnium ignaris insederit, non modo quae diserta sed vel magis quae honesta sunt, discant.", "st": "1.8.4"}, {"sp": "N", "t": "Ideoque optime institutum est, ut ab Homero atque Vergilio lectio inciperet, quanquam ad intelligendas eorum virtutes firmiore iudicio opus est; sed huic rei superest tempus, neque enim semel legentur. Interim et sublimitate heroi carminis animus adsurgat et ex magnitudine rerum spiritum ducat et optimis imbuatur.", "st": "1.8.5"}, {"sp": "N", "t": "Utiles tragoediae, alunt et lyrici; si tamen in his non auctores modo sed etiam partes operis elegeris, nam et Graeci licenter multa et Horatium nolim in quibusdam interpretari. Elegia vero, utique quae amat, et hendecasyllabi, qui sunt commata Sotadeorum (nam de Sotadeis ne praecipiendum quidem est) amoveantur, si fieri potest, si minus, certe ad firmius aetatis robur reserventur.", "st": "1.8.6"}, {"sp": "N", "t": "Comoediae, quae plurimum conferre ad eloquentiam potest, cum per omnes et personas et adfectus eat, quem usum in pueris putem, paulo post suo loco dicam; nam cum mores in tuto fuerint, inter praecipua legenda erit.", "st": "1.8.7"}, {"sp": "N", "t": "De Menandro loquor, nec tamen excluserim alios. Nam Latini quoque auctores adferent utilitatis aliquid. Sed pueris, quae maxime ingenium alant atque animum augeant, praelegenda; ceteris, quae ad eruditionem modo pertinent, longa aetas spatium dabit. Multum autem veteres etiam Latini conferunt, (quanquam plerique plus ingenio quam arte valuerunt) in primis copiam verborum, quorum in tragoediis gravitas, in comoediis elegantia et quidam velut ἀττικισμός inveniri potest.", "st": "1.8.8"}, {"sp": "N", "t": "Oeconomia quoque in iis diligentior quam in plerisque novorum erit, qui omnium operum solam virtutem sententias putaverunt. Sanctitas certe et, ut sic dicam, virilitas ab iis petenda est, quando nos in omnia deliciarum vitia dicendi quoque ratione defluximus.", "st": "1.8.9"}, {"sp": "N", "t": "Denique credamus summis oratoribus, qui veterum poemata vel ad fidem causarum vel ad ornamentum eloquentiae adsumunt.", "st": "1.8.10"}, {"sp": "N", "t": "Nam praecipue quidem apud Ciceronem frequenter tamen apud Asinium etiam et ceteros, qui sunt proximi, videmus Enni, Acci, Pacuvi, Lucili, Terenti, Caecili et aliorum inseri versus summa non eruditionis modo gratia sed etiam iucunditatis, cum poeticis voluptatibus aures a forensi asperitate respirent.", "st": "1.8.11"}, {"sp": "N", "t": "Quibus accedit non mediocris utilitas, cum sententiis eorum velut quibusdam testimoniis quae proposuere confirment. Verum priora illa ad pueros magis, haec sequentia ad robustiores pertinebunt, cum grammatices amor et usus lectionis non scholarum temporibus, sed vitae spatio terminentur.", "st": "1.8.12"}, {"sp": "N", "t": "In praelegendo grammaticus et illa quidem minora praestare debebit, ut partes orationis reddi sibi soluto versu desideret et pedum proprietates, quae adeo debent esse notae in carminibus, ut etiam in oratoria compositione desiderentur. Deprehendat, quae barbara, quae impropria, quae contra leges loquendi sint posita;", "st": "1.8.13"}, {"sp": "N", "t": "non ut ex iis utique improbentur poetae (quibus, quia plerumque servire metro coguntur, adeo ignoscitur, ut vitia ipsa allis in carmine appellationibus nominentur; metaplasmos enim et schematismos et schemata, ut dixi, vocamus, et laudem virtutis necessitati damus), sed ut commoneat artificialium et memoriam agitet.", "st": "1.8.14"}, {"sp": "N", "t": "Id quoque inter prima rudimenta non inutile demonstrare, quot quaeque verba modis intelligenda sint. Circa glossemata etiam, id est voces minus usitatas, non ultima eius professionis diligentia est.", "st": "1.8.15"}, {"sp": "N", "t": "Enimvero iam maiore cura doceat tropos omnes, quibus praecipue non poema modo sed etiam oratio ornatur; schemata utraque, id est figuras, quaeque λέξεως quaeque διανοίας vocantur, quorum ego sicut troporum tractatum in eum locum differo, quo mihi de ornatu orationis dicendum erit.", "st": "1.8.16"}, {"sp": "N", "t": "Praecipue vero illa infigat animis, quae in oeconomia virtus, quae in decore rerum, quid personae cuique convenerit, quid in sensibus laudandum, quid in verbis, ubi copia probabilis, ubi modus.", "st": "1.8.17"}, {"sp": "N", "t": "His accedet enarratio historiarum, diligens quidem illa non tamen usque ad supervacuum laborem occupata. Nam receptas aut certe claris auctoribus memoratas exposuisse satis est. Persequi quidem, quid quis unquam vel contemptissimorum hominum dixerit, aut nimiae miseriae aut inanis iactantiae est et detinet atque obruit ingenia melius aliis uacatura.", "st": "1.8.18"}, {"sp": "N", "t": "Nam qui omnes etiam indignas lectione scidas excutit, anilibus quoque fabulis accommodare operam potest. Atqui pleni sunt huiusmodi impedimentis grammaticorum commentarii, vix ipsis qui composuerunt satis noti.", "st": "1.8.19"}, {"sp": "N", "t": "Nam Didymo, quo nemo plura scripsit, accidisse compertum est, ut, cum historiae cuidam tanquam vanae repugnaret, ipsius proferretur liber, qui eam continebat.", "st": "1.8.20"}, {"sp": "N", "t": "Quod evenit praecipue in fabulosis usque ad deridicula quaedam, quaedam etiam pudenda; unde improbissimo cuique pleraque fingendi licentia est, adeo ut de libris totis et auctoribus, ut succurrit, mentiantur tuto, quia inveniri qui nunquam fuere non possunt: nam in notioribus frequentissime deprehenduntur a curiosis. Ex quo mihi inter virtutes grammatici habebitur aliqua nescire.", "st": "1.8.21"}, {"sp": "N", "t": "Et finitae quidem sunt partes duae, quas haec professio pollicetur, id est ratio loquendi et enarratio auctorum, quarum illam methodicen hanc historicen vocant. Adiiciamus tamen eorum curae quaedam dicendi primordia, quibus aetates nondum rhetorem capientes instituant.", "st": "1.9.1"}, {"sp": "N", "t": "Igitur Aesopi fabellas, quae fabulis nutricularum proxime succedunt, narrare sermone puro et nihil se supra modum extollente, deinde eandem gracilitatem stilo exigere condiscant; versus primo solvere, mox mutatis verbis interpretari, tum paraphrasi audacius vertere, qua et breviare quaedam et exornare salvo modo poetae sensu permittitur.", "st": "1.9.2"}, {"sp": "N", "t": "Quod opus etiam consummatis professoribus difficile qui commode tractaverit, cuicunque discendo sufficiet. Sententiae quoque et chriae et ethologiae subiectis dictorum rationibus apud grammaticos scribantur, quia initium ex lectione ducunt; quorum omnium similis est ratio, forma diversa, quia sententia universalis est vox, ethologia personis continetur.", "st": "1.9.3"}, {"sp": "N", "t": "Chriarum plura genera traduntur: unum simile sententiae, quod est positum in voce simplici, <em>Dixit ille,<\/em> aut, <em>Dicere solebat;<\/em> alterum, quod est in respondendo, <em>Interrogatus ille,<\/em> vel, <em>cum hoc ei dictum esset, respondit;<\/em> tertium huic non dissimile, <em>cum quis dixisset aliquid, vel fecisset.<\/em>", "st": "1.9.4"}, {"sp": "N", "t": "Etiam in ipsorum factis esse chriam putant, ut <em>Crates, cum indoctum puerum vidisset, paedagogum eius percussit;<\/em> et aliud paene par ei, quod tamen eodem nomine appellare non audent sed dicunt χρειῶδες, ut <em>Milo, quem vitulum adsueuerat ferre, taurum ferebat.<\/em> In his omnibus et declinatio per eosdem ducitur casus, et tam factorum quam dictorum ratio est.", "st": "1.9.5"}, {"sp": "N", "t": "Narratiunculas a poetis celebratas notitiae causa non eloquentiae tractandas puto. Cetera maioris operis ac spiritus Latini rhetores relinquendo necessaria grammaticis fecerunt; Graeci magis operum suorum et onera et modum norunt.", "st": "1.9.6"}, {"sp": "N", "t": "Haec de Grammatice, quam brevissime potui, non ut omnia dicerem sectatus, quod infinitum erat, sed ut maxime necessaria; nunc de ceteris artibus, quibus instituendos, priusquam rhetori tradantur, pueros existimo, strictim subiungam, ut efficiatur orbis ille doctrinae, quem Graeci ἐγκύκλιον παιδείαν vocant.", "st": "1.10.1"}, {"sp": "N", "t": "Nam iisdem fere annis aliarum quoque disciplinarum studia ingredienda sunt, quae, quia et ipsae artes sunt et esse perfectae sine orandi scientia possunt nec rursus ad efficiendum oratorem satis valent solae, an sint huic operi necessariae quaeritur.", "st": "1.10.2"}, {"sp": "N", "t": "Nam quid, inquiunt, ad agendam causam dicendamve sententiam pertinet, scire, quemadmodum data linea constitui triangula aequis lateribus possint? Aut quo melius vel defendet reum vel reget consilia, qui citharae sonos nominibus et spatiis distinxerit?", "st": "1.10.3"}, {"sp": "N", "t": "Enumerent etiam fortasse multos quamlibet utiles foro, qui nec geometren audierint nec musicos nisi hac communi voluptate aurium intelligant. Quibus ego primum hoc respondeo, quod M. Cicero scripto ad Brutum libro frequentius testatur, non eum a nobis institui oratorem, qui sit aut fuerit, sed imaginem quandam concepisse nos animo perfecti illius et nulla parte cessantis.", "st": "1.10.4"}, {"sp": "N", "t": "Nam et sapientem formantes eum, qui sit futurus consummatus undique et, ut dicunt, mortalis quidam deus, non modo cognitione caelestium vel mortalium putant instruendum, sed per quaedam parva sane, si ipsa demum aestimes, ducunt sicut exquisitas interim ambiguitates; non quia <em>ceratinae<\/em> aut <em>crocodilinae<\/em> possint facere sapientem, sed quia illum ne in minimis quidem oporteat falli.", "st": "1.10.5"}, {"sp": "N", "t": "Similiter oratorem, qui delet esse sapiens, non geometres faciet aut musicus quaeque his alia subiungam, sed hae quoque artes, ut sit consummatus, iuvabunt. Nisi forte antidotus quidem atque alia, quae oculis aut vulneribus medentur, ex multis atque interim contrariis quoque inter se effectibus componi videmus, quorum ex diversis fit una illa mixtura, quae nulli earum similis est, ex quibus constat, sed proprias vires ex omnibus sumit;", "st": "1.10.6"}, {"sp": "N", "t": "et nuta animalia mellis illum inimitabilem humanae rationi saporem vario florum ac sucorum genere perficiunt: nos mirabimur, si oratio, qua nihil praestantius homini dedit providentia, pluribus artibus egeat, quae, etiam cum se non ostendunt in dicendo nec proferunt, vim tamen occultam suggerunt et tacitae quoque sentiuntur? Fuit aliquis sine iis disertus:", "st": "1.10.7"}, {"sp": "N", "t": "sed ego oratorem volo. Non multum adiiciunt: sed aeque non erit totum, cui vel parva deerunt; et optimum quidem hoc esse conveniet; cuius etiamsi in arduo spes est, nos tamen praecipiamus omnia, ut saltem plura fiant. Sed cur deficiat animus? Natura enim perfectum oratorem esse non prohibet, turpiterque desperatur quidquid fieri potest. Atque ego vel iudicio veterum poteram esse contentus.", "st": "1.10.8"}, {"sp": "N", "t": "Nam quis ignorat musicen (ut de hae primum loquar) tantum iam illis antiquis temporibus non studii modo verum etiam venerationis habuisse, ut iidem musici et vates et sapientes iudicarentur (mittam alios) Orpheus et Linus; quorum utrumque dis genitum, alterum vero, quia rudes quoque atque agrestes animos admiratione mulceret, non feras modo sed saxa etiam silvasque duxisse posteritatis memoriae traditum est.", "st": "1.10.9"}, {"sp": "N", "t": "Itaque et Timagenes auctor est, omnium in litteris studiorum antiquissimam musicen extitisse, et testimonio sunt clarissimi poetae, apud quos inter regalia convivia laudes heroum ac deorum ad citharam canebantur. lopas vero ille Vergilii nonne <em>canit errantem lunam solisque labores<\/em> et cetera? Quibus certe palam confirmat auctor eminentissimus, musicen cum divinarum etiam rerum cognitione esse coniunctam.", "st": "1.10.10"}, {"sp": "N", "t": "Quod si datur, erit etiam oratori necessaria, siquidem (ut diximus) haec quoque pars, quae ab oratoribus relicta a philosophis est occupata, nostri operis fuit, ac sine omnium talium scientia non potest esse perfecta eloquentia.", "st": "1.10.11"}, {"sp": "N", "t": "Atque claros nomine sapientiae viros, nemo dubitaverit, studiosos musices fuisse, cum Pythagoras atque eum secuti acceptam sine dubio antiquitus opinionem vulgaverint, mundum ipsum ratione esse compositum, quam postea sit lyra imitata, nec illa modo contenti dissimilium concordia, quam vocant ἁρμονίαν, sonum quoque iis motibus dederint.", "st": "1.10.12"}, {"sp": "N", "t": "Nam Plato, cum in aliis quibusdam tum praecipue in Timaeo, ne intelligi quidem nisi ab iis, qui hanc quoque partem disciplinae diligenter perceperint, potest. De philosophis loquor, quorum fons ipse Socrates iam senex institui lyra non erubescebat?", "st": "1.10.13"}, {"sp": "N", "t": "Duces maximos et fidibus et tibiis cecinisse traditum et exercitus Lacedaemoniorum musicis accensos modis. Quid autem aliud in nostris legionibus cornua ac tubae faciunt? quorum concentus quanto est vehementior, tantum Romana in bellis gloria ceteris praestat.", "st": "1.10.14"}, {"sp": "N", "t": "Non igitur frustra Plato civili viro, quem πολιτικὸν vocat, necessariam musicen credidit. Et eius sectae, quae aliis severissima aliis asperrima videtur, principes in hac fuere sententia, ut existimarent sapientium aliquos nonnullam operam his studiis accommodaturos. Et Lycurgus, durissimarum Lacedaemoniis legum auctor, musices disciplinam probavit.", "st": "1.10.15"}, {"sp": "N", "t": "Atque eam natura ipsa videtur ad tolerandos facilius labores velut muneri nobis dedisse, si quidem et remigem cantus hortatur; nec solum in iis operibus, in quibus plurium conatus praeeunte aliqua iucunda voce conspirat, sed etiam singulorum fatigatio quamlibet se rudi modulatione solatur.", "st": "1.10.16"}, {"sp": "N", "t": "Laudem adhuc dicere artis pulcherrimae videor, nondum eam tamen oratori coniungere. Transeamus igitur id quoque, quod grammatice quondam ac musice iunctae fuerunt; siquidem Archytas atque Euenus etiam subiectam grammaticen musicae putaverunt, et eosdem utriusque rei praeceptores fuisse cum Sophron ostendit, mimorum quidem scriptor sed quem Plato adeo probavit, ut suppositos capiti libros eius,", "st": "1.10.17"}, {"sp": "N", "t": "cum moreretur, habuisse credatur, tum Eupolis, apud quem Prodamus et musicen et litteras docet, et Maricas, qui est Hyperbolus, nihil se ex musice scire nisi litteras confitetur. Aristophanes quoque non uno libro sic institui pueros antiquitus solitos esse demonstrat, et apud Menandrum in Hypobolimaeo senex, qui reposcenti filium patri velut rationem impendiorum, quae in educationem contulerit, exponens, psaltis se et geometris multa dicit dedisse.", "st": "1.10.18"}, {"sp": "N", "t": "Unde etiam ille mos, ut in conviviis post cenam circumferretur lyra; cuius cum se imperitum Themistocles confessus esset ut verbis Ciceronis utar, <em>est habitus indoctior.<\/em>", "st": "1.10.19"}, {"sp": "N", "t": "Sed veterum quoque Romanorum epulis fides ac tibias adhibere moris fuit. Versus quoque Saliorum habent carmen. Quae cum omnia sint a Numa rege instituta, faciunt manifestum, ne illis quidem, qui rudes ac bellicosi videntur, cura musices, quantum illa recipiebat aetas, defuisse.", "st": "1.10.20"}, {"sp": "N", "t": "Denique in proverbium usque Graecorum celebratum est, indoctos a Musis atque a Gratiis abesse.", "st": "1.10.21"}, {"sp": "N", "t": "Verum quid ex ea proprie petat futurus orator, disseramus. Numeros musice duplices habet in vocibus et in corpore, utriusque enim rei aptus quidam modus desideratur. Vocis rationem Aristoxenus musicus dividit in ῥυθμόν et μέλος, quorum alterum modulatione, alterum canore ac sonis constat. Num igitur non haec omnia oratori necessaria? quorum unum ad gestum, alterum ad collocationem verborum, tertium ad flexus vocis, qui sunt in agendo quoque plurimi, pertinet:", "st": "1.10.22"}, {"sp": "N", "t": "nisi forte in carminibus tantum et in canticis exigitur structura quaedam et inoffensa copulatio vocum, in agendo supervacua est; aut non compositio et sonus in oratione quoque varie pro rerum modo adhibetur sicut in musice.", "st": "1.10.23"}, {"sp": "N", "t": "Namque et voce et modulatione grandia elate, iucunda dulciter, moderata leniter canit, totaque arte consentit cum eorum quae dicuntur adfectibus.", "st": "1.10.24"}, {"sp": "N", "t": "Atqui in orando quoque intentio vocis, remissio, flexus pertinet ad movendos audientium adfectus, aliaque et collocationis et vocis (ut eodem utar verbo) modulatione concitationem iudicis, alia misericordiam petimus; cum etiam organis, quibus sermo exprimi non potest, adfici animos in diversum habitum sentiamus.", "st": "1.10.25"}, {"sp": "N", "t": "Corporis quoque aptus et decens motus, qui dicitur εὐρυθμία, et est necessarius nec aliunde peti potest; in quo pars actionis non minima consistit, qua de re sepositus nobis est locus.", "st": "1.10.26"}, {"sp": "N", "t": "Age, non habebit imprimis curam vocis orator? Quid tam musices proprium? Sed ne haec quidem praesumenda pars est. Uno interim contenti simus exemplo C. Gracchi, praecipui suorum temporum oratoris, cui contionanti consistens post eum musicus fistula, quam τονάριον vocant, modos, quibus deberet intendi, monstrabat.", "st": "1.10.27"}, {"sp": "N", "t": "Haec ei cura inter turbidissimas actiones vel terrenti optimates vel iam timenti fuit. Libet propter quosdam imperitiores etiam crassiore, ut vocant, Musa dubitationem huius utilitatis eximere.", "st": "1.10.28"}, {"sp": "N", "t": "Nam poetas certe legendos oratori futuro concesserint: num igitur hi sine musice? ac si quis tam caecus animi est, ut de allis dubitet, illos certe, qui carmina ad lyram composuerunt. Haec diutius forent dicenda, si hoc studium velut novum praeciperem.", "st": "1.10.29"}, {"sp": "N", "t": "Cum vero antiquitus usque a Chirone atque Achille ad nostra tempora apud omnes, qui modo legitimam disciplinam non sint perosi, duraverit, non est committendum, ut illa dubia faciam defensionis sollicitudine.", "st": "1.10.30"}, {"sp": "N", "t": "Quamvis autem satis iam ex ipsis, quibus sum modo usus, exemplis credam esse manifestum, quae mihi et quatenus musice placeat, apertius tamen profitendum puto, non hanc a me praecipi, quae nunc in scenis effeminata et impudicis modis fracta non ex parte minima, si quid in nobis virilis roboris manebat, excidit, sed qua laudes fortium canebantur, quaque ipsi fortes canebant; nec psalteria et spadicas, etiam virginibus prolis recusanda, sed cognitionem rationis, quae ad movendos leniendosque adfectus plurimum valet.", "st": "1.10.31"}, {"sp": "N", "t": "Nam et Pythagoran accepimus concitatos ad vim pudicae domui adferendam iuvenes, iussa mutare in spondeum modos tibicina, composuisse; et Chrysippus etiam nutricum illi, quae adhibetur infantibus, adlectationi suum quoddam carmen assignat.", "st": "1.10.32"}, {"sp": "N", "t": "Est etiam non inerudite ad declamandum ficta materia, in qua ponitur tibicen, qui sacrificanti Phrygium cecinerat, acto illo in insaniam et per praecipitia delato accusari, quod causa mortis extiterit; quae si dici debet ab oratore nec dici citra scientiam musices potest, quomodo non hanc quoque artem necessariam esse operi nostro vel iniqui consentient?", "st": "1.10.33"}, {"sp": "N", "t": "In geometria partem fatentur esse utilem teneris aetatibus. Agitari namque animos et acui ingenia et celeritatem percipiendi venire inde concedunt, sed prodesse eam non ut ceteras artes, cum perceptae sint, sed cum discatur, existimant: ea vulgaris opinio est.", "st": "1.10.34"}, {"sp": "N", "t": "Nec sine causa summi viri etiam impensam huic scientiae operam dederunt. Nam cum sit geometria divisa in numeros atque formas, numerorum quidem notitia non oratori modo, sed cuicunque saltem primis litteris erudito necessaria est. In causis vero vel frequentissime versari solet; in quibus actor, non dico, si circa summas trepidat, sed si digitorum saltem incerto aut indecoro gestu a computatione dissentit, iudicatur indoctus.", "st": "1.10.35"}, {"sp": "N", "t": "Ilia vero linearis ratio et ipsa quidem cadit frequenter in causas (nam de terminis mensurisque sunt lites), sed habet maiorem quandam aliam cum arte oratoria cognationem.", "st": "1.10.36"}, {"sp": "N", "t": "Iam primum ordo est geometriae necessarius; nonne et eloquentiae? Ex prioribus geometria probat insequentia, ex certis incerta; nonne id in dicendo facimus? Quid? illa propositarum quaestionum conclusio non fere tota constat syllogismis? Propter quod plures invenias, qui dialecticae similem quam qui rhetoricae fateantur hanc artem. Verum et orator etiamsi raro non tamen nunquam probabit dialectice.", "st": "1.10.37"}, {"sp": "N", "t": "Nam et syllogismo, si res poscet, utetur et certe enthymemate, qui rhetoricus est syllogismus. Denique probationum quae sunt potentissimae γραμμικαὶ ἀποδείξεις vulgo dicuntur: quid autem magis oratio quam probationem petit?", "st": "1.10.38"}, {"sp": "N", "t": "Falsa quoque veris similia geometrica ratione deprehendit. Fit hoc et in numeris per quasdam, quas ψευδογραφίας vocant, quibus pueri ludere solebamus. Sed alia maiora sunt. Nam quis non ita proponenti credat? Quorum locorum extremae lineae eandem mensuram colligunt, eorum spatium quoque, quod iis lineis continetur, par sit necesse est.", "st": "1.10.39"}, {"sp": "N", "t": "At id falsum est. Nam plurimum refert, cuius sit formae ille circuitus; reprehensique a geometris sunt historici, qui magnitudinem insularum satis significari navigationis ambitu crediderunt. Nam ut quaeque forma perfectissima ita capacissima est.", "st": "1.10.40"}, {"sp": "N", "t": "Ideoque illa circumcurrens linea si efficiet orbem, quae forma est in planis maxime perfecta, amplius spatium complectetur quam si quadratum paribus oris efficiat, rursus quadrata triangulis, triangula ipsa plus aequis lateribus quam inaequalibus.", "st": "1.10.41"}, {"sp": "N", "t": "Sed alia forsitan obscuriora; nos facillimum etiam imperitis sequamur experimentum. lugeri mensuram ducentos et quadraginta longitudinis pedes esse dimidioque in latitudinem patere, non fere quisquam est qui ignoret, et qui sit circuitus et quantum campi claudat, colligere expeditum.", "st": "1.10.42"}, {"sp": "N", "t": "At centeni et octogeni in quamque partem pedes idem spatium extremitatis sed multo amplius clausae quattuor lineis areae faciunt. Id si computare quem piget, brevioribus numeris idem discat. Nam deni in quadram pedes, quadraginta per oram, intra centum erunt. At si quini deni per latera, quini in fronte sint, ex illo, quod amplectuntur, quartam deducent eodem circumductu.", "st": "1.10.43"}, {"sp": "N", "t": "Si vero porrecti utrinque undeviceni singulis distent, non plures intus quadratos habebunt, quam per quot longitudo ducetur; quae circumibit autem linea, eiusdem spatii erit, cuius ea quae centum continet. Ita quidquid formae quadrati detraxeris, amplitudini quoque peribit.", "st": "1.10.44"}, {"sp": "N", "t": "Ergo etiam id fieri potest, ut maiore circuitu minor loci amplitudo claudatur. Haec in planis. Nam in collibus vallibusque etiam imperito patet plus soli esse quam caeli.", "st": "1.10.45"}, {"sp": "N", "t": "Quid quod se eadem geometria tollit ad rationem usque mundi? in qua, cum siderum certos constitutosque cursus numeris docet, discimus nihil esse inordinatum atque fortuitum; quod ipsum nonnunquam pertinere ad oratorem potest.", "st": "1.10.46"}, {"sp": "N", "t": "An vero, cum Pericles Athenienses solis obscuratione territos redditis eius rei causis metu liberavit, aut cum Sulpicius ille Gallus in exercitu L. Paulli de lunae defectione disseruit, ne velut prodigio divinitus facto militum animi terrerentur, non videtur usus esse oratoris officio?", "st": "1.10.47"}, {"sp": "N", "t": "Quod si Nicias in Sicilia scisset, non eodem confusus metu pulcherrimum Atheniensium exercitum perdidisset; sicut Dion, cum ad destruendam Dionysii tyrannidem venit, non est tali casu deterritus. Sint extra licet usus bellici, transeamusque, quod Archimedes unus obsidionem Syracusarum in longius traxit.", "st": "1.10.48"}, {"sp": "N", "t": "Illud utique iam proprium ad efficiendum quod intendimus, plurimas quaestiones, quibus difficilior alia ratione explicatio est, ut de ratione dividendi, de sectione in infinitum, de celeritate augenda, linearibus illis probationibus solvi solere; ut, si est oratori (quod proximus demonstrabit liber) de omnibus rebus dicendum, nullo modo sine geometria esse possit orator.", "st": "1.10.49"}, {"sp": "N", "t": "Dandum aliquid comoedo quoque, dum eatenus, qua pronuntiandi scientiam futurus orator desiderat. Non enim puerum, quem in hoc instituimus, aut femineae vocis exilitate frangi volo aut seniliter tremere.", "st": "1.11.1"}, {"sp": "N", "t": "Nec vitia ebrietatis effingat neque servili vernilitate imbuatur nec amoris, avaritiae, metus discat adfectum; quae neque oratori sunt necessaria et mentem, praecipue in aetate prima teneram adhuc et rudem, inficiunt.", "st": "1.11.2"}, {"sp": "N", "t": "Nam frequens imitatio transit in mores. Ne gestus quidem omnis ac motus a comoedis petendus est. Quanquam enim utrumque eorum ad quendam modum praestare debet orator, plurimum tamen aberit a scenico, nec vultu nec manu nec excursionibus nimius. Nam si qua in his ars est dicentium, ea prima est, ne ars esse videatur.", "st": "1.11.3"}, {"sp": "N", "t": "Quod est igitur huius doctoris officium? In primis vitia si qua sunt oris emendet, ut expressa sint verba, ut suis quaeque litterae sonis enuntientur. Quarundam enim vel exilitate vel pinguitudine nimia laboramus, quasdam velut acriores parum efficimus et aliis non dissimilibus sed quasi hebetioribus permutamus.", "st": "1.11.4"}, {"sp": "N", "t": "Quippe et Rho litterae, qua Demosthenes quoque laboravit, Labda succedit (quarum vis est apud nos quoque); et cum c ac similiter g non evaluerunt, in <em>t<\/em> ac <em>d<\/em> molliuntur.", "st": "1.11.5"}, {"sp": "N", "t": "Ne illas quidem circa <em>s<\/em> litteram delicias hic magister feret, nec verba in faucibus patietur audiri nec oris inanitate resonare nec, quod minime sermoni puro conveniat, simplicem vocis naturam pleniore quodam sono circumliniri, quod Graeci καταπεπλασμένον dicunt.", "st": "1.11.6"}, {"sp": "N", "t": "Sic appellatur cantus tibiarum, quae praeclusis quibus clarescunt foraminibus, recto modo exitu graviorem spiritum reddunt.", "st": "1.11.7"}, {"sp": "N", "t": "Curabit etiam, ne extremae syllabae intercidant, ut par sibi sermo sit, ut, quotiens exclamandum erit, lateris conatus sit ille non capitis, ut gestus ad vocem, vultus ad gestum accommodetur.", "st": "1.11.8"}, {"sp": "N", "t": "Observandum erit etiam, ut recta sit facies dicentis, ne labra distorqueantur, ne immodicus hiatus rictum discindat, ne supinus vultus, ne deiecti in terram oculi, ne inclinata utrolibet cervix. Nam frons pluribus generibus peccat.", "st": "1.11.9"}, {"sp": "N", "t": "Vidi multos, quorum supercilia ad singulos vocis conatus adlevarentur, aliorum constricta, aliorum etiam dissidentia, cum alterum in verticem tenderent, altero paene oculus ipse premeretur.", "st": "1.11.10"}, {"sp": "N", "t": "Infinitum autem, ut mox dicemus, in his quoque rebus momentum est; et nihil potest placere quod non decet.", "st": "1.11.11"}, {"sp": "N", "t": "Debet etiam docere comoedus, quomodo narrandum, qua sit auctoritate suadendum, qua concitatione consurgat ira, qui flexus deceat miserationem. Quod ita optime faciet, si certos ex comoediis elegerit locos et ad hoc maxime idoneos, id est, actionibus similes.", "st": "1.11.12"}, {"sp": "N", "t": "Iidem autem non ad pronuntiandum modo utilissimi verum ad augendam quoque eloquentiam maxime accommodati erunt.", "st": "1.11.13"}, {"sp": "N", "t": "Et haec, dum infirma aetas maiora non capiet; ceterum, cum legere orationes oportebit, cum virtutes earum iam sentiet, tum mihi diligens aliquis ac peritus adsistat, neque solum lectionem formet, verum ediscere etiam electa ex iis cogat et ea dicere stantem clare et quemadmodum agere oportebit, ut protinus pronuntiationem, vocem, memoriam exerceat.", "st": "1.11.14"}, {"sp": "N", "t": "Ne illos quidem reprehendendos puto, qui paulum etiam palaestricis vacaverunt. Non de his loquor, quibus pars vitae in oleo, pars in vino consumitur, qui corporum cura mentem obruerunt (hos enim abesse ab eo quem instituimus quam longissime velim);", "st": "1.11.15"}, {"sp": "N", "t": "sed nomen est idem iis, a quibus gestus motusque formantur, ut recta sint brachia, ne indoctae rusticae manus, ne status indecorus, ne qua in proferendis pedibus inscitia, ne caput oculique ab alia corporis inclinatione dissideant.", "st": "1.11.16"}, {"sp": "N", "t": "Nam neque haec esse in parte pronuntiationis negaverit quisquam, neque ipsam pronuntiationem ab oratore secernet, et certe, quod facere oporteat, non indignandum est discere, cum praesertim haec chironomia, quae est, ut nomine ipso declaratur, lex gestus, et ab illis temporibus heroicis orta sit et a summis Graeciae viris atque ipso etiam Socrate probata, a Platone quoque in parte civilium posita virtutum et a Chrysippo in praeceptis de liberorum educatione compositis non omissa.", "st": "1.11.17"}, {"sp": "N", "t": "Nam Lacedaemonios quidem etiam saltationem quandam tanquam ad bella quoque utilem habuisse inter exercitationes accepimus. Neque id veteribus Romanis dedecori fuit; argumentum est sacerdotum nomine ac religione durans ad hoc tempus saltatio, et illa in tertio Ciceronis de Oratore libro verba Crassi, quibus praecipit, ut orator utatur <em>laterum inclinatione forti ac virili, non a scena et histrionibus sed ab armis aut etiam a palaestra;<\/em> cuius disciplinae usus in nostram usque aetatem sine reprehensione descendit.", "st": "1.11.18"}, {"sp": "N", "t": "A me tamen nec ultra pueriles annos retinebitur nec in his ipsis diu. Neque enim gestum oratoris componi ad similitudinem saltationis volo, sed subesse aliquid ex hac exercitatione puerili, unde nos non id agentes furtim decor ille discentibus traditus prosequatur.", "st": "1.11.19"}, {"sp": "N", "t": "Quaeri solet, an, etiamsi discenda sint haec, eodem tempore tamen tradi omnia et percipi possint. Negant enim quidam, quia confundatur animus ac fatigetur tot disciplinis in diversum tendentibus, ad quas nec mens nec corpus nec dies ipse sufficiat, et si maxime patiatur hoc aetas robustior, pueriles annos onerari non oporteat.", "st": "1.12.1"}, {"sp": "N", "t": "Sed non satis perspiciunt, quantum natura humani ingenii valeat; quae ita est agilis ac velox, sic in omnem partem, ut ita dixerim, spectat, ut ne possit quidem aliquid agere tantum unum, in plura vero non eodem die modo, sed eodem temporis momento vim suam intendat.", "st": "1.12.2"}, {"sp": "N", "t": "An vero citharoedi non simul et memoriae et sono vocis et plurimis flexibus serviunt, cum interim alios nervos dextra percurrunt, alios laeva trahunt, continent, praebent, ne pes quidem otiosus certam legem temporum servat, et haec pariter omnia?", "st": "1.12.3"}, {"sp": "N", "t": "Quid? nos agendi subita necessitate deprehensi nonne alia dicimus, alia providemus, cum pariter inventio rerum, electio verborum, compositio, gestus, pronuntiatio, vultus, motus desiderentur? Quae si velut sub uno conatu tam diversa parent simul, cur non pluribus curis horas partiamur? cum praesertim reficiat animos ac reparet varietas ipsa, contraque sit aliquanto difficilius in labore uno perseverare. Ideo et stilus lectione requiescit, et ipsius lectionis taedium vicibus levatur.", "st": "1.12.4"}, {"sp": "N", "t": "Quamlibet multa egerimus, quodam tamen modo recentes sumus ad id quod incipimus. Quis non obtundi potest, si per totum diem cuiuscunque artis unum magistrum ferat? Mutatione recreabitur sicut in cibis, quorum diversitate reficitur stomachus et pluribus minore fastidio alitur.", "st": "1.12.5"}, {"sp": "N", "t": "Aut dicant isti mihi, quae sit alia ratio discendi. Grammatico soli deserviamus, deinde geometrae tantum, omittamus interim quod didicimus? mox transeamus ad musicum, excidant priora? et cum Latinis studebimus litteris, non respiciamus ad Graecas, et, ut semel finiam, nihil faciamus nisi novissimum?", "st": "1.12.6"}, {"sp": "N", "t": "Cur non idem suademus agricolis, ne arva simul et vineta et oleas et arbustum colant, ne pratis et pecoribus et hortis et alvearibus avibusque accommodent curam? Cur ipsi aliquid forensibus negotiis, aliquid desideriis amicorum, aliquid rationibus domesticis, aliquid curae corporis, nonnihil voluptatibus cotidie damus? quarum nos una res quaelibet nihil intermittentes fatigaret. Adeo facilius est multa facere quam diu.", "st": "1.12.7"}, {"sp": "N", "t": "Illud quidem minime verendum est, ne laborem studiorum pueri difficilius tolerent, neque enim ulla aetas minus fatigatur. Mirum sit forsitan, sed experimentis deprehendas.", "st": "1.12.8"}, {"sp": "N", "t": "Nam et dociliora sunt ingenia, priusquam obduruerunt. Id vel hoc argumento patet, quod intra biennium, quam verba recte formare potuerunt, quamvis nullo instante, omnia fere loquuntur; at noviciis nostris per quot annos sermo Latinus repugnat. Magis scias, si quem iam robustum instituere litteris coeperis, non sine causa dici παιδομαθεῖς eos, qui in sua quidque arte optime faciant.", "st": "1.12.9"}, {"sp": "N", "t": "Et patientior est laboris natura pueris quam iuvenibus. Videlicet, ut corpora infantium nec casus, quo in terram totiens deferuntur, tam graviter adfligit nec illa per manus et genua reptatio nec post breve tempus continui lusus et totius diei discursus, quia pondus illis abest nec sese ipsi gravant: sic animi quoque, credo, quia minore conatu moventur nec suo nisu studiis insistunt, sed formandos se tantummodo praestant, non similiter fatigantur.", "st": "1.12.10"}, {"sp": "N", "t": "Praeterea secundum aliam aetatis illius facilitatem velut simplicius docentes sequuntur nec quae iam egerint metiuntur. Abest illis adhuc etiam laboris iudicium. Porro, ut frequenter experti sumus, minus adficit sensus fatigatio quam cogitatio.", "st": "1.12.11"}, {"sp": "N", "t": "Sed ne temporis quidem unquam plus erit, quia his aetatibus omnis in audiendo profectus est. Cum ad stilum secedet, cum generabit ipse aliquid atque componet, tum inchoare haec studia vel non vacabit vel non libebit.", "st": "1.12.12"}, {"sp": "N", "t": "Ergo cum grammaticus totum occupare diem non possit nec debeat, ne discentis animum taedio avertat, quibus potius studiis haec temporum velut subsiciva donabimus?", "st": "1.12.13"}, {"sp": "N", "t": "Nam nec ego consumi studentem in his artibus volo, nec moduletur aut musicis notis cantica excipiat, nec utique ad minutissima usque geometriae opera descendat, non comoedum in pronuntiando nec saltatorem in gestu facio; quae si omnia exigerem, suppeditabat tamen tempus. Longa est enim, quae discit, aetas, et ego non de tardis ingeniis loquor.", "st": "1.12.14"}, {"sp": "N", "t": "Denique cur in his omnibus, quae discenda oratori futuro puto, eminuit Plato? qui non contentus disciplinis, quas praestare poterant Athenae, non Pythagoreorum, ad quos in Italiam navigaverat, Aegypti quoque sacerdotes adiit atque eorum arcana perdidicit.", "st": "1.12.15"}, {"sp": "N", "t": "Difficultatis patrocinia praeteximus segnitiae. Neque enim nobis operis amor est, nec, quia sit honesta ac rerum pulcherrima eloquentia, petitur ipsa, sed ad venalem usum et sordidum lucrum accingimur.", "st": "1.12.16"}, {"sp": "N", "t": "Dicant sine his in foro multi et adquirant, dum sit locupletior aliquis sordidae mercis negotiator et plus voci suae debeat praeco. Nec velim quidem lectorem dari mihi quid studia referant computaturum.", "st": "1.12.17"}, {"sp": "N", "t": "Qui vero imaginem ipsam eloquentiae divina quadam mente conceperit, quique illam (ut ait non ignobilis tragicus) <em>reginam rerum orationem<\/em> ponet ante oculos, fructumque non ex stipe advocationum sed ex animo suo et contemplatione ac scientia petet perpetuum illum nec fortunae subiectum, facile persuadebit sibi, ut tempora, quae spectaculis, campo, tesseris, otiosis denique sermonibus, ne dicam somno et conviviorum mora conteruntur, geometrae potius ac musico impendat, quanto plus delectationis habiturus quam ex illis ineruditis voluptatibus.", "st": "1.12.18"}, {"sp": "N", "t": "Dedit enim hoc providentia hominibus munus, ut honesta magis iuvarent. Sed nos haec ipsa dulcedo longius duxit. Hactenus ergo de studiis, quibus, antequam maiora capiat, puer instituendus est; proximus liber velut novum sumet exordium et ad rhetoris officia transibit.", "st": "1.12.19"}, {"sp": "HDR", "t": "Liber II", "st": "2"}, {"sp": "N", "t": "Tenuit consuetudo, quae cotidie magis invalescit, ut praeceptoribus eloquentiae, Latinis quidem semper sed etiam Graecis interim, discipuli serius quam ratio postulat, traderentur. Eius rei duplex causa est, quod et rhetores utique nostri suas partes omiserunt et grammatici alienas occupaverunt.", "st": "2.1.1"}, {"sp": "N", "t": "Nam et illi declamare modo et scientiam declamandi ac facultatem tradere officii sui ducunt, idque intra deliberativas iudicialesque materias (nam cetera ut professione sua minora despiciunt), et hi non satis credunt excepisse, quae relicta erant, (quo nomine gratia quoque iis habenda est), sed ad prosopopoeias usque ac suasorias, in quibus onus dicendi vel maximum est, irrumpunt.", "st": "2.1.2"}, {"sp": "N", "t": "Hinc ergo accidit, ut, quae alterius artis prima erant opera, facta sint alterius novissima, et aetas altioribus iam disciplinis debita in schola minore subsidat ac rhetoricen apud grammaticos exerceat. Ita, quod est maxime ridiculum, non ante ad declamandi magistrum mittendus videtur puer quam declamare sciat. Nos suum cuique professioni modum demus.", "st": "2.1.3"}, {"sp": "N", "t": "Et grammatice (quam in Latinum transferentes litteraturam vocaverunt) fines suos norit, praesertim tantum ab hac appellationis suae paupertate, intra quam primi illi constitere, provecta; nam tenuis a fonte assumptis historicorum criticorumque viribus pleno iam satis alveo fluit, cum praeter rationem recte loquendi non parum alioqui copiosam prope omnium maximarum artium scientiam amplexa sit;", "st": "2.1.4"}, {"sp": "N", "t": "et rhetorice, cui nomen vis eloquendi dedit, officia sua non detrectet nec occupari gaudeat pertinentem ad se laborem, quae, dum opere cedit,", "st": "2.1.5"}, {"sp": "N", "t": "iam paene possessione depulsa est. Neque infitiabor, aliquem ex his, qui grammaticen profiteantur, eo usque scientiae progredi posse, ut ad haec quoque tradenda sufficiat; sed cum id aget, rhetoris officio fungetur non suo.", "st": "2.1.6"}, {"sp": "N", "t": "Nos porro quaerimus, quando iis, quae rhetorice praecipit, percipiendis puer maturus esse videatur. In quo quidem non id est aestimandum, cuius quisque sit aetatis, sed quantum in studiis iam effecerit.", "st": "2.1.7"}, {"sp": "N", "t": "Et ne diutius disseram, quando sit rhetori tradendus, sic optime finiri credo; cum poterit. Sed hoc ipsum ex superiore pendet quaestione. Nam si grammatices munus usque ad suasorias prorogatur, tardius rhetore opus est. At si rhetor prima officia operis sui non recusat,", "st": "2.1.8"}, {"sp": "N", "t": "a narrationibus statim et laudandi vituperandique opusculis cura eius desideratur. An ignoramus antiquis hoc fuisse ad augendam eloquentiam genus exercitationis, ut theses dicerent et communes locos et cetera citra complexum rerum personarumque, quibus verae fictaeque controversiae continentur? Ex quo palam est, quam turpiter deserat eam partem rhetorices institutio, quam et primam habuit et diu solam.", "st": "2.1.9"}, {"sp": "N", "t": "Quid autem est ex iis, de quibus supra dixi, quod non cum in alia, quae sunt propria rhetorum, tum certe in illud iudiciale causae genus incidat?", "st": "2.1.10"}, {"sp": "N", "t": "An non in foro narrandum est? qua in parte nescio an sit vel plurimum. Non laus ac vituperatio certaminibus illis frequenter inseritur? Non communes loci, sive qui sunt in vitia derecti, quales legimus a Cicerone compositos, seu quibus quaestiones generaliter tractantur, quales sunt editi a Quinto quoque Hortensio: ut, <em>Sitne parvis argumentis credendum,<\/em>", "st": "2.1.11"}, {"sp": "N", "t": "et pro testibus et in testes, in mediis litium medullis versantur? Arma sunt haec quodammodo praeparanda semper, ut iis, cum res poscet, utare. Quae qui pertinere ad orationem non putabit, is ne statuam quidem inchoari credet, cum eius membra fundentur. Neque hanc (ut aliqui putabunt) festinationem meam sic quisquam calumnietur, tanquam eum, qui sit rhetori traditus, abducendum protinus a grammaticis putem.", "st": "2.1.12"}, {"sp": "N", "t": "Dabuntur et illis tum quoque tempora sua, neque erit verendum, ne binis praeceptoribus oneretur puer. Non enim crescet sed dividetur, qui sub uno miscebatur, labor, et erit sui quisque operis magister utilior; quod adhuc obtinent Graeci, a Latinis omissum est, et fieri videtur excusate, quia sunt qui labori isti successerint.", "st": "2.1.13"}, {"sp": "N", "t": "Ergo cum ad eas in studiis vires pervenerit puer, ut, quae prima esse praecepta rhetorum diximus, mente consequi possit, tradendus eius artis magistris erit;", "st": "2.2.1"}, {"sp": "N", "t": "quorum in prinis inspici mores oportebit. Quod ego non idcirco potissimum in hac parte tractare sum aggressus, quia non in ceteris quoque doctoribus idem hoc examinandum quam diligentissime putem, sicut testatus sum libro priore; sed quod magis necessariam eius rei mentionem facit aetas ipsa discentium.", "st": "2.2.2"}, {"sp": "N", "t": "Nam et adulti fere pueri ad hos praeceptores transferuntur et apud eos iuvenes etiam facti perseverant; ideoque maior adhibenda tum cura est, ut et teneriores annos ab iniuria sanctitas docentis custodiat et ferociores a licentia gravitas deterreat.", "st": "2.2.3"}, {"sp": "N", "t": "Neque vero sat est summam praestare abstinentiam, nisi disciplinae severitate convenientium quoque ad se mores astrinxerit.", "st": "2.2.4"}, {"sp": "N", "t": "Sumat igitur ante omnia parentis erga discipulos suos animum, ac succedere se in eorum locum, a quibus sibi liberi tradantur, existimet. Ipse nec habeat vitia nec ferat. Non austeritas eius tristis, non dissoluta sit comitas, ne inde odium hinc contemptus oriatur. Plurimus ei de honesto ac bono sermo sit; nam quo saepius monuerit, hoc rarius castigabit. Minime iracundus, nec tamen eorum, quae emendanda erunt, dissimulator, simplex in docendo, patiens laboris,", "st": "2.2.5"}, {"sp": "N", "t": "assiduus potius quam immodicus. Interrogantibus libenter respondeat, non interrogantes percontetur ultro. In laudandis discipulorum dictionibus nec malignus nec effusus, quia res altera taedium laboris,", "st": "2.2.6"}, {"sp": "N", "t": "altera securitatem parit. In emendando, quae corrigenda erunt, non acerbus minimeque contumeliosus; nam id quidem multos a proposito studendi fugat, quod quidam sic obiurgant quasi oderint.", "st": "2.2.7"}, {"sp": "N", "t": "Ipse aliquid immo multa cotidie dicat, quae secum auditores referant. Licet enim satis exemplorum ad imitandum ex lectione suppeditet, tamen viva illa, ut dicitur, vox alit plenius praecipueque eius praeceptoris, quem discipuli, si modo recte sunt instituti, et amant et verentur. Vix autem dici potent, quanto libentius imitemur eos, quibus favemus.", "st": "2.2.8"}, {"sp": "N", "t": "Minime vero permittenda pueris, ut fit apud plerosque, adsurgendi exultandique in laudando licentia; quin etiam iuvenum modicum esse, cum audient, testimonium debet. Ita fiet, ut ex iudicio praeceptoris discipulus pendeat,", "st": "2.2.9"}, {"sp": "N", "t": "atque id se dixisse recte, quod ab eo probabitur, credat. Illa vero vitiosissima, quae iam humanitas vocatur, invicem qualiacunque laudandi, cum est indecora et theatralis et severe institutis scholis aliena, tum studiorum perniciosissima hostis. Supervacua enim videntur cura ac labor, parata, quidquid effuderint,", "st": "2.2.10"}, {"sp": "N", "t": "laude. Vultum igitur praeceptoris intueri tam, qui audiunt, debent, quam ipse qui dicit; ita enim probanda atque improbanda discernet,", "st": "2.2.11"}, {"sp": "N", "t": "si stilo facultas continget, auditione indicium. At nunc proni atque succincti ad omnem clausulam non exsurgunt modo uerum etiam excurrunt et cum indecora exultatione conclamant. Id mutuum est et ibi declamationis fortuna. Hinc tumor et vana de se persuasio usque adeo, ut illo condiscipulorum tumultu inflati, si parum a praeceptore laudentur, ipsi de illo male sentiant.", "st": "2.2.12"}, {"sp": "N", "t": "Sed se quoque praeceptores intente ac modeste audiri velint; non enim iudicio discipulorum dicere debet magister sed discipulus magistri. Quin, si fieri potest, intendendus animus in hoc quoque, ut perspiciat, quae quisque et quomodo laudet, et placere, quae bene dicet, non suo magis quam eorum nomine delectetur, qui recte iudicabunt.", "st": "2.2.13"}, {"sp": "N", "t": "Pueros adolescentibus permixtos sedere, non placet mihi. Nam etiamsi vir talis, qualem esse oportet studiis moribusque praepositum, modestam habere potest etiam iuventutem, tamen vel infirmitas a robustioribus separanda est, et carendum non solum crimine turpitudinis verum etiam suspicione.", "st": "2.2.14"}, {"sp": "N", "t": "Haec notanda breviter existimavi; nam ut absit ab ultimis vitiis ipse ac schola, ne praecipiendum quidem credo. Ac si quis est, qui flagitia manifesta in eligendo filii praeceptore non vitet, iam hinc sciat cetera quoque, quae ad utilitatem iuventutis componere conamur, esse sibi hac parte omissa supervacua.", "st": "2.2.15"}, {"sp": "N", "t": "Ne illorum quidem persuasio silentio transeunda est, qui, etiam cum idoneos rhetori pueros putaverunt, non tamen continuo tradendos eminentissimo credunt, sed apud minores aliquamdiu detinent, tanquam instituendis artibus magis sit apta mediocritas praeceptoris, cum ad intellectum atque ad imitationem facilior tum ad suscipiendas elementorum molestias minus superba.", "st": "2.3.1"}, {"sp": "N", "t": "Qua in re mihi non arbitror diu laborandum, ut ostendam, quanto sit melius optimis imbui, quanta in eluendis quae semel insederint vitiis difficultas consequatur, cum geminatum onus succedentes premat et quidem edocendi gravius ac prius quam docendi.", "st": "2.3.2"}, {"sp": "N", "t": "Propter quod Timotheum clarum in arte tibiarum ferunt duplices ab iis, quos alius instituisset, solitum exigere mercedes, quam si rudes traderentur. Error tamen est in re duplex: unus, quod interim sufficere illos minores existimant, et bono sane stomacho contenti sunt;", "st": "2.3.3"}, {"sp": "N", "t": "quae quanquam est ipsa reprehensione digna securitas, tamen esset utcunque tolerabilis, si eiusmodi praeceptores minus docerent non peius; alter ille etiam frequentior, quod eos, qui ampliorem dicendi facultatem sint consecuti, non putant ad minora descendere, idque interim fieri, quia fastidiant praestare hanc inferioribus curam,", "st": "2.3.4"}, {"sp": "N", "t": "interim quia omnino non possint. Ego porro eum qui nolit in numero praecipientium non habeo, posse autem maxime, si velit, optimum quemque contendo; primum, quod eum, qui eloquentia ceteris praestet, illa quoque, per quae ad eloquentiam pervenitur, diligentissime percepisse credibile est;", "st": "2.3.5"}, {"sp": "N", "t": "deinde, quia plurimum in praecipiendo valet ratio, quae doctissimo cuique plenissima est; postremo, quia nemo sic in maioribus eminet, ut eum minora deficiant. Nisi forte Iovem quidem Phidias optime fecit, illa autem, quae in ornamentum operis eius accedunt, alius melius elaborasset, aut orator loqui nesciet aut leviores morbos curare non poterit praestantissimus medicus.", "st": "2.3.6"}, {"sp": "N", "t": "Quid ergo? non est quaedam eloquentia maior quam ut eam intellectu consequi puerilis infirmitas possit? Ego vero confiteor: sed hunc disertum praeceptorem prudentem quoque et non ignarum docendi esse oportebit summittentem se ad mensuram discentis; ut velocissimus quoque, si forte iter cum parvulo faciat, det manum et gradum suum minuat nec procedat ultra quam comes possit.", "st": "2.3.7"}, {"sp": "N", "t": "Quid? si plerumque accidit ut faciliora sint ad intelligendum et lucidiora multo, quae a doctissimo quoque dicuntur? Nam et prima est eloquentiae virtus perspicuitas, et quo quis ingenio minus valet, hoc se magis attollere et dilatare conatur, ut statura breves in digitos eriguntur et plura infirmi minantur.", "st": "2.3.8"}, {"sp": "N", "t": "Nam tumidos et corruptos et tinnulos et quocunque alio cacozeliae genere peccantes certum habeo non virium sed infirmitatis vitio laborare, ut corpora non robore sed valetudine inflantur et recto itinere lassi plerumque devertunt. Erit ergo etiam obscurior, quo quisque deterior.", "st": "2.3.9"}, {"sp": "N", "t": "Non excidit mihi, scripsisse me in libro priore, cum potiorem in scholis eruditionem esse quam domi dicerem, libentius se prima studia tenerosque profectus ad imitationem condiscipulorum, quae facilior esset, erigere; quod a quibusdam sic accipi potest, tanquam haec, quam nunc tueor,", "st": "2.3.10"}, {"sp": "N", "t": "sententia priori diversa sit. Id a me procul aberit; namque ea causa vel maxima est, cur optimo cuique praeceptori sit tradendus puer, quod apud eum discipuli quoque melius instituti aut dicent, quod inutile non sit imitari, aut si quid erraverint, statim corrigentur;", "st": "2.3.11"}, {"sp": "N", "t": "at indoctus ille etiam probabit fortasse vitiosa et placere audientibus iudicio suo coget. Sit ergo tam eloquentia quam moribus praestantissimus, qui ad Phoenicis Homerici exemplum dicere ac facere doceat.", "st": "2.3.12"}, {"sp": "N", "t": "Hinc iam, quas primas in docendo partes rhetorum putem, tradere incipiam, dilata parumper illa quae sola vulgo vocatur arte rhetorica. Ac mihi opportunus maxime videtur ingressus ab eo, cuius aliquid simile apud grammaticos puer didicerit.", "st": "2.4.1"}, {"sp": "N", "t": "Et quia narrationum, excepta qua in causis utimur, tres accepimus species, fabulam, quae versatur in tragoediis atque carminibus, non a veritate modo sed etiam a forma veritatis remota; argumentum, quod falsum sed vero simile comoediae fingunt; historiam, in qua est gestae rei expositio; grammaticis autem poeticas dedimus:", "st": "2.4.2"}, {"sp": "N", "t": "apud rhetorem initium sit historica, tanto robustior quanto verior. Sed narrandi quidem quae nobis optima ratio videatur, tum demonstrabimus, cum de iudiciali parte dicemus. Interim admonere illud satis est, ut sit ea neque arida prorsus atque ieiuna, (nam quid opus erat tantum studiis laboris impendere, si res nudas atque inornatas indicare satis videretur?) neque rursus sinuosa et arcessitis descriptionibus, in quas plerique imitatione poeticae licentiae ducuntur, lasciviat.", "st": "2.4.3"}, {"sp": "N", "t": "Vitium utrumque, peius tamen illud, quod ex inopia quam quod ex copia venit. Nam in pueris oratio perfecta nec exigi nec sperari potest; melior autem indoles laeta generosique conatus et vel plura iusto concipiens interim spiritus.", "st": "2.4.4"}, {"sp": "N", "t": "Nec unquam me in his discentis annis offendat, si quid superfuerit. Quin ipsis quoque doctoribus hoc esse curae velim, ut teneras adhuc mentes more nutricum mollius alant et satiari velut quodam iucundioris disciplinae lacte patiantur.", "st": "2.4.5"}, {"sp": "N", "t": "Erit illud plenius interim corpus, quod mox adulta aetas astringat. Hinc spes roboris. Maciem namque et infirmitatem in posterum minari solet protinus omnibus membris expressus infans. Audeat haec aetas plura et inveniat et inventis gaudeat, sint licet illa non satis sicca interim ac severa. Facile remedium est ubertati;", "st": "2.4.6"}, {"sp": "N", "t": "sterilia nullo labore vincuntur. Ilia mihi in pueris natura minimum spei dederit, in qua ingenium iudicio praesumitur. Materiam esse primum volo vel abundantiorem atque ultra quam oporteat fusam. Multum inde decoquent anni, multum ratio limabit, aliquid velut usu ipso deteretur, sit modo unde excidi possit et quod exsculpi; erit autem, si non ab initio tenuem nimium laminam duxerimus et quam caelatura altior rumpat.", "st": "2.4.7"}, {"sp": "N", "t": "Quod me de his aetatibus sentire minus mirabitur, qui apud Ciceronem legerit: <em>Volo enim se efferat in adolescente fecunditas.<\/em> Quapropter in primis evitandus et in pueris praecipue magister aridus, non minus quam teneris adhuc plantis siccum et sine humore ullo solum.", "st": "2.4.8"}, {"sp": "N", "t": "Inde fiunt humiles statim et velut terram spectantes, qui nihil supra cotidianum sermonem attollere audeant. Macies illis pro sanitate et iudicii loco infirmitas est, et dum satis putant vitio carere, in id ipsum incidunt vitium, quod virtutibus carent. Quare mihi ne maturitas quidem ipsa festinet, nec musta in lacu statim austera sint; sic et annos ferent et vetustate proficient.", "st": "2.4.9"}, {"sp": "N", "t": "Ne illud quidem quod admoneamus indignum est, ingenia puerorum nimia interim emendationis severitate deficere; nam et desperant et dolent et novissime oderunt et, quod maxime nocet, dum omnia timent, nihil conantur.", "st": "2.4.10"}, {"sp": "N", "t": "Quod etiam rusticis notum est, qui frondibus teneris non putant adhibendam esse falcem, quia reformidare ferrum videntur et nondum cicatricem pati posse.", "st": "2.4.11"}, {"sp": "N", "t": "Iucundus ergo tum maxime debet esse praeceptor, ut remedia, quae alioqui natura sunt aspera, molli manu leniantur; laudare aliqua, ferre quaedam, mutare etiam, reddita cur id fiat ratione, illuminare interponendo aliquid sui. Nonnunquam hoc quoque erit utile, ipsum totas dictare materias, quas et imitetur puer et interim tanquam suas amet.", "st": "2.4.12"}, {"sp": "N", "t": "At si tam negligens ei stilus fuerit, ut emendationem non recipiat; expertus sum prodesse, quotiens eandem materiam rursus a me tractatam scribere de integro iuberem; posse enim adhuc eum melius, quatenus nullo magis studia quam spe gaudent.", "st": "2.4.13"}, {"sp": "N", "t": "Aliter autem alia aetas emendanda est, et pro modo virium et exigendum et corrigendum opus. Solebam ego dicere pueris aliquid ausis licentius aut laetius, laudare illud me adhuc, venturum tempus, quo idem non permitterem; ita et ingenio gaudebant et iudicio non fallebantur.", "st": "2.4.14"}, {"sp": "N", "t": "Sed ut eo revertar, unde sum digressus: narrationes stilo componi quanta maxima possit adhibita diligentia volo. Nam ut primo, cum sermo instituitur, dicere quae audierint utile est pueris ad loquendi facultatem, ideoque et retro agere expositionem et a media in utramque partem discurrere sane merito cogantur, sed ad gremium praeceptoris, et dum aliud non possunt et dum res ac verba connectere incipiunt, ut protinus memoriam firment: ita cum iam formam rectae atque emendatae orationis accipient, extemporalis garrulitas nec exspectata cogitatio et vix surgendi mora circulatoriae vere iactationis est.", "st": "2.4.15"}, {"sp": "N", "t": "Hinc parentium imperitorum inane gaudium, ipsis vero contemptus operis et inverecunda frons et consuetudo pessime dicendi et malorum exercitatio et, quae magnos quoque profectus frequenter perdidit, arrogans de se persuasio innascitur.", "st": "2.4.16"}, {"sp": "N", "t": "Erit suum parandae facilitati tempus, nec a nobis negligenter locus iste transibitur. Interim satis est, si puer omni cura et summo, quantum illa aetas capit, labore aliquid probabile scripserit; in hoc assuescat, huius sibi rei naturam faciat. Ille demum in id, quod quaerimus, aut ei proximum poterit evadere, qui ante discet recte dicere quam cito.", "st": "2.4.17"}, {"sp": "N", "t": "Narrationibus non inutiliter subiungitur opus destruendi confirmandique eas, quod ἀνασκευή et κατασκευή vocatur. Id porro non tantum in fabulosis et carmine traditis fieri potest, verum etiam in ipsis annalium monumentis; ut, si quaeratur, an sit credibile super caput Valeri pugnantis sedisse corvum, qui os oculosque hostis Galli rostro atque alis everberaret, sit in utramque partem ingens ad dicendum materia;", "st": "2.4.18"}, {"sp": "N", "t": "aut de serpente, quo Scipio traditur genitus, et lupa Romuli et Egeria Numae. Nam Graecis historiis plerumque poeticae similis licentia est. Saepe etiam quaeri solet de tempore, de loco quo gesta res dicitur, nonnunquam de persona quoque; sicut Livius frequentissime dubitat, et alii ab aliis historici dissentiunt.", "st": "2.4.19"}, {"sp": "N", "t": "Inde paulatim ad maiora tendere incipiet, laudare claros viros et vituperare improbos, quod non simplicis utilitatis opus est. Namque et ingenium exercetur multiplici variaque materia, et animus contemplatione recti pravique formatur, et multa inde cognitio rerum venit exemplisque, quae sunt in omni genere causarum potentissima, iam tum instruit, cum res poscet, usurum.", "st": "2.4.20"}, {"sp": "N", "t": "Hinc illa quoque exercitatio subit comparationis, uter melior uterve deterior; quae quanquam versatur in ratione simili, tamen et duplicat materiam et virtutum vitiorumque non tantum naturam, sed etiam modum tractat. Verum de ordine laudis contraque, quoniam tertia haec rhetorices pars est, praecipiemus suo tempore.", "st": "2.4.21"}, {"sp": "N", "t": "Communes loci (de iis loquor, quibus citra personas in ipsa vitia moris est perorare, ut in adulterum, aleatorem, petulantem) ex mediis sunt iudiciis et, si reum adiicias, accusationes; quanquam hi quoque ab illo generali tractatu ad quasdam deduci species solent, ut si ponatur adulter caecus, aleator pauper, petulans senex. Habent autem nonnunquam etiam defensionem.", "st": "2.4.22"}, {"sp": "N", "t": "Nam et pro luxuria et pro amore dicimus, et leno interim parasitusque defenditur sic, ut non homini patrocinemur, sed crimini.", "st": "2.4.23"}, {"sp": "N", "t": "Theses autem, quae sumuntur ex rerum comparatione, ut rusticane vita an urbana potior, iurisperiti an militaris viri laus maior, mire sunt ad exercitationem dicendi speciosae atque uberes, quae vel ad suadendi officium vel etiam ad iudiciorum disceptationem iuvant plurimum. Nam posterior ex praedictis locus in causa Murenae copiosissime a Cicerone tractatur.", "st": "2.4.24"}, {"sp": "N", "t": "Sunt et illae paene totae ad deliberativum pertinentes genus, ducendane uxor, petendine sint magistratus. Namque et hae personis modo adiectis suasoriae erunt.", "st": "2.4.25"}, {"sp": "N", "t": "Solebant praeceptores mei neque inutili et nobis etiam iucundo genere exercitationis praeparare nos coniecturalibus causis, cum quaerere atque exsequi iuberent, <em>Cur armata apud Lacedaemonios Venus,<\/em> et <em>Quid ita crederetur Cupido puer atque volucer et sagittis ac face armatus,<\/em> et similia, in quibus scrutabamur voluntatem, cuius in controversiis frequens quaestio est, quod genus chriae videri potest.", "st": "2.4.26"}, {"sp": "N", "t": "Nam locos quidem, quales sunt de testibus, semperne his credendum, et de argumentis, an habenda etiam parvis fides, adeo manifestum est ad forenses actiones pertinere, ut quidam neque ignobiles in officiis civilibus scriptos eos memoriaeque diligentissime mandatos in promptu habuerint, ut quotiens esset occasio, extemporales eorum dictiones his velut emblematis exornarentur.", "st": "2.4.27"}, {"sp": "N", "t": "Quo quidem (neque enim eius rei iudicium differre sustineo) summam videbantur mihi infirmitatem de se confiteri. Nam quid ii possint in causis, quarum varia et nova semper est facies, proprium invenire? quomodo propositis ex parte adversa respondere, altercationibus velociter occurrere, testem rogare? qui etiam in iis, quae sunt communia et in plurimis causis tractantur, vulgatissimos sensus verbis nisi tanto ante praeparatis prosequi nequeant.", "st": "2.4.28"}, {"sp": "N", "t": "Necesse vero iis, cum eadem iudiciis pluribus dicunt, aut fastidium moveant velut frigidi et repositi cibi, aut pudorem deprehensa totiens audientium memoria infelix supellex, quae sicut apud pauperes ambitiosos pluribus et diversis officiis conteratur:", "st": "2.4.29"}, {"sp": "N", "t": "cum eo quidem quod vix ullus est tam communis locus, qui possit cohaerere cum causa nisi aliquo propriae quaestionis vinculo copulatus; appareat alioqui non tam insertum quam adplicitum,", "st": "2.4.30"}, {"sp": "N", "t": "vel quod dissimilis est ceteris vel quod plerumque adsumi etiam parum apte solet, non quia desideratur sed quia paratus est: ut quidam sententiarum gratia verbosissimos locos arcessunt, cum ex locis debeat nasci sententia.", "st": "2.4.31"}, {"sp": "N", "t": "Ita sunt autem speciosa haec et utilia, si oriuntur ex causa; ceterum quamlibet pulchra elocutio, nisi ad victoriam tendit, utique supervacua, sed interim etiam contraria est. Verum hactenus evagari satis fuerit.", "st": "2.4.32"}, {"sp": "N", "t": "Legum laus ac vituperatio iam maiores ac prope summis operibus suffecturas vires desiderant; quae quidem suasoriis an controversiis magis accommodata sit exercitatio, consuetudine et iure civitatium differt. Apud Graecos enim lator earum ad iudicem vocabatur, Romanis pro contione suadere ac dissuadere moris fuit. Utroque autem modo pauca de his et fere certa dicuntur. Nam et genera sunt tria, sacri, publici, privati iuris.", "st": "2.4.33"}, {"sp": "N", "t": "Quae divisio ad laudem magis spectat, si quis eam per gradus augeat, quod lex, quod publica, quod ad religionem deum comparata sit. Ea quidem, de quibus quaeri solet, communia omnibus.", "st": "2.4.34"}, {"sp": "N", "t": "Aut enim de iure dubitari potest eius, qui rogat, ut de P. Clodi, qui non rite creatus tribunus arguebatur; aut de ipsius rogationis, quod est varium, sive non trino forte nundino promulgata sive non idoneo die, sive contra intercessionem vel auspicia aliudve quid, quod legitimis obstet, dicitur lata esse vel ferri, sive alicui manentium legum repugnare.", "st": "2.4.35"}, {"sp": "N", "t": "Sed haec ad illas primas exercitationes non pertinent; nam sunt hae citra complexum personarum, temporum, causarum. Reliqua eadem fere vero fictoque huiusmodi certamine tractantur.", "st": "2.4.36"}, {"sp": "N", "t": "Nam vitium aut in verbis aut in rebus est. In verbis quaeritur, an satis significent, an sit in iis aliquid ambiguum; in rebus, an lex sibi ipsa consentiat, an in praeteritum ferri debeat, an in singulos homines. Maxime vero commune est quaerere, an sit honesta, an utilis.", "st": "2.4.37"}, {"sp": "N", "t": "Nec ignore, plures fieri a plerisque partes; sed nos iustum, pium, religiosum, ceteraque his similia honesto complectimur. Iusti tamen species non simpliciter excuti solent. Aut enim de re ipsa quaeritur, ut dignane poena vel praemio sit, aut de modo praemii poenaeve, qui tam maior quam minor culpari potest.", "st": "2.4.38"}, {"sp": "N", "t": "Utilitas quoque interim natura discernitur, interim tempore. Quaedam an obtineri possint, ambigi solet. Ne illud quidem ignorare oportet, leges aliquando totas, aliquando ex parte reprehendi solere, cum exemplum rei utriusque nobis claris orationibus praebeatur.", "st": "2.4.39"}, {"sp": "N", "t": "Nec me fallit, eas quoque leges esse, quae non in perpetuum rogentur, sed de honoribus aut imperiis, qualis Manilia fuit, de qua Ciceronis oratio est. Sed de his nihil hoc loco praecipi potest; constant enim propria rerum, de quibus agitur, non communi qualitate.", "st": "2.4.40"}, {"sp": "N", "t": "His fere veteres facultatem dicendi exercuerunt assumpta tamen a dialecticis argumentandi ratione. Nam fictas ad imitationem fori consiliorumque materias apud Graecos dicere circa Demetrium Phalerea institutum fere constat.", "st": "2.4.41"}, {"sp": "N", "t": "An ab ipso id genus exercitationis sit inventum, ut alio quoque libro sum confessus, parum comperi; sed ne ii quidem, qui hoc fortissime adfirmant, ullo satis idoneo auctore nituntur. Latinos vero dicendi praeceptores extremis L. Crassi temporibus coepisse Cicero auctor est; quorum insignis maxime Plotius fuit.", "st": "2.4.42"}, {"sp": "N", "t": "Sed de ratione declamandi post paulum. Interim, quia prima rhetorices rudimenta tractamus, non omittendum videtur id quoque, ut moneam, quantum sit collaturus ad profectum discentium rhetor, si, quemadmodum a grammaticis exigitur poetarum enarratio, ita ipse quoque historiae atque etiam magis orationum lectione susceptos a se discipulos instruxerit; quod nos in paucis, quorum id aetas exigebat et parentes utile esse crediderant, servavimus.", "st": "2.5.1"}, {"sp": "N", "t": "Ceterum sentientibus iam tum optima duae res impedimento fuerunt, quod et longa consuetudo aliter docendi fecerat legem, et robusti fere iuvenes nec hunc laborem desiderantes exemplum nostrum sequebantur.", "st": "2.5.2"}, {"sp": "N", "t": "Nec tamen, etiamsi quid novi vel sero invenissem, praecipere in posterum puderet. Nunc vero scio id fieri apud Graecos sed magis per adiutores, quia non videntur tempora suffectura, si legentibus singulis praeire semper ipsi velint.", "st": "2.5.3"}, {"sp": "N", "t": "Et hercule praelectio, quae in hoc adhibetur, ut facile atque distincte pueri scripta oculis sequantur, etiam illa, quae vim cuiusque verbi, si quod minus usitatum incidat, docet, multum infra rhetoris officium existimanda est.", "st": "2.5.4"}, {"sp": "N", "t": "At demonstrare virtutes vel, si quando ita incidat, vitia, id professionis eius atque promissi, quo se magistrum eloquentiae pollicetur, maxime proprium est, eo quidem validius, quod non utique hunc laborem docentium postulo, ut ad gremium revocatis cuius quisque eorum velit libri lectione deserviant.", "st": "2.5.5"}, {"sp": "N", "t": "Nam mihi cum facilius tum etiam multo videtur magis utile, facto silentio unum aliquem (quod ipsum imperari per vices optimum est) constituere lectorem, ut protinus pronuntiationi quoque assuescant; tum exposita causa, in quam scripta legetur oratio,", "st": "2.5.6"}, {"sp": "N", "t": "(nam sic clarius quae dicentur intelligi poterunt) nihil otiosum pati, quodque in inventione quodque in elocutione adnotandum erit, quae in prooemio conciliandi iudicis ratio, quae narrandi lux, brevitas, fides, quod aliquando consilium et quam occulta calliditas (namque ea sola in hoc ars est,", "st": "2.5.7"}, {"sp": "N", "t": "quae intelligi nisi ab artifice non possit); quanta deinceps in dividendo prudentia, quam subtilis et crebra argumentatio, quibus viribus inspiret, qua iucunditate permulceat, quanta in maledictis asperitas, in iocis urbanitas, ut denique dominetur in adfectibus atque in pectora irrumpat animumque iudicum similem iis, quae dicit, efficiat.", "st": "2.5.8"}, {"sp": "N", "t": "Tum in ratione eloquendi, quod verbum proprium, ornatum, sublime; ubi amplificatio laudanda, quae virtus ei contraria, quid speciose translatum, quae figura verborum, quae levis et quadrata sed virilis tamen compositio.", "st": "2.5.9"}, {"sp": "N", "t": "Ne id quidem inutile, etiam corruptas aliquando et vitiosas orationes, quas tamen plerique iudiciorum pravitate mirantur, legi palam ostendique in his, quam multa impropria, obscura, tumida, humilia, sordida, lasciva, effeminata sint; quae non laudantur modo a plerisque, sed, quod est peius, propter hoc ipsum, quod sunt prava, laudantur.", "st": "2.5.10"}, {"sp": "N", "t": "Nam sermo rectus et secundum naturam enuntiatus nihil habere ex ingenio videtur; illa vero, quae utcunque deflexa sunt, tanquam exquisitiora miramur; non aliter quam distortis et quocunque modo prodigiosis corporibus apud quosdam maius est pretium quam iis, quae nihil ex communi habitu boni perdiderunt.", "st": "2.5.11"}, {"sp": "N", "t": "Atque etiam qui specie capiuntur, vulsis levatisque et inustas comas acu comentibus et non suo colore nitidis plus esse formae putant, quam possit tribuere incorrupta natura, ut pulchritudo corporis venire videatur ex malis morum.", "st": "2.5.12"}, {"sp": "N", "t": "Neque solum haec ipse debebit docere praeceptor sed frequenter interrogare et iudicium discipulorum experiri. Sic audientibus securitas aberit nec quae dicentur superfluent aures, simulque ad id perducentur, quod ex hoc quaeritur, ut inveniant ipsi et intelligant. Nam quid aliud agimus docendo eos, quam ne semper docendi sint?", "st": "2.5.13"}, {"sp": "N", "t": "Hoc diligentiae genus ausim dicere plus collaturum discentibus quam omnes omnium artes, quae iuvant sine dubio multum; sed latiore quadam comprehensione per omnes quidem species rerum cotidie paene nascentium ire qui possunt?", "st": "2.5.14"}, {"sp": "N", "t": "Sicut de re militari, quanquam sunt tradita quaedam praecepta communia, magis tamen proderit scire, qua ducum quisque ratione, in quali re, tempore, loco sit sapienter usus aut contra. Nam in omnibus fere minus valent praecepta quam experimenta.", "st": "2.5.15"}, {"sp": "N", "t": "An vero declamabit quidem praeceptor, ut sit exemplo suis auditoribus; non plus contulerint lecti Cicero aut Demosthenes? Corrigetur palam, si quid in declamando discipulus erraverit; non potentius erit emendare orationem, quin immo etiam iucundius? Aliena enim vitia reprehendi quisque mavult quam sua.", "st": "2.5.16"}, {"sp": "N", "t": "Nec deerant plura, quae dicerem; sed neminem haec utilitas fugit, atque utinam tam non pigeat facere istud quam non displicebit.", "st": "2.5.17"}, {"sp": "N", "t": "Quod si potuerit obtineri, non ita difficilis supererit quaestio, qui legendi sint incipientibus. Nam quidam illos minores, quia facilior intellectus videbatur, probaverunt; alii floridius genus, ut ad alenda primarum aetatum ingenia magis accommodatum.", "st": "2.5.18"}, {"sp": "N", "t": "Ego optimos quidem et statim et semper sed tamen eorum candidissimum quemque et maxime expositum velim, ut Livium a pueris magis quam Sallustium, etsi hic historiae maior est auctor,", "st": "2.5.19"}, {"sp": "N", "t": "ad quem tamen intelligendum iam profectu opus sit. Cicero, ut mihi quidem videtur, et iucundus incipientibus quoque et apertus est satis, nec prodesse tantum sed etiam amari potest, tum (quemadmodum Livius praecipit) ut quisque erit Ciceroni simillimus.", "st": "2.5.20"}, {"sp": "N", "t": "Duo autem genera maxime cavenda pueris puto: unum, ne quis eos antiquitatis nimius admirator in Gracchorum Catonisque et aliorum similium lectione durescere velit; fient enim horridi atque ieiuni; nam neque vim eorum adhuc intellectu consequentur et elocutione, quae tum sine dubio erat optima, sed nostris temporibus aliena est, contenti, quod est pessimum,", "st": "2.5.21"}, {"sp": "N", "t": "similes sibi magnis viris videbuntur Alterum, quod huic diversum est, ne recentis huius lasciviae flosculis capti voluptate prava deleniantur, ut praedulce illud genus et puerilibus ingeniis hoc gratius, quo propius est, adament.", "st": "2.5.22"}, {"sp": "N", "t": "Firmis autem iudiciis iamque extra periculum positis suaserim et antiquos legere, ex quibus si assumatur solida ac virilis ingenii vis, deterso rudis saeculi squalore, tum noster hic cultus clarius enitescet, et novos,", "st": "2.5.23"}, {"sp": "N", "t": "quibus et ipsis multa virtus adest. Neque enim nos tarditatis natura damnavit, sed dicendi mutavimus genus et ultra nobis quam oportebat indulsimus; ita non tam ingenio illi nos superarunt quam proposito.", "st": "2.5.24"}, {"sp": "N", "t": "Multa ergo licebit eligere; sed curandum erit, ne iis, quibus permixta sunt, inquinentur. Quosdam vero etiam, quos totos imitari oporteat, et fuisse nuper et nunc esse,", "st": "2.5.25"}, {"sp": "N", "t": "quidni libenter non modo concesserim, verum etiam contenderim? Sed hi qui sint, non cuiuscunque est pronuntiare. Tutius circa priores vel erratur, ideoque hanc novorum distuli lectionem, ne imitatio iudicium antecederet.", "st": "2.5.26"}, {"sp": "N", "t": "Fuit etiam in hoc diversum praecipientium propositum, quod eorum quidam materias, quas discipulis ad dicendum dabant, non contenti divisione dirigere latius dicendo prosequebantur, nec solum probationibus implebant sed etiam adfectibus.", "st": "2.6.1"}, {"sp": "N", "t": "Alii, cum primas modo lineas duxissent, post declamationes, quid omisisset quisque, tractabant; quosdam vero locos non minore cura, quam cum ad dicendum ipsi surgerent, excolebant. Utile utrumque, et ideo neutrum ab altero separo; sed si facere tantum alterum necesse sit, plus proderit demonstrasse rectam protinus viam quam revocare ab errore iam lapsos:", "st": "2.6.2"}, {"sp": "N", "t": "primum quia emendationem auribus modo accipiunt, divisionem vero ad cogitationem etiam et stilum perferunt; deinde quod libentius praecipientem audiunt quam reprehendentem. Si qui vero paulo sunt vivaciores, in his praesertim moribus, etiam irascuntur admonitioni et taciti repugnant. Neque ideo tamen minus vitia aperte coarguenda sunt.", "st": "2.6.3"}, {"sp": "N", "t": "Habenda enim ratio ceterorum, qui recta esse, quae praeceptor non emendaverit, credent. Utraque autem ratio miscenda est et ita tractanda, ut ipsae res postulabunt.", "st": "2.6.4"}, {"sp": "N", "t": "Namque incipientibus danda erit velut praeformata materia secundum cuiusque vires; at cum satis composuisse sese ad exemplum videbuntur, brevia quaedam demonstranda vestigia, quae persecuti iam suis viribus sine adminiculo progredi possint.", "st": "2.6.5"}, {"sp": "N", "t": "Nonnunquam credi sibi ipsos oportebit, ne mala consuetudine semper alienum laborem sequendi nihil per se conari et quaerere sciant. Quodsi satis prudenter dicenda viderint, iam prope consummata fuerit praecipientis opera; at si quid erraverint adhuc, erunt ad ducem reducendi.", "st": "2.6.6"}, {"sp": "N", "t": "Cui rei simile quiddam facientes aves cernimus, quae teneris infirmisque fetibus cibos ore suo collatos partiuntur; at cum visi sunt adulti, paulum egredi nidis et circumvolare sedem illam praecedentes ipsae docent, tum expertas vires libero caelo suaeque ipsorum fiduciae permittunt.", "st": "2.6.7"}, {"sp": "N", "t": "Illud ex consuetudine mutandum prorsus existimo in iis, de quibus nunc disserimus, aetatibus, ne omnia quae scripserint ediscant et certa, ut moris est, die dicant; quod quidem maxime patres exigunt atque ita demum studere liberos suos, si quam frequentissime declamaverint, credunt, cum profectus praecipue diligentia constet.", "st": "2.7.1"}, {"sp": "N", "t": "Nam ut scribere pueros plurimumque esse in hoc opere plane velim, sic ediscere electos ex orationibus vel historiis aliove quo genere dignorum ea cura voluminum locos, multo magis suadeam.", "st": "2.7.2"}, {"sp": "N", "t": "Nam et exercebitur acrius memoria aliena complectendo quam sua; et qui erunt in difficiliore huius laboris genere versati, sine molestia quae ipsi composuerint iam familiaria animo suo adfigent, et adsuescent optimis semperque habebunt intra se, quod imitentur; et iam non sentientes formam orationis illam, quam mente penitus acceperint, expriment.", "st": "2.7.3"}, {"sp": "N", "t": "Abundabunt autem copia verborum optimorum et compositione et figuris iam non quaesitis sed sponte et ex reposito velut thesauro se offerentibus. Accedit his et iucunda in sermone bene a quoque dictorum relatio et in causis utilis. Nam et plus auctoritatis adferunt ea, quae non praesentis gratia litis sunt comparata, et laudem saepe maiorem quam si nostra sint conciliant.", "st": "2.7.4"}, {"sp": "N", "t": "Aliquando tamen permittendum quae ipsi scripserint dicere, ut laboris sui fructum etiam ex illa quae maxime petitur laude plurium capiant. Verum id quoque tum fieri oportebit, cum aliquid commodius elimaverint, ut eo velut praemio studii sui donentur ac se meruisse ut dicerent gaudeant.", "st": "2.7.5"}, {"sp": "N", "t": "Virtus praeceptoris haberi solet nec immerito diligenter in iis, quos erudiendos susceperit, notare discrimina ingeniorum et, quo quemque natura maxime ferat, scire. Nam est in hoc incredibilis quaedam varietas nec pauciores animorum paene quam corporum formae.", "st": "2.8.1"}, {"sp": "N", "t": "Quod intelligi etiam ex ipsis oratoribus potest, qui tantum inter se distant genere dicendi, ut nemo sit alteri similis, quamvis plurimi se ad eorum quos probabant imitationem composuerint.", "st": "2.8.2"}, {"sp": "N", "t": "Utile deinde plerisque visum est ita quemque instituere, ut propria naturae bona doctrina foverent et in id potissimum ingenia, quo tenderent, adiuvarentur; ut si quis palaestrae peritus, cum in aliquod plenum pueris gymnasium venerit, expertus eorum omni modo corpus animumque discernat, cui quisque certamini praeparandus sit,", "st": "2.8.3"}, {"sp": "N", "t": "ita praeceptorem eloquentiae, cum sagaciter fuerit intuitus, cuius ingenium presso limatoque genere dicendi, cuius acri, gravi, dulci, aspero, nitido, urbano maxime gaudeat, ita se commodaturum singulis, ut in eo, quo quisque eminet, provehatur;", "st": "2.8.4"}, {"sp": "N", "t": "quod et adiuta cura natura magis evalescat, et qui in diversa ducatur neque in iis, quibus minus aptus est, satis possit efficere et ea, in quae natus videtur, deserendo faciat infirmiora.", "st": "2.8.5"}, {"sp": "N", "t": "Quod mihi (libera enim vel contra receptas persuasiones rationem sequenti sententia est) in parte verum videtur. Nam proprietates ingeniorum dispicere prorsus necessarium est.", "st": "2.8.6"}, {"sp": "N", "t": "In his quoque certum studiorum facere delectum nemo dissuaserit. Namque erit alius historiae magis idoneus, alius compositus ad carmen, alius utilis studio iuris, ut nonnulli rus fortasse mittendi. Sic discernet haec dicendi magister, quomodo palaestricus ille cursorem faciet aut pugilem aut luctatorem aliudve quid ex iis, quae sunt sacrorum certaminum.", "st": "2.8.7"}, {"sp": "N", "t": "Verum ei, qui foro destinabitur, non in unam partem aliquam sed in omnia, quae sunt eius operis, etiam si qua difficiliora discenti videbuntur, elaborandum est. Nam et omnino supervacua erat doctrina, si natura sufficeret.", "st": "2.8.8"}, {"sp": "N", "t": "An si quis ingenio corruptus ac tumidus, ut plerique sunt, incident, in hoc eum ire patiemur? aridum atque ieiunum non alemus et quasi vestiemus? Nam si quaedam detrahere necessarium est, cur non sit adiicere concessum?", "st": "2.8.9"}, {"sp": "N", "t": "Neque ego contra naturam pugno. Non enim deserendum id bonum, si quod ingenitum est, existimo, sed augendum addendumque quod cessat.", "st": "2.8.10"}, {"sp": "N", "t": "An vero clarissimus ille praeceptor Isocrates, quem non magis libri bene dixisse quam discipuli bene docuisse testantur, cum de Ephoro atque Theopompo sic iudicaret, ut alteri frenis alteri calcaribus opus esse diceret, aut in illo lentiore tarditatem aut in illo paene praecipiti concitationem adiuvandam docendo existimavit, cum alterum alterius natura miscendum arbitraretur?", "st": "2.8.11"}, {"sp": "N", "t": "Imbecillis tamen ingeniis sane sic obsequendum sit, ut tantum in id, quo vocat natura, ducantur; ita enim, quod solum possunt, melius efficient. Si vero liberalior materia contigerit et in qua merito ad spem oratoris simus aggressi, nulla dicendi virtus omittenda est.", "st": "2.8.12"}, {"sp": "N", "t": "Nam licet sit aliquam in partem pronior, ut necesse est, ceteris tamen non repugnabit, atque ea cura paria faciet iis, in quibus eminebat; sicut ille (ne ab eodem exemplo recedamus) exercendi corpora peritus, non, si docendum pancratiasten susceperit, pugno ferire vel calce tantum aut nexus modo atque in iis certos aliquos docebit, sed omnia quae sunt eius certaminis. Erit qui ex his aliqua non possit: in id maxime quod poterit incumbet.", "st": "2.8.13"}, {"sp": "N", "t": "Nam sunt haec duo vitanda prorsus: unum ne temptes quod effici non possit, alterum ne ab eo, quod quis optime facit, in aliud, ad quod minus est idoneus, transferas. At si fuerit qui docebitur ille, quem adolescentes senem vidimus, Nicostratus, omnibus in eo docendi partibus similiter utetur, efficietque illum, qualis hic fuit, luctando pugnandoque, quorum utroque certamine iisdem diebus coronabatur, invictum.", "st": "2.8.14"}, {"sp": "N", "t": "Et quanto id magis oratoris futuri magistro providendum erit? Non enim satis est dicere presse tantum aut subtiliter aut aspere, non magis quam phonasco acutis tantum aut mediis aut gravibus sonis aut horum etiam particulis excellere. Nam sicut cithara ita oratio perfecta non est, nisi ab imo ad summum omnibus intenta nervis consentiat.", "st": "2.8.15"}, {"sp": "N", "t": "Plura de officio docentium locutus discipulos id unum interim moneo, ut praeceptores suos non minus quam ipsa studia ament, et parentes esse non quidem corporum sed mentium credant.", "st": "2.9.1"}, {"sp": "N", "t": "Multum haec pietas conferet studio; nam ita et libenter audient et dictis credent et esse similes concupiscent, in ipsos denique coetus scholarum laeti alacresque convenient, emendati non irascentur, laudati gaudebunt, ut sint carissimi, studio merebuntur.", "st": "2.9.2"}, {"sp": "N", "t": "Nam ut illorum officium est docere, sic horum praebere se dociles; alioqui neutrum sine altero sufficit. Et sicut hominis ortus ex utroque gignentium confertur, et frustra sparseris semina, nisi illa praemollitus foverit sulcus: ita eloquentia coalescere nequit nisi sociata tradentis accipientisque concordia.", "st": "2.9.3"}, {"sp": "N", "t": "In his primis operibus, <em>quae non ipsa parva<\/em> sunt sed maiorum quasi membra atque partes, bene instituto atque exercitato iam fere tempus appetet aggrediendi suasorias iudicialesque materias; quarum antequam viam ingredior, pauca mihi de ipsa ratione declamandi dicenda sunt, quae quidem ut ex omnibus novissime inventa ita multo est utilissima.", "st": "2.10.1"}, {"sp": "N", "t": "Nam et cuncta illa, de quibus diximus, in se fere continet, et veritati proximam imaginem reddit, ideoque ita est celebrata, ut plerisque videretur ad formandam eloquentiam vel sola sufficere. Neque enim virtus ulla perpetuae duntaxat orationis reperiri potest, quae non sit cum hac dicendi meditatione communis.", "st": "2.10.2"}, {"sp": "N", "t": "Eo quidem res ista culpa docentium reccidit, ut inter praecipuas quae corrumperent eloquentiam causas licentia atque inscitia declamantium fuerit. Sed eo, quod natura bonum est, bene uti licet.", "st": "2.10.3"}, {"sp": "N", "t": "Sint ergo et ipsae materiae, quae fingentur, quam simillimae veritatis, et declamatio, in quantum maxime potest, imitetur eas actiones, in quarum exercitationem reperta est.", "st": "2.10.4"}, {"sp": "N", "t": "Nam magos et pestilentiam et responsa et saeviores tragicis novercas aliaque magis adhuc fabulosa frustra inter sponsiones et interdicta quaeremus. Quid ergo? Nunquam haec supra fidem et poetica, ut vere dixerim, themata iuvenibus tractare permittamus, ut exspatientur et gaudeant materia et quasi in corpus eant?", "st": "2.10.5"}, {"sp": "N", "t": "Erit optimum; sed certe sint grandia et tumida, non stulta etiam et acrioribus oculis intuenti ridicula: ut, si iam cedendum est, impleat se declamator aliquando, dum sciat, ut quadrupedes, cum viridi pabulo distentae sunt, sanguinis detractione curantur et sic ad cibos viribus conservandis idoneos redeunt, ita sibi quoque tenuandas adipes, et quidquid humoris corrupti contraxerit, emittendum, si esse sanus ac robustus volet. Alioqui tumor ille inanis primo cuiusque veri operis conatu deprehendetur.", "st": "2.10.6"}, {"sp": "N", "t": "Totum autem declamandi opus qui diversum omni modo a forensibus causis existimant, ii profecto ne rationem quidem, qua ista exercitatio inventa sit, pervident.", "st": "2.10.7"}, {"sp": "N", "t": "Nam si foro non praeparat, aut scenicae ostentationi aut furiosae vociferationi simillimum est. Quid enim attinet iudicem praeparare, qui nullus est; narrare, quod omnes sciant falsum; probationes adhibere causae, de qua nemo sit pronuntiaturus? Et haec quidem otiosa tantum; adfici vero et ira vel luctu permovere, cuius est ludibrii, nisi quibusdam pugnae simulacris ad verum discrimen aciemque iustam consuescimus?", "st": "2.10.8"}, {"sp": "N", "t": "Nihil ergo inter forense genus dicendi atque hoc declamatorium intererit? Si profectus gratia dicimus, nihil. Utinamque adiici ad consuetudinem posset, ut nominibus uteremur, et perplexae magis et longioris aliquando actus controversiae fingerentur, et verba in usu cotidiano posita minus timeremus, et iocos inserere moris esset; quae nos, quamlibet per alia in scholis exercitati simus, tirones in foro inveniunt.", "st": "2.10.9"}, {"sp": "N", "t": "Si vero in ostentationem comparetur declamatio, sane paulum aliquid inclinare ad voluptatem audientium debemus.", "st": "2.10.10"}, {"sp": "N", "t": "Nam et in iis actionibus, quae in aliqua sine dubio veritate versantur, sed sunt ad popularem aptatae delectationem, quales legimus panegyricos, totumque hoc demonstrativum genus, permittitur adhibere plus cultus omnemque artem, quae latere plerumque in iudiciis debet, non confiteri modo sed ostentare etiam hominibus in hoc advocatis.", "st": "2.10.11"}, {"sp": "N", "t": "Quare declamatio, quoniam est iudiciorum consiliorumque imago, similis esse debet veritati; quoniam autem aliquid in se habet ἐπιδεικτικόν nonnihil sibi nitoris assumere.", "st": "2.10.12"}, {"sp": "N", "t": "Quod faciunt actores comici, qui neque ita prorsus, ut nos vulgo loquimur, pronuntiant, quod esset sine arte, neque procul tamen a natura recedunt, quo vitio periret imitatio; sed morem communis huius sermonis decore quodam scenico exornant.", "st": "2.10.13"}, {"sp": "N", "t": "Sic quoque aliqua nos incommoda ex iis, quas finxerimus, materiis consequentur, in eo praecipue, quod multa in iis relinquuntur incerta, quae sumimus ut videtur, aetates, facultates, liberi, parentes, urbium ipsarum vires, iura, mores, alia his similia;", "st": "2.10.14"}, {"sp": "N", "t": "quin aliquando etiam argumentum ex ipsis positionum vitiis ducimus. Sed haec suo quaeque loco. Quamvis enim omne propositum operis a nobis destinati eo spectet, ut orator instituatur, tamen, ne quid studiosi requirant, etiam si quid erit, quod ad scholas proprie pertineat, in transitu non omittemus.", "st": "2.10.15"}, {"sp": "N", "t": "Iam hinc ergo nobis inchoanda est ea pars artis, ex qua capere initium solent, qui priora omiserunt; quanquam video quosdam in ipso statim limine obstaturos mihi, qui nihil egere huiusmodi praeceptis eloquentiam putent, sed natura sua et vulgari modo et scholarum exercitatione contenti rideant etiam diligentiam nostram exemplo magni quoque nominis professorum, quorum aliquis, ut opinor, interrogatus, quid esset σχῆμα et νόημα, nescire se quidem sed, si ad rem pertineret, esse in sua declamatione respondit.", "st": "2.11.1"}, {"sp": "N", "t": "Alius percontanti, Theodoreus an Apollodoreus esset? Ego, inquit, parmularius sum. Nec sane potuit urbanius ex confessione inscitiae suae elabi. Porro hi, quia et beneficio ingenii praestantes sunt habiti et multa etiam memoria digna exclamaverunt, plurimos habent similes negligentiae suae, paucissimos naturae.", "st": "2.11.2"}, {"sp": "N", "t": "Igitur impetu dicere se et viribus uti gloriantur; neque enim opus esse probatione aut dispositione in rebus fictis, sed, cuius rei gratia plenum sit auditorium, sententiis grandibus, quarum optima quaeque a periculo petatur.", "st": "2.11.3"}, {"sp": "N", "t": "Quin etiam in cogitando, nulla ratione adhibita aut tectum intuentes magnum aliquid, quod ultro se offerat, pluribus saepe diebus expectant, aut murmure incerto velut classico instincti concitatissimum corporis motum non enuntiandis sed quaerendis verbis accommodant.", "st": "2.11.4"}, {"sp": "N", "t": "Nonnulli certa sibi initia, priusquam sensum invenerint, destinant, quibus aliquid diserti subiungendum sit, eaque diu secum ipsi clareque meditati desperata conectendi facultate deserunt et ad alia deinceps atque inde alia non minus communia ac nota devertunt.", "st": "2.11.5"}, {"sp": "N", "t": "Qui plurimum videntur habere rationis, non in causas tamen laborem suum sed in locos intendunt, atque in iis non corpori prospiciunt sed abrupta quaedam, ut forte ad manum venere, iaculantur.", "st": "2.11.6"}, {"sp": "N", "t": "Unde fit, ut dissoluta et ex diversis congesta oratio cohaerere non possit similisque sit commentariis puerorum, in quos ea, quae aliis declamantibus laudata sunt, regerunt. Magnas tamen sententias et res bonas, ita enim gloriari solent, elidunt; nam et barbari et servi; et si hoc sat est, nulla est ratio dicendi.", "st": "2.11.7"}, {"sp": "N", "t": "Ne hoc quidem negaverim, sequi plerumque hanc opinionem, ut fortius dicere videantur indocti; primum vitio male iudicantium, qui maiorem habere vim credunt ea, quae non habent artem, ut effringere quam aperire, rumpere quam solvere, trahere quam ducere putant robustius.", "st": "2.12.1"}, {"sp": "N", "t": "Nam et gladiator, qui armorum inscius in rixam ruit, et luctator, qui totius corporis nisu in id, quod semel invasit, incumbit, fortior ab his vocatur; cum interim et hic frequenter suis viribus ipse prosternitur, et illum vehementis impetus excipit adversarii mollis articulus.", "st": "2.12.2"}, {"sp": "N", "t": "Sed sunt in hac parte, quae imperitos etiam naturaliter fallant; nam et divisio, cum plurimum valeat in causis, speciem virium minuit, et rudia politis maiora et sparsa compositis numerosiora creduntur.", "st": "2.12.3"}, {"sp": "N", "t": "Est praeterea quaedam virtutum vitiorumque vicinia, qua maledicus pro libero, temerarius pro forti, effusus pro copioso accipitur. Maledicit autem ineruditus apertius et saepius vel cum periculo suscepti litigatoris, frequenter etiam suo.", "st": "2.12.4"}, {"sp": "N", "t": "Adfert et ista res opinionem, quia libentissime homines audiunt ea, quae dicere ipsi noluissent. Illud quoque alterum quod est in elocutione ipsa periculum minus vitat conaturque perdite, unde evenit nonnunquam, ut aliquid grande inveniat qui semper quaerit quod nimium est; verum id et raro provenit, et cetera vitia non pensat.", "st": "2.12.5"}, {"sp": "N", "t": "Propter hoc quoque interdum videntur indocti copiam habere maiorem, quod dicunt omnia; doctis est et electio et modus. His accedit, quod a cura docendi quod intenderunt recedunt. Itaque illud quaestionum et argumentorum apud corrupta iudicia frigus evitant nihilque aliud, quam quod vel pravis voluptatibus aures assistentium permulceat, quaerunt.", "st": "2.12.6"}, {"sp": "N", "t": "Sententiae quoque ipsae, quas solas petunt, magis eminent, cum omnia circa illas sordida et abiecta sunt; ut lumina non inter umbras, quemadmodum Cicero dicit, sed plane in tenebris clariora sunt. Itaque ingeniosi vocentur, ut libet, dum tamen constet contumeliose sic laudari disertum.", "st": "2.12.7"}, {"sp": "N", "t": "Nihilominus confitendum est etiam detrahere doctrinam aliquid, ut limam rudibus et cotes hebetibus et vino vetustatem, sed vitia detrahit, atque eo solo minus est, quod litterae perpolierunt, quo melius.", "st": "2.12.8"}, {"sp": "N", "t": "Verum hi pronuntiatione quoque famam dicendi fortius quaerunt. Nam et clamant ubique et omnia levata, ut ipsi vocant, manu emugiunt, multo discursu, anhelitu, iactatione gestus, motu capitis furentes.", "st": "2.12.9"}, {"sp": "N", "t": "Iam collidere manus, terrae pedem incutere, femur, pectus, frontem caedere, mire ad pullatum circulum facit; cum ille eruditus, ut in oratione multa summittere, variare, disponere, ita etiam in pronuntiando suum cuique eorum, quae dicet, colori accommodare actum sciat, et, si quid sit perpetua observatione dignum, modestus et esse et videri malit.", "st": "2.12.10"}, {"sp": "N", "t": "At illi hanc vim appellant, quae est potius violentia; cum interim non actores modo aliquos invenias sed, quod est turpius, praeceptores etiam, qui brevem dicendi exercitationem consecuti omissa ratione ut tulit impetus, passim tumultuentur eosque, qui plus honoris litteris tribuerunt, ineptos et ieiunos et trepidos et infirmos, ut quodque verbum contumeliosissimum occurrit, appellent.", "st": "2.12.11"}, {"sp": "N", "t": "Verum illis quidem gratulemur sine labor, sine ratione, sine disciplina disertis; nos, quando et praecipiendi munus iam pridem deprecati sumus et in foro quoque dicendi, quia honestissimum finem putabamus desinere dum desideraremur, inquirendo scribendoque talia consolemur otium nostrum, quae futura usui bonae mentis iuvenibus arbitramur, nobis certe sunt voluptati.", "st": "2.12.12"}, {"sp": "N", "t": "Nemo autem a me exigat id praeceptorum genus, quod est a plerisque scriptoribus artium traditum, ut quasi quasdam leges inmutabili necessitate constrictas studiosis dicendi feram: utique prooemium et id quale, proxima huic narratio, quae lex deinde narrandi, propositio post hanc vel, ut quibusdam placuit, excursio, tum certus ordo quaestionum ceteraque, quae, velut si aliter facere fas non sit, quidam tanquam iussi sequuntur.", "st": "2.13.1"}, {"sp": "N", "t": "Erat enim rhetorice res prorsus facilis ac parva, si uno et brevi praescripto contineretur; sed mutantur pleraque causis, temporibus, occasione, necessitate. Atque ideo res in oratore praecipua consilium est, quia varie et ad rerum momenta convertitur.", "st": "2.13.2"}, {"sp": "N", "t": "Quid si enim praecipias imperatori, quotiens aciem instruat, derigat frontem, cornua utrinque promoveat, equites pro cornibus locet? erit haec quidem rectissima fortasse ratio, quotiens licebit; sed mutabitur natura loci, si mons occurret, si flumen obstabit, collibus, silvis, asperitate alia prohibebitur;", "st": "2.13.3"}, {"sp": "N", "t": "mutabit hostium genus, mutabit praesentis condicio discriminis; nunc acie directa nunc cuneis, Nunc auxiliis nunc legione pugnabitur, nonnunquam terga etiam dedisse simulata fuga proderit.", "st": "2.13.4"}, {"sp": "N", "t": "Ita prooemium necessarium an supervacuum, breve an longius, ad iudicem omni sermone derecto an aliquando averso per aliquam figuram dicendum sit, constricta an latius fusa narratio, continua an divisa, recta an ordine permutato, causae docebunt. Itemque de quaestionum ordine, cum in eadem controversia aliud alii parti prius quaeri frequenter expediat.", "st": "2.13.5"}, {"sp": "N", "t": "Neque enim rogationibus plebisve scitis sancta sunt ista praecepta, sed hoc quidquid est utilitas excogitavit.", "st": "2.13.6"}, {"sp": "N", "t": "Non negabo autem sic utile esse plerumque, alioqui nec scriberem; verum, si eadem illa nobis aliud suadebit utilitas, hanc relictis magistrorum auctoritatibus sequemur.", "st": "2.13.7"}, {"sp": "N", "t": "Equidem id maxime <em>praecipiam ac repetens iterumque iterumque monebo:<\/em> res duas in omni actu spectet orator, quid deceat et quid expediat. Expedit autem saepe mutare ex illo constituto traditoque ordine aliqua et interim decet, ut in statuis atque picturis videmus variari habitus, vultus, status. Nam recti quidem corporis vel minima gratia est;", "st": "2.13.8"}, {"sp": "N", "t": "nempe enim adversa sit facies et demissa brachia et iuncti pedes et a summis ad ima rigens opus. Flexus ille et, ut sic dixerim, motus dat actum quendam et adfectum. Ideo nec ad unum modum formatae manus et in vultu mille species.", "st": "2.13.9"}, {"sp": "N", "t": "Cursum habent quaedam et impetum, sedent alia vel incumbunt; nuda haec, illa velata sunt, quaedam mixta ex utroque. Quid tam distortum et elaboratum quam est ille discobolos Myronis? Si quis tamen, ut parum rectum, improbet opus, nonne ab intellectu artis abfuerit, in qua vel praecipue laudabilis est ipsa illa novitas ac difficultas?", "st": "2.13.10"}, {"sp": "N", "t": "Quam quidem gratiam et delectationem adferunt figurae, quaeque in sensibus quaeque in verbis sunt; mutant enim aliquid a recto atque hanc prae se virtutem ferunt, quod a consuetudine vulgari recesserunt.", "st": "2.13.11"}, {"sp": "N", "t": "Habet in pictura speciem tota facies; Apelles tamen imaginem Antigoni latere tantum altero ostendit, ut amissi oculi deformitas lateret. Quid? non in oratione operienda sunt quaedam, sive ostendi non debent sive exprimi pro dignitate non possunt?", "st": "2.13.12"}, {"sp": "N", "t": "Ut fecit Timanthes, opinor, Cythnius in ea tabula, qua Coloten Teium vicit. Nam cum in Iphigeniae immolatione pinxisset tristem Calchantem, tristiorem Vlixem, addidisset Menelao, quem summum poterat ars efficere, maerorem, consumptis adfectibus, non reperiens, quo digne modo patris vultum posset exprimere, velavit eius caput et suo cuique animo dedit aestimandum.", "st": "2.13.13"}, {"sp": "N", "t": "Nonne huic simile est illud Sallustianum, <em>Nam de Carthagine tacere satius puto quam parum dicere?<\/em> Propter quae mihi semper moris fuit, quam minime alligare me ad praecepta, quae καθολικά vocitant, id est (ut dicamus quomodo possumus) universalia vel perpetualia. Raro enim reperitur hoc genus, ut non labefactari parte aliqua et subrui possit.", "st": "2.13.14"}, {"sp": "N", "t": "Sed de his plenius suo quidque loco tractabimus. Interim nolo se iuvenes satis instructos, si quem ex his, qui breves plerumque circumferuntur, artis libellum edidicerint, et velut decretis technicorum tutos putent. Multo labore, assiduo studio, varia exercitatione, plurimis experimentis, altissima prudentia, praesentissimo consilio constat ars dicendi.", "st": "2.13.15"}, {"sp": "N", "t": "Sed adiuvatur his quoque, si tamen rectam viam, non unam orbitam monstrent; a qua declinare qui crediderit nefas, patiatur necesse est illam per funes ingredientium tarditatem. Itaque et stratum militari labore iter saepe deserimus compendio ducti; et, si rectum limitem rupti torrentibus pontes inciderint, circumire cogemur, et, si ianua tenebitur incendio,", "st": "2.13.16"}, {"sp": "N", "t": "per parietem exibimus. Late fusum opus est et multiplex et prope cotidie novum, et de quo nunquam dicta erunt omnia. Quae sint tamen tradita, quid ex his optimum, et si qua mutari, adiici, detrahi melius videbitur, dicere experiar.", "st": "2.13.17"}, {"sp": "N", "t": "Rhetoricen in Latinum transferentes tum oratoriam, tum oratricem nominaverunt. Quos equidem non fraudaverim debita laude, quod copiam Romani sermonis augere temptarint. Sed non omnia nos ducentes ex Graeco sequuntur sicut ne illos quidem, quotiens utique suis verbis signare nostra voluerunt.", "st": "2.14.1"}, {"sp": "N", "t": "Et haec interpretatio non minus dura est quam illa Plauti essentia atque queentia, sed ne propria quidem; nam oratoria sic effertur ut elocutoria, oratrix ut elocutrix; illa autem de qua loquimur rhetorice talis est qualis eloquentia, nec dubie apud Graecos quoque duplicem intellectum habet.", "st": "2.14.2"}, {"sp": "N", "t": "Namque uno modo fit appositum ars rhetorica ut navis piratica, altero nomen rei, qualis est philosophia, amicitia. Nos ipsam nunc volumus significare substantiam ut grammatice litteratura est, non litteratrix quemadmodum oratrix, nec litteratoria quemadmodum oratoria; verum id in rhetorice non fit.", "st": "2.14.3"}, {"sp": "N", "t": "Ne pugnemus igitur, cum praesertim plurimis alioqui Graecis sit utendum. Nam certe et philosophos et musicos et geometras dicam, nec vim adferam nominibus his indecora in Latinum sermonem mutatione. Denique cum M. Tullius etiam in ipsis librorum, quos hac de re primum scripserat, titulis Graeco nomine utatur, profecto non est verendum, ne temere videamur oratori maximo de nomine artis suae credidisse.", "st": "2.14.4"}, {"sp": "N", "t": "Igitur rhetorice (iam enim sine metu cavillationis utemur hac appellatione) sic, ut opinor, optime dividetur, ut de arte, de artifice, de opere dicamus. Ars erit, quae disciplina percipi debet; ea est bene dicendi scientia. Artifex est, qui percepit hanc artem, id est, orator, cuius est summa bene dicere; opus, quod efficitur ab artifice, id est, bona oratio. Haec omnia rursus diducuntur in species; sed illa sequentia suo loco, nunc quae de prima parte tractanda sunt, ordiar.", "st": "2.14.5"}, {"sp": "N", "t": "Ante omnia, quid sit rhetorice. Quae finitur quidem varie, sed quaestionem habet duplicem, aut enim de qualitate ipsius rei aut de comprehensione verborum dissensio est. Prima atque praecipua opinionum circa hoc differentia, quod alii malos quoque viros posse oratores dici putant; alii, quorum nos sententiae accedimus, nomen hoc artemque, de qua loquimur, bonis demum tribui volunt. Eorum autem,", "st": "2.15.1"}, {"sp": "N", "t": "qui dicendi facultatem a maiore ac magis expetenda vitae laude secernunt, quidam rhetoricen vim tantum, quidam scientiam sed non virtutem, quidam usum, quidam artem quidem sed a scientia et virtute diiunctam, quidam etiam pravitatem quandam artis, id est κακοτεχνίαν nominaverunt.", "st": "2.15.2"}, {"sp": "N", "t": "Hi fere aut in persuadendo aut in dicendo apte ad persuadendum positum orandi munus sunt arbitrati. Id enim fieri potest ab eo quoque, qui vir bonus non sit. Est igitur frequentissimus finis, rhetoricen esse vim persuadendi. Quod ego vim appello, plerique potestatem, nonnulli facultatem vocant; quae res ne quid adferat ambiguitatis, <em>vim<\/em> dico δύναμιν.", "st": "2.15.3"}, {"sp": "N", "t": "Haec opinio originem ab Isocrate (si tamen re vera Ars, quae circumfertur, eius est) duxit. Qui, cum longe sit a voluntate infamantium oratoris officia, finem artis temere comprehendit, dicens esse rhetoricen persuadendi opificem, id est πειθοῦς δημιουργόν; neque enim mihi permiserim eadem uti declinatione, qua Ennius M. Cethegum <em>Suadae medullam<\/em> vocat.", "st": "2.15.4"}, {"sp": "N", "t": "Apud Platonem quoque Gorgias in libro, qui nomine eius inscriptus est, idem fere dicit; sed hanc Plato illius opinionem vult accipi non suam. Cicero pluribus locis scripsit, officium oratoris esse <em>dicere apposite ad persuadendum.<\/em>", "st": "2.15.5"}, {"sp": "N", "t": "In rhetoricis etiam, quos sine dubio ipse non probat, finem facit persuadere. Verum et pecunia persuadet et gratia et auctoritas dicentis et dignitas, postremo aspectus etiam ipse sine voce, quo vel recordatio meritorum cuiusque vel facies aliqua miserabilis vel formae pulchritudo sententiam dictat.", "st": "2.15.6"}, {"sp": "N", "t": "Nam et Manium Aquilium defendens Antonius, cum scissa veste cicatrices, quas is pro patria pectore adverso suscepisset, ostendit, non orationis habuit fiduciam sed oculis populi Romani vim attulit, quem illo ipso aspectu maxime motum in hoc, ut absolveret reum, creditum est.", "st": "2.15.7"}, {"sp": "N", "t": "Servium quidem Galbam miseratione sola, qua non suos modo liberos parvulos in contione produxerat, sed Galli etiam Sulpicii filium suis ipse manibus circumtulerat, elapsum esse, cum aliorum monumentis tum Catonis oratione testatum est.", "st": "2.15.8"}, {"sp": "N", "t": "Et Phrynen non Hyperidis actione, quanquam admirabili, sed conspectu corporis, quod illa speciosissimum alioqui diducta nudaverat tunica, putant periculo liberatam. Quae si omnia persuadent, non est hic, de quo locuti sumus, idoneus finis.", "st": "2.15.9"}, {"sp": "N", "t": "Ideoque diligentiores sibi sunt visi, qui, cum de rhetorice idem sentirent, existimaverunt eam vim dicendo persuadendi. Quem finem Gorgias in eodem, de quo supra diximus, libro, velut coactus a Socrate facit; a quo non dissentit Theodectes, sive ipsius id opus est, quod de rhetorice nomine eius inscribitur, sive, ut creditum est, Aristotelis, in quo est, finem esse rhetorices ducere homines dicendo in id, quod actor velit.", "st": "2.15.10"}, {"sp": "N", "t": "Sed ne hoc quidem satis est comprehensum; persuadent enim dicendo vel ducunt in id quod volunt alii quoque, ut meretrices, adulatores, corruptores. At contra non persuadet semper orator; ut interim non sit proprius hic finis eius, interim sit communis cum iis, qui ab oratore procul absunt.", "st": "2.15.11"}, {"sp": "N", "t": "Atqui non multum ab hoc fine abest Apollodorus, dicens iudicialis orationis primum et super omnia esse persuadere iudici et sententiam eius ducere in id, quod velit; nam et ipse oratorem fortunae subiicit, ut, si non persuaserit, nomen suum retinere non possit.", "st": "2.15.12"}, {"sp": "N", "t": "Quidam recesserunt ab eventu, sicut Aristoteles dicit: <em>rhetorice est vis inveniendi omnia in oratione persuasibilia.<\/em> Qui finis et illud vitium, de quo supra diximus, habet et insuper quod nihil nisi inventionem complectitur, quae sine elocutione non est oratio.", "st": "2.15.13"}, {"sp": "N", "t": "Hermagorae, qui finem eius esse ait persuasibiliter dicere, et aliis, qui eandem sententiam non iisdem tantum verbis explicant ac finem esse demonstrant dicere quae oporteat omnia ad persuadendum, satis responsum est, cum persuadere non tantum oratoris esse convicimus.", "st": "2.15.14"}, {"sp": "N", "t": "Addita sunt his alia varie. Quidam enim <em>circa res omnes,<\/em> quidam <em>circa civiles<\/em> modo versari rhetoricen putaverunt; quorum verius utrum sit, in eo loco, qui huius quaestionis proprius est, dicam.", "st": "2.15.15"}, {"sp": "N", "t": "Omnia subiecisse oratori videtur Aristoteles, cum dixit vim esse videndi, quid in quaque re possit esse persuasibile. Et Patrocles, qui non quidem adiicit <em>in quaque re,<\/em> sed nihil excipiendo idem ostendit; vim enim vocat inveniendi, quod sit in oratione persuasibile; qui fines et ipsi solam complectuntur inventionem. Quod vitium fugiens Theodorus vim putat inveniendi et eloquendi cum ornatu credibilia in omni oratione.", "st": "2.15.16"}, {"sp": "N", "t": "Sed cum eodem modo credibilia quo persuasibilia etiam non orator inveniat, adiiciendo <em>in omni oratione<\/em> magis quam superiores concedit scelera quoque suadentibus pulcherrimae rei nomen.", "st": "2.15.17"}, {"sp": "N", "t": "Gorgias apud Platonem suadendi se artificem in iudiciis et aliis coetibus esse ait, de iustis quoque et iniustis tractare; cui Socrates persuadendi, non docendi concedit facultatem.", "st": "2.15.18"}, {"sp": "N", "t": "Qui vero non omnia subiiciebant oratori, sollicitius ac verbosius, ut necesse erat, adhibuerunt discrimina; quorum fuit Ariston, Critolai Peripatetici discipulus, cuius hic finis est, <em>scientia videndi et agendi in quaestionibus civilibus per orationem popularis persuasionis.<\/em> Hic scientiam,", "st": "2.15.19"}, {"sp": "N", "t": "quia Peripateticus est, non, ut Stoici, virtutis loco ponit; popularem autem comprehendendo persuasionem etiam contumeliosus est adversus artem orandi, quam nihil putat doctis persuasuram. Illud de omnibus, qui circa civiles demum quaestiones oratorem iudicant versari, dictum sit, excludi ab his plurima oratoris officia, illam certe laudativam totam, quae est rhetorices pars tertia.", "st": "2.15.20"}, {"sp": "N", "t": "Cautius Theodorus Gadareus, ut iam ad eos veniamus, qui artem quidem esse eam sed non virtutem putaverunt. Ita enim dicit (ut ipsis eorum verbis utar, qui haec ex Graeco transtulerunt), <em>Ars inventrix et iudicatrix et enuntiatrix decenti ornatu secundum mensionem eius, quod in quoque potest sumi persuasibile, in materia civili.<\/em>", "st": "2.15.21"}, {"sp": "N", "t": "Itemque Cornelius Celsus, qui finem rhetorices ait dicere persuasibiliter in dubia civili materia. Quibus sunt non dissimiles, qui ab aliis traduntur; qualis est ille, <em>Vis videndi et eloquendi de rebus civilibus subiectis sibi cum quadam persuasione et quodam corporis habitu et eorum, quae dicet, pronuntiatione.<\/em>", "st": "2.15.22"}, {"sp": "N", "t": "Mille alia, sed aut eadem aut ex eisdem composita; quibus item, cum de materia rhetorices dicendum erit, respondebimus. Quidam eam neque vim neque scientiam neque artem putaverunt, sed Critolaus usum dicendi (nam hoc τριβή significat), Athenaeus fallendi artem.", "st": "2.15.23"}, {"sp": "N", "t": "Plerique autem, dum pauca ex Gorgia Platonis a prioribus imperite excerpta legere contenti neque hoc totum neque alia eius volumina evolvunt, in maximum errorem inciderunt, creduntque eum in hac esse opinione, ut rhetoricen non artem sed peritiam quandam gratiae ac voluptatis existimet;", "st": "2.15.24"}, {"sp": "N", "t": "et alio loco civilitatis particulae simulacrum et quartam partem adulationis, quod duas partes civilitatis corpori adsignet, medicinam et quam interpretantur exercitatricem, duas animo, legalem atque iustitiam; adulationem autem medicinae vocet cocorum artificium, exercitatricis mangonum, qui colorem fuco et verum robur inani sagina mentiantur, legalis cavillatricem, iustitiae rhetoricen.", "st": "2.15.25"}, {"sp": "N", "t": "Quae omnia sunt quidem scripta in hoc libro dictaque a Socrate, cuius persona videtur Plato significare quid sentiat; sed alii sunt eius sermones ad coarguendos, qui contra disputant, compositi, quos ἐλεγκτικούς vocant, alii ad praecipiendum, qui δογματικοί appellantur.", "st": "2.15.26"}, {"sp": "N", "t": "Socrates autem seu Plato eam quidem, quae tum exercebatur, rhetoricen talem putat, nam et dicit his verbis τοῦτον τὸν τρόπον, ὃν ὑμεῖς πολιτεύεσθε, veram autem et honestam intelligit. Itaque disputatio ilia contra Gorgian ita clauditur, οὐκοῦν ἀνάγκη τὸν ῥητορικὸν δίκαιον εἶναι, τὸν δὲ δίκαιον βούλεσθαι δίκαια πράττειν;", "st": "2.15.27"}, {"sp": "N", "t": "Ad quod ille quidem conticescit, sed sermonem suscipit Polus iuvenili calore inconsideratior, contra quem illa de simulacro et adulatione dicuntur. Tum Callicles adhuc concitatior, qui tamen ad hanc perducitur clausulam, τὸν μέλλοντα ὀρθῶς ῥητορικὸν ἔσεσθαι, δίκαιον ἄνδρα δεῖ εἶναι καὶ ἐπιστήμονα τῶν δικαίων; ut appareat, Platoni non rhetoricen videri malum, sed eam veram nisi iusto ac bono non contingere.", "st": "2.15.28"}, {"sp": "N", "t": "Adhuc autem in Phaedro manifestius facit, hanc artem consummari citra iustitiae quoque scientiam non posse; cui opinioni nos quoque accedimus. An aliter defensionem Socratis et eorum, qui pro patria ceciderant, laudem scripsisset?", "st": "2.15.29"}, {"sp": "N", "t": "quae certe sunt oratoris opera. Sed in illud hominum genus, quod facilitate dicendi male utebatur, invectus est. Nam et Socrates inhonestam sibi credidit orationem, quam ei Lysias reo composuerat; et tum maxime scribere litigatoribus, quae illi pro se ipsi dicerent, erat moris, atque ita iuri, quo non licebat pro altero agere, fraus adhibebatur.", "st": "2.15.30"}, {"sp": "N", "t": "Doctores quoque eius artis parum idonei Platoni videbantur, qui rhetoricen a iustitia separarent et veris credibilia praeferrent; nam id quoque dicit in Phaedro.", "st": "2.15.31"}, {"sp": "N", "t": "Consensisse autem illis superioribus videri potest etiam Cornelius Celsus, cuius haec verba sunt: <em>Orator simile tantum veri petit.<\/em> Deinde paulo post: <em>Non enim bona conscientia sed victoria litigantis est praemium.<\/em> Quae si vera essent, pessimorum hominum foret, haec tam perniciosa nocentissimis moribus dare instrumenta et nequitiam praeceptis adiuvare. Sed illi rationem opinionis suae viderint.", "st": "2.15.32"}, {"sp": "N", "t": "Nos autem ingressi formare perfectum oratorem, quem in primis esse virum bonum volumus, ad eos qui de hoc opere melius sentiunt, revertamur. Rhetoricen autem quidam eandem civilitatem esse iudicaverunt; Cicero scientiae civilis partem vocat (civilis autem scientia idem quod sapientia est); quidam eandem philosophiam,", "st": "2.15.33"}, {"sp": "N", "t": "quorum est Isocrates. Huic eius substantiae maxime conveniet finitio, rhetoricen esse bene dicendi scientiam. Nam et orationis omnes virtutes semel complectitur et protinus etiam mores oratoris, cum bene dicere non possit nisi bonus.", "st": "2.15.34"}, {"sp": "N", "t": "Idem valet Chrysippi finis ille ductus a Cleanthe scientia recte dicendi. Sunt plures eiusdem, sed ad alias quaestiones magis pertinent. Idem sentit et finis hoc modo comprehensus, persuadere quod oporteat, nisi quod artem ad exitum alligat.", "st": "2.15.35"}, {"sp": "N", "t": "At bene Areus dicere secundum virtutem orationis. Excludunt a rhetorice malos et illi, qui scientiam civilium officiorum eam putaverunt, si scientiam virtutem iudicant; sed anguste intra civiles quaestiones coercent. Albucius, non obscurus professor atque auctor, scientiam bene dicendi esse consentit, sed exceptionibus peccat adiiciendo circa civiles quaestiones et credibiliter; quarum utrique iam responsum est.", "st": "2.15.36"}, {"sp": "N", "t": "Probabilis et illi voluntatis, qui recte sentire et dicere rhetorices putaverunt. Hi sunt fere fines maxime illustres et de quibus praecipue disputatur. Nam omnes quidem persequi neque attinet neque possum, cum pravum quoddam, ut arbitror, studium circa scriptores artium extiterit, nihil eisdem verbis, quae prior aliquis occupasset, finiendi, quae ambitio procul aberit a me.", "st": "2.15.37"}, {"sp": "N", "t": "Dicam enim non utique quae invenero sed quae placebunt, sicut hoc, rhetoricen esse bene dicendi scientiam; cum reperto quod est optimum, qui quaerit aliud, peius velit. His approbatis, simul manifestum est illud quoque, quem finem vel quid summum et ultimum habeat rhetorice, quod τέλος dicitur, ad quod omnis ars tendit; nam si est ipsa bene dicendi scientia, finis eius et summum est bene dicere.", "st": "2.15.38"}, {"sp": "N", "t": "Sequitur quaestio, an utilis rhetorice. Nam quidam vehementer in eam invehi solent, et, quod sit indignissimum, in accusationem orationis utuntur orandi viribus:", "st": "2.16.1"}, {"sp": "N", "t": "eloquentiam esse, quae poenis eripiat scelestos, cuius fraude damnentur interim boni, consilia ducantur in peius, nec seditiones modo turbaeque populares sed bella etiam inexpiabilia excitentur; cuius denique tum maximus sit usus, cum pro falsis contra veritatem valet.", "st": "2.16.2"}, {"sp": "N", "t": "Nam et Socrati obiiciunt comici docere eum, quomodo peiorem causam meliorem faciat, et contra Tisian et Gorgian similia dicit polliceri Plato.", "st": "2.16.3"}, {"sp": "N", "t": "Et his adiiciunt exempla Graecorum Romanorumque et enumerant, qui perniciosa non singulis tantum sed rebus etiam publicis usi eloquentia turbaverint civitatium status vel everterint, eoque et Lacedaemoniorum civitate expulsam et Athenis quoque, ubi actor movere adfectus vetabatur, velut recisam orandi potestatem.", "st": "2.16.4"}, {"sp": "N", "t": "Quo quidem modo nec duces erunt utiles nec magistratus nec medicina nec denique ipsa sapientia. Nam et dux Flaminius et Gracchi, Saturnini, Glauciae magistratus, et in medicis venena et in his, qui philosophorum nomine male utuntur, gravissima nonnunquam flagitia deprehensa sunt.", "st": "2.16.5"}, {"sp": "N", "t": "Cibos aspernemur; attulerunt saepe valetudinis causas. Nunquam tecta subeamus; super habitantes aliquando procumbunt. Non fabricetur militi gladius; potest uti eodem ferro latro. Quis nescit, ignes, aquas, sine quibus nulla sit vita, et (ne terrenis immorer) solem lunamque, praecipua siderum, aliquando et nocere?", "st": "2.16.6"}, {"sp": "N", "t": "Num igitur negabitur deformem Pyrrhi pacem caecus ille Appius dicendi viribus diremisse? aut non divina M. Tulli eloquentia et contra leges agrarias popularis fuit et Catilinae fregit audaciam et supplicationes, qui maximus honor victoribus bello ducibus datur, in toga meruit?", "st": "2.16.7"}, {"sp": "N", "t": "Nonne perterritos militum animos frequenter a metu revocat oratio et tot pugnandi pericula ineuntibus laudem vita potiorem esse persuadet? Neque vero me Lacedaemonii atque Athenienses magis moverint quam populus Romanus, apud quem summa semper oratoribus dignitas fuit.", "st": "2.16.8"}, {"sp": "N", "t": "Equidem nec urbium conditores reor aliter effecturos fuisse ut vaga ilia multitudo coiret in populos, nisi docta voce commota; nec legum repertores sine summa vi orandi consecutos, ut se ipsi homines ad servitutem iuris astringerent.", "st": "2.16.9"}, {"sp": "N", "t": "Quin ipsa vitae praecepta, etiamsi natura sunt honesta, plus tamen ad formandas mentes valent, quotiens pulchritudinem rerum claritas orationis illuminat. Quare, etiamsi in utramque partem valent arma facundiae, non est tamen aequum id haberi malum, quo bene uti licet.", "st": "2.16.10"}, {"sp": "N", "t": "Verum haec apud eos forsitan quaerantur, qui summam rhetorices ad persuadendi vim rettulerunt. Si vero est bene dicendi scientia, quem nos finem sequimur, ut sit orator in primis vir bonus, utilem certe esse eam confitendum est.", "st": "2.16.11"}, {"sp": "N", "t": "Et hercule deus ille princeps, parens rerum fabricatorque mundi, nullo magis hominem separavit a ceteris, quae quidem mortalia essent, animalibus, quam dicendi facultate.", "st": "2.16.12"}, {"sp": "N", "t": "Nam corpora quidem magnitudine, viribus, firmitate, patientia, velocitate praestantiora in illis mutis videmus, eadem minus egere adquisitae extrinsecus opis. Nam et ingredi citius et pasci et tranare aquas citra docentem natura ipsa sciunt.", "st": "2.16.13"}, {"sp": "N", "t": "Et pleraque contra frigus ex suo corpore vestiuntur, et arma iis ingenita quaedam et ex obvio fere victus, circa quae omnia multus hominibus labor est. Rationem igitur nobis praecipuam dedit eiusque nos socios esse cum dis immortalibus voluit.", "st": "2.16.14"}, {"sp": "N", "t": "Sed ipsa ratio neque tam nos iuvaret neque tam esset in nobis manifesta, nisi, quae concepissemus mente, promere etiam loquendo possemus, quod magis deesse ceteris animalibus quam intellectum et cogitationem quandam videmus.", "st": "2.16.15"}, {"sp": "N", "t": "Nam et mollire cubilia et nidos texere et educare fetus et excludere, quin etiam reponere in hiemem alimenta, opera quaedam nobis inimitabilia (qualia sunt cerarum ac mellis) efficere, nonnullius fortasse rationis est; sed quia carent sermone, quae id faciunt, muta atque irrationalia vocantur.", "st": "2.16.16"}, {"sp": "N", "t": "Denique homines, quibus negata vox est, quantulum adiuvat animus ille caelestis? Quare si nihil a dis oratione melius accepimus, quid tam dignum cultu ac labore ducamus, aut in quo malimus praestare hominibus, quam quo ipsi homines ceteris animalibus praestant,", "st": "2.16.17"}, {"sp": "N", "t": "eo quidem magis, quod nulla in arte plenius labor gratiam refert? Id adeo manifestum erit, si cogitaverimus, unde et quo usque iam provecta sit orandi facultas; et adhuc augeri potest.", "st": "2.16.18"}, {"sp": "N", "t": "Nam ut omittam, defendere amicos, regere consiliis senatum, populum, exercitum in quae velit ducere, quam sit utile conveniatque bono viro, nonne pulchrum vel hoc ipsum est, ex communi intellectu verbisque, quibus utuntur omnes, tantum adsequi laudis et gloriae, ut non loqui et orare sed, quod Pericli contigit, fulgurare ac tonare videaris?", "st": "2.16.19"}, {"sp": "N", "t": "Finis non erit, si exspatiari in parte hac et indulgere voluptati velim. Transeamus igitur ad eam quaestionem, quae sequitur, an rhetorice ars sit.", "st": "2.17.1"}, {"sp": "N", "t": "Quod quidem adeo ex iis, qui praecepta dicendi tradiderunt, nemo dubitavit, ut etiam ipsis librorum titulis testatum sit, scriptos eos de arte rhetorica; Cicero vero eam, quae rhetorice vocetur, esse artificiosam eloquentiam dicat. Quod non oratores tantum vindicarunt, ut studiis aliquid suis praestitisse videantur, sed cum iis philosophi et Stoici et Peripatetici plerique consentiunt.", "st": "2.17.2"}, {"sp": "N", "t": "Ac me dubitasse confiteor, an hanc partem quaestionis tractandam putarem; nam quis est adeo non ab eruditione modo sed a sensu remotus hominis, ut fabricandi quidem et texendi et e luto vasa ducendi artem putet, rhetoricen autem, maximum ac pulcherrimum, ut supra diximus, opus, in tam sublime fastigium existimet sine arte venisse?", "st": "2.17.3"}, {"sp": "N", "t": "Equidem illos, qui contra disputaverunt, non tam id sensisse quod dicerent, quam exercere ingenia materiae difficultate credo voluisse, sicut Polycraten, cum Busirim laudaret et Clytaemnestram; quanquam is, quod his dissimile non est, composuisse orationem, quae est habita contra Socraten, dicitur.", "st": "2.17.4"}, {"sp": "N", "t": "Quidam naturalem esse rhetoricen volunt et tamen adiuvari exercitatione non diffitentur, ut in libris Ciceronis de Oratore dicit Antonius, observationem quandam esse non artem.", "st": "2.17.5"}, {"sp": "N", "t": "Quod non ideo, ut pro vero accipiamus, est positum, sed ut Antoni persona servetur, qui dissimulator artis fuit. Hanc autem opinionem habuisse Lysias videtur. Cuius sententiae talis defensio est, quod indocti et barbari et servi, pro se cum loquuntur, aliquid dicant simile principio, narrent, probent, refutent, et (quod vim habeat epilogi) deprecentur.", "st": "2.17.6"}, {"sp": "N", "t": "Deinde adiiciunt illas verborum cavillationes, nihil, quod ex arte fiat, ante artem fuisse; atqui dixisse homines pro se et in alios semper, doctores artis sero et circa Tisian et Coraca primum repertos, orationem igitur ante artem fuisse eoque artem non esse.", "st": "2.17.7"}, {"sp": "N", "t": "Nos porro, quando coeperit huius rei doctrina, non laboramus exquirere, quanquam apud Homerum et praeceptorem Phoenicem cum agendi tum etiam loquendi et oratores plures et omne in tribus ducibus orationis genus et certamina quoque proposita eloquentiae inter iuvenes invenimus, quin in caelatura clipei Achillis et lites sunt et actores.", "st": "2.17.8"}, {"sp": "N", "t": "Illud enim admonere satis est, omnia, quae ars consummaverit, a natura initia duxisse. Aut tollatur medicina, quae ex observatione salubrium atque iis contrariorum reperta est, et, ut quibusdam placet, tota constat experimentis; nam et vulnus deligavit aliquis, antequam haec ars esset, et febrem quiete et abstinentia, non quia rationem videbat, sed quia id valetudo ipsa cogebat, mitigavit.", "st": "2.17.9"}, {"sp": "N", "t": "Nec fabrica sit ars; casas enim primi illi sine arte fecerunt; nec musica; cantatur ac saltatur per omnes gentes aliquo modo. Ita si rhetorice vocari debet sermo quicunque, fuisse eam,", "st": "2.17.10"}, {"sp": "N", "t": "antequam esset ars, confitebor; si vero non quisquis loquitur, orator est, et tum non tanquam oratores loquebantur, necesse est, oratorem factum arte nec ante artem fuisse fateantur. Quo illud quoque excluditur, quod dicunt, non esse artis id, quod faciat qui non didicerit, dicere autem homines et qui non didicerint.", "st": "2.17.11"}, {"sp": "N", "t": "Ad cuius rei confirmationem adferunt, Demaden remigem, et Aeschinen hypocriten oratores fuisse. Falso; nam neque orator esse, qui non didicit, potest, et hos sero potius quam nunquam didicisse quis dixerit, quanquam Aeschines ab initio sit versatus in litteris, quas pater eius etiam docebat, Demaden neque non didicisse certum sit, et continua dicendi exercitatio potuerit tantum, quantuscunque postea fuit, fecisse; nam id potentissimum discendi genus est.", "st": "2.17.12"}, {"sp": "N", "t": "Sed et praestantiorem, si didicisset, futurum fuisse dicere licet; neque enim orationes scribere est ausus, ut eum multum valuisse in dicendo sciamus.", "st": "2.17.13"}, {"sp": "N", "t": "Aristoteles, ut solet, quaerendi gratia quaedam subtilitatis suae argumenta excogitavit in Gryllo; sed idem et de arte rhetorica tris libros scripsit, et in eorum primo non artem solum eam fatetur, sed ei particulam civilitatis sicut dialectices adsignat.", "st": "2.17.14"}, {"sp": "N", "t": "Multa Critolaus contra, multa Rhodius Athenodorus. Agnon quidem detraxit sibi inscriptione ipsa fidem, qua rhetorices accusationem professus est. Nam de Epicuro, qui disciplinas omnes fugit, nihil miror.", "st": "2.17.15"}, {"sp": "N", "t": "Hi complura dicunt sed ex paucis locis ducta; itaque potentissimis eorum breviter occurram, ne in infinitum quaestio evadat.", "st": "2.17.16"}, {"sp": "N", "t": "Prima iis argumentatio ex materia est. Omnes enim artes aiunt habere materiam, quod est verum; rhetorices nullam esse propriam, quod esse falsum in sequentibus probabo.", "st": "2.17.17"}, {"sp": "N", "t": "Altera est calumnia nullam artem falsis assentiri opinionibus, quia constitui sine perceptione non possit, quae semper vera sit; rhetoricen assentiri falsis, non esse igitur artem.", "st": "2.17.18"}, {"sp": "N", "t": "Ego rhetoricen nonnunquam dicere falsa pro veris confitebor, sed non ideo in falsa quoque esse opinione concedam, quia longe diversum est, ipsi quid videri et, ut alii videatur, efficere. Nam et imperator falsis utitur saepe, ut Hannibal, cum inclusus a Fabio, sarmentis circum cornua boum deligatis incensisque, per noctem in adversos montes agens armenta speciem hosti abeuntis exercitus dedit, sed illum fefellit, ipse, quid verum esset, non ignoravit.", "st": "2.17.19"}, {"sp": "N", "t": "Nec vero Theopompus Lacedaemonius, cum permutato cum uxore habitu e custodia ut mulier evasit, falsam de se opinionem habuit, sed custodibus praebuit. Item orator, cum falso utitur pro vero, scit esse falsum eoque se pro vero uti; non ergo falsam habet ipse opinionem, sed fallit alium.", "st": "2.17.20"}, {"sp": "N", "t": "Nec Cicero, cum se tenebras offudisse iudicibus in causa Cluenti gloriatus est, nihil ipse vidit. Et pictor, cum vi artis suae efficit, ut quaedam eminere in opere, quaedam recessisse credamus, ipse ea plana esse non nescit.", "st": "2.17.21"}, {"sp": "N", "t": "Aiunt etiam omnes artes habere finem aliquem propositum, ad quem tendant; hunc modo nullum esse in rhetorice, modo non praestari eum, qui promittatur. Mentiuntur; nos enim esse finem iam ostendimus, et quis esset diximus.", "st": "2.17.22"}, {"sp": "N", "t": "Et praestabit hunc semper orator, semper enim bene dicet. Firmum autem hoc, quod opponitur, adversus eos fortasse sit, qui persuadere finem putaverunt. Noster orator arsque a nobis finita non sunt posita in eventu. Tendit quidem ad victoriam qui dicit; sed cum bene dixit, etiamsi non vincat, id quod arte continetur effecit.", "st": "2.17.23"}, {"sp": "N", "t": "Nam et gubernator vult salva nave in portum pervenire; si tamen tempestate fuerit abreptus, non ideo minus erit gubernator dicetque notum illud, <em>Dum clavum rectum teneam.<\/em>", "st": "2.17.24"}, {"sp": "N", "t": "Et medicus sanitatem aegri petit; si tamen aut valetudinis vi aut intemperantia aegri aliove quo casu summa non contingit, dum ipse omnia secundum rationem fecerit, medicinae fine non excidet. Ita oratori bene dixisse finis est. Nam est ars ea, ut post paulum clarius ostendemus, in actu posita non in effectu.", "st": "2.17.25"}, {"sp": "N", "t": "Ita falsum erit illud quoque, quod dicitur, artes scire quando sint finem consecutae, rhetoricen nescire. Nam se quisque bene dicere intelligit. Uti etiam vitiis rhetoricen, quod ars nulla faciat, criminantur, quia et falsum dicat et adfectus moveat.", "st": "2.17.26"}, {"sp": "N", "t": "Quorum neutrum est turpe, cum ex bona ratione proficiscitur, ideoque nec vitium. Nam et mendacium dicere etiam sapienti aliquando concessum est, et adfectus, si aliter ad aequitatem perduci iudex non poterit, necessario movebit orator.", "st": "2.17.27"}, {"sp": "N", "t": "Imperiti enim iudicant et qui frequenter in hoc ipsum fallendi sint, ne errent. Nam, si mihi sapientes iudices dentur, sapientium contiones atque omne consilium, nihil invidia valeat, nihil gratia, nihil opinio praesumpta falsique testes: perquam sit exiguus eloquentiae locus et prope in sola delectatione ponatur.", "st": "2.17.28"}, {"sp": "N", "t": "Sin et audientium mobiles animi et tot malis obnoxia veritas, arte pugnandum est et adhibenda quae prosunt. Neque enim, qui recta via depulsus est, reduci ad eam nisi alio flexu potest.", "st": "2.17.29"}, {"sp": "N", "t": "Plurima vero ex eo contra rhetoricen cavillatio est, quod ex utraque causae parte dicatur. Inde haec: nullam esse artem contrariam sibi, rhetoricen esse contrariam sibi; nullam artem destruere quod effecerit, accidere hoc rhetorices operi; item aut dicenda eam docere aut non dicenda; ita vel per hoc non esse artem, quod non dicenda praecipiat, vel per hoc, quod, cum dicenda praeceperit, etiam contraria his doceat.", "st": "2.17.30"}, {"sp": "N", "t": "Quae omnia apparet de ea rhetorice dici, quae sit a bono viro atque ab ipsa virtute seiuncta; alioqui ubi iniusta causa est, ibi rhetorice non est, adeo ut vix admirabili quodam casu possit accidere, ut ex utraque parte orator, id est vir bonus, dicat.", "st": "2.17.31"}, {"sp": "N", "t": "Tamen quoniam hoc quoque in rerum naturam cadit, ut duos sapientes aliquando iustae causae in diversum trahant, (quando etiam pugnaturos eos inter se, si ratio ita duxerit, credunt) respondebo propositis, atque ita quidem, ut appareat, haec adversus eos quoque frustra excogitata, qui malis moribus nomen oratoris indulgent.", "st": "2.17.32"}, {"sp": "N", "t": "Nam rhetorice non est contraria sibi. Causa enim cum causa, non illa secum ipsa componitur. Nec, si pugnent inter se, qui idem didicerunt, idcirco ars, quae utrique tradita est, non erit; alioqui nec armorum, quia saepe gladiatores sub eodem magistro eruditi inter se componuntur;", "st": "2.17.33"}, {"sp": "N", "t": "nec gubernandi, quia navalibus proeliis gubernator est gubernatori adversus; nec imperatoria, quia imperator cum imperatore contendit. Item non evertit opus rhetorice, quod efficit. Neque enim positum a se argumentum solvit orator sed ne rhetorice quidem, quia apud eos, qui in persuadendo finem putant, aut si quis (ut dixi) casus duos inter se bonos viros composuerit, verisimilia quaerentur; non autem, si quid est altero credibilius, id ei contrarium est, quod fuit credibile.", "st": "2.17.34"}, {"sp": "N", "t": "Nam ut candido candidius et dulci dulcius non est adversum, ita nec probabili probabilius. Neque praecipit unquam non dicenda nec dicendis contraria, sed quae in quaque causa dicenda sunt.", "st": "2.17.35"}, {"sp": "N", "t": "Non semper autem ei, etiamsi frequentissime, tuenda veritas erit; sed aliquando exigit communis utilitas, ut etiam falsa defendat. Ponuntur hae quoque in secundo Ciceronis de Oratore libro contradictiones: artem earum rerum esse, quae sciantur; oratoris omnem actionem opinione, non scientia contineri, quia et apud eos dicat, qui nesciant, et ipse dicat aliquando, quod nesciat.", "st": "2.17.36"}, {"sp": "N", "t": "Ex his alterum, id est, an sciat index, de quo dicatur, nihil ad oratoris artem; alteri respondendum, <em>Ars earum rerum est, quae sciuntur.<\/em> Rhetorice ars est bene dicendi, bene autem dicere scit orator.", "st": "2.17.37"}, {"sp": "N", "t": "Sed nescit, an verum sit quod dicit. Ne hi quidem, qui ignem aut aquam aut quattuor elementa aut corpora insecabilia esse, ex quibus res omnes initium duxerint, tradunt, nec qui intervalla siderum et mensuras solis ac terrae colligunt; disciplinam tamen suam artem vocant. Quodsi ratio efficit, ut haec non opinari sed propter vim probationum scire videantur, eadem ratio idem praestare oratori potest.", "st": "2.17.38"}, {"sp": "N", "t": "Sed an causa vera sit, nescit. Ne medicus quidem, an dolorem capitis habeat, qui hoc se pati dicet; curabit tamen, tamquam id verum sit, et erit ars medicina. Quid quod rhetorice non utique propositum habet semper vera dicendi, sed semper verisimilia? scit autem esse verisimilia quae dicit.", "st": "2.17.39"}, {"sp": "N", "t": "Adiiciunt his, qui contra sentiunt, quod saepe, quae in allis litibus impugnarunt actores causarum, eadem in aliis defendant. Quod non artis sed hominis est vitium. Haec sunt praecipua, quae contra rhetoricen dicantur; alia et minora et tamen ex his fontibus derivata. Confirmatur autem esse artem eam breviter.", "st": "2.17.40"}, {"sp": "N", "t": "Nam sive, ut Cleanthes voluit, ars est potestas via, id est ordine, efficiens, esse certe viam atque ordinem in bene dicendo nemo dubitaverit; sive ille ab omnibus fere probatus finis observatur, artem constare ex perceptionibus consentientibus et coexercitatis ad fine utilem vitae, iam ostendemus nihil non horum in rhetorice inesse.", "st": "2.17.41"}, {"sp": "N", "t": "Quid quod et inspectione et exercitatione ut artes ceterae constat? Nec potest ars non esse, si est ars dialectice, quod fere constat, cum ab ea specie magis quam genere differat. Sed nec illa omittenda sunt, qua in re alius se inartificialiter alius artificialiter gerat, in ea esse artem, et in eo quod, qui didicerit, melius faciat quam qui non didicerit, esse artem.", "st": "2.17.42"}, {"sp": "N", "t": "Atqui non solum doctus indoctum, sed etiam doctior doctum in rhetorices opere superabit, neque essent aliter eius tam multa praecepta tamque magni, qui docerent; idque cum omnibus confitendum est, tum nobis praecipue, qui rationem dicendi a bono viro non separamus.", "st": "2.17.43"}, {"sp": "N", "t": "Cum sint autem artium aliae positae in inspectione, id est cognitione et aestimatione rerum, qualis est astrologia, nullum exigens actum sed ipso rei, cuius studium habet, intellectu contenta, quae θεωρητικὴ vocatur; aliae in agendo, quarum in hoc finis est et ipso actu perficitur nihilque post actum operis relinquit, quae πρακτική dicitur, qualis saltatio est;", "st": "2.18.1"}, {"sp": "N", "t": "aliae in effectu, quae operis, quod oculis subiicitur, consummatione finem accipiunt, quam ποητικήν appellamus, qualis est pictura: fere iudicandum est, rhetoricen in actu consistere; hoc enim, quod est officii sui, perficit.", "st": "2.18.2"}, {"sp": "N", "t": "Atque ita ab omnibus dictum est. Mihi autem videtur etiam ex illis ceteris artibus multum assumere. Nam et potest aliquando ipsa res per se inspectione esse contenta. Erit enim rhetorice in oratore etiam tacente, et si desierit agere vel proposito vel aliquo casu impeditus, non magis desinet esse orator quam medicus, qui curandi fecerit finem.", "st": "2.18.3"}, {"sp": "N", "t": "Nam est aliquis, ac nescio an maximus, etiam ex secretis studiis fructus ac tum pura voluptas litterarum, cum ab actu, id est opera, recesserunt et contemplatione sui fruuntur.", "st": "2.18.4"}, {"sp": "N", "t": "Sed effectivae quoque aliquid simile scriptis orationibus vel historiis, quod ipsum opus in parte oratoria merito ponimus, consequetur. Si tamen una ex tribus artibus habenda sit, quia maxime eius usus actu continetur atque est in eo frequentissima, dicatur activa vel administrativa, nam et hoc eiusdem rei nomen est.", "st": "2.18.5"}, {"sp": "N", "t": "Scio, quaeri etiam, naturane plus ad eloquentiam conferat an doctrina. Quod ad propositum quidem operis nostri nihil pertinet (neque enim consummatus orator nisi ex utroque fieri potest), plurimum tamen referre arbitror, quam esse in hoc loco quaestionem velimus.", "st": "2.19.1"}, {"sp": "N", "t": "Nam si parti utrilibet omnino alteram detrahas, natura etiam sine doctrina multum valebit, doctrina nulla esse sine natura poterit. Sin ex pari coeant, in mediocribus quidem utrisque maius adhuc credam naturae esse momentum, consummatos autem plus doctrinae debere quam naturae putabo; sicut terrae nullam fertilitatem habenti nihil optimus agricola profuerit, e terra uberi utile aliquid etiam nullo colente nascetur, at in solo fecundo plus cultor quam ipsa per se bonitas soli efficiet.", "st": "2.19.2"}, {"sp": "N", "t": "Et, si Praxiteles signum aliquod ex molari lapide conatus esset exsculpere, Parium marmor mallem rude; at si illud idem artifex expolisset, plus in manibus fuisset quam in marmore. Denique natura materia doctrinae est; haec fingit, illa fingitur. Nihil ars sine materia, materiae etiam sine arte pretium est, ars summa materia optima melior.", "st": "2.19.3"}, {"sp": "N", "t": "Illa quaestio est maior, ex mediis artibus, quae neque laudari per se nec vituperari possunt, sed utiles aut secus secundum mores utentium fiunt, habenda sit rhetorice, an sit, ut compluribus etiam philosophorum placet, virtus.", "st": "2.20.1"}, {"sp": "N", "t": "Equidem illud, quod in studiis dicendi plerique exercuerunt et exercent, aut nullam artem, quae ἀτεχνία nominatur, puto, (multos enim video sine ratione, sine litteris, qua vel impudentia vel fames duxit, ruentes) aut malam quasi artem, quam κακοτεχνίαν dicimus. Nam et fuisse multos et esse nonnullos existimo, qui facultatem dicendi ad hominum perniciem converterint.", "st": "2.20.2"}, {"sp": "N", "t": "ματαιοτεχνία quoque est quaedam, id est supervacua artis imitatio, quae nihil sane neque boni neque mali habeat, sed vanum laborem, qualis illius fuit, qui grana ciceris ex spatio distanti missa in acum continuo et sine frustratione inserebat, quem cum spectasset Alexander, donasse dicitur eiusdem leguminis modio, quod quidem praemium fuit illo opere dignissimum.", "st": "2.20.3"}, {"sp": "N", "t": "His ego comparandos existimo, qui in declamationibus, quas esse veritati dissimillimas volunt, aetatem multo studio ac labore consumunt. Verum haec, quam instituere conamur et cuius imaginem animo concepimus, quae bono viro convenit quaeque est vere rhetorice, virtus erit.", "st": "2.20.4"}, {"sp": "N", "t": "Quod philosophi quidem multis et acutis conclusionibus colligunt, mihi vero etiam planiore hac proprieque nostra probatione videtur esse perspicuum. Ab illis haec dicuntur. Si consonare sibi in faciendis ac non faciendis virtus est, quae pars eius prudentia vocatur, eadem in dicendis ac non dicendis erit.", "st": "2.20.5"}, {"sp": "N", "t": "Et si virtutes sunt, ad quas nobis etiam ante quam doceremur initia quaedam ac semina sunt concessa natura, ut ad iustitiam, cuius rusticis quoque ac barbaris apparet aliqua imago, nos certe sic esse ab initio formatos, ut possemus orare pro nobis, etiamsi non perfecte, tamen ut inessent quaedam (ut dixi) semina eius facultatis, manifestum est.", "st": "2.20.6"}, {"sp": "N", "t": "Non eadem autem natura est iis artibus, quae a virtute sunt remotae. Itaque cum duo sint genera orationis, altera perpetua, quae rhetorice dicitur, altera concisa, quae dialectice (quas quidem Zeno adeo coniunxit, ut hanc compressae in pugnum manus, illam explicatae diceret similem), etiam disputatrix virtus erit. Adeo de hac, quae speciosior atque apertior tanto est, nihil dubitabitur. Sed plenius hoc idem atque apertius intueri ex ipsis operibus volo.", "st": "2.20.7"}, {"sp": "N", "t": "Nam quid orator in laudando faciet nisi honestorum et turpium peritus? aut in suadendo nisi utilitate perspecta? aut in iudiciis, si iustitiae sit ignarus? Quid? non fortitudinem postulat res eadem, cum saepe contra turbulentas populi minas, saepe cum periculosa potentium offensa, nonnunquam, ut iudicio Miloniano, inter circumfusa militum arma dicendum sit; ut, si virtus non est, ne perfecta quidem esse possit oratio.", "st": "2.20.8"}, {"sp": "N", "t": "Quodsi ea in quoque animalium est virtus, qua praestat cetera vel pleraque, ut in leone impetus, in equo velocitas, hominem porro ratione atque oratione excellere ceteris certum est: cur non tam in eloquentia quam in ratione virtutem eius esse credamus, recteque hoc apud Ciceronem dixerit Crassus: <em>Est enim eloquentia una quaedam de summis virtutibus,<\/em> et ipse Cicero sua persona cum ad Brutum in epistulis, tum aliis etiam locis virtutem eam appellet?", "st": "2.20.9"}, {"sp": "N", "t": "At prooemium aliquando ac narrationem dicet malus homo et argumenta, sic ut nihil sit in iis requirendum. Nam et latro pugnabit acriter, virtus tamen erit fortitudo; et tormenta sine gemitu feret malus servus, tolerantia tamen doloris laude sua non carebit. Multa fiunt eadem sed aliter. Sufficiant igitur haec, quia de utilitate supra tractavimus.", "st": "2.20.10"}, {"sp": "N", "t": "Materiam rhetorices quidam dixerunt esse orationem, qua in sententia ponitur apud Platonem Gorgias. Quae si ita accipitur, ut sermo quacunque de re compositus dicatur oratio, non materia sed opus est, ut statuarii statua; nam et oratio efficitur arte sicut statua. Sin hac appellatione verba ipsa significari putamus, nihil haec sine rerum substantia faciunt.", "st": "2.21.1"}, {"sp": "N", "t": "Quidam argumenta persuasibilia; quae et ipsa in parte sunt operis et arte fiunt et materia egent. Quidam civiles quaestiones; quorum opinio non qualitate sed modo erravit, est enim haec materia rhetorices sed non sola.", "st": "2.21.2"}, {"sp": "N", "t": "Quidam, quia virtus sit rhetorice, materiam eius totam vitam vocant. Alii, quia non omnium virtutum materia sit tota vita, sed pleraeque earum versentur in partibus, sicut iustitia, fortitudo, continentia propriis officiis et suo fine intelliguntur, rhetoricen quoque dicunt in una aliqua parte ponendam, eique locum in ethice negotialem adsignant id est πραγματικόν.", "st": "2.21.3"}, {"sp": "N", "t": "Ego (neque id sine auctoribus) materiam esse rhetorices iudico omnes res quaecunque ei ad dicendum subiectae erunt. Nam Socrates apud Platonem dicere Gorgiae videtur, non in verbis esse materiam sed in rebus. Et in Phaedro palam, non in iudiciis modo et contionibus, sed in rebus etiam privatis ac domesticis rhetoricen esse demonstrat.", "st": "2.21.4"}, {"sp": "N", "t": "Quo manifestum est hanc opinionem ipsius Platonis fuisse. Et Cicero quodam loco materiam rhetorices vocat res, quae subiectae sint ei, sed certas demum putat esse subiectas. Alio vero de omnibus rebus oratori dicendum arbitratur his quidem verbis: <em>Quanquam vis oratoris professioque ipsa bene dicendi hoc suscipere ac polliceri videtur, ut omni de re, quaecunque sit proposita, ornate ab eo copioseque dicatur.<\/em>", "st": "2.21.5"}, {"sp": "N", "t": "Atque adhuc alibi: <em>Vero enim oratori, quae sunt in hominum vita, quandoquidem in ea versatur orator atque ea est ei subiecta materies, omnia quaesita, audita, lecta, disputata, tractata, agitata esse debent.<\/em>", "st": "2.21.6"}, {"sp": "N", "t": "hanc autem, quam nos materiam vocamus, id est res subiectas, quidam modo infinitam modo non propriam rhetorices esse dixerunt, eamque artem circumcurrentem vocaverunt, quod in omni materia diceret, cum quibus mihi minima pugna est.", "st": "2.21.7"}, {"sp": "N", "t": "Nam de omni materia dicere eam fatentur; propriam habere materiam, quia multiplicem habeat, negant. Sed neque infinita est, etiamsi est multiplex; et aliae quoque artes minores habent multiplicem materiam, velut architectonice, namque ea in omnibus, quae sunt aedificio utilia, versatur, et caelatura, quae auro, argento, aere, ferro opera efficit.", "st": "2.21.8"}, {"sp": "N", "t": "Nam sculptura etiam lignum, ebur, marmor, vitrum, gemmas praeter ea quae supra dixi complectitur.", "st": "2.21.9"}, {"sp": "N", "t": "Neque protinus non est materia rhetorices, si in eadem versatur et alius. Nam si quaeram, quae sit materia statuarii, dicetur aes; si quaeram quae sit excusoris, id est fabricae eius quam Graeci χαλκευτικήν vocant, similiter aes esse respondeant. Atqui plurimum statuis differunt vasa.", "st": "2.21.10"}, {"sp": "N", "t": "Nec medicina ideo non erit ars, quia unctio et exercitatio cum palaestrica, ciborum vero qualitas etiam cum cocorum ei sit arte communis.", "st": "2.21.11"}, {"sp": "N", "t": "Quod vero de bono, utili, iusto disserere philosophiae officium esse dicunt, non obstat. Nam cum philosophum dicunt, hoc accipi volunt virum bonum. Quare igitur oratorem, quem a bono viro non separo, in eadem materia versari mirer?", "st": "2.21.12"}, {"sp": "N", "t": "cum praesertim primo libro iam ostenderim, philosophos omissam hanc ab oratoribus partem occupasse, quae rhetorices propria semper fuisset, ut illi potius in nostra materia versentur. Denique cum sit dialectices materia de rebus subiectis disputare, sit autem dialectice oratio concisa, cur non eadem perpetuae quoque materia videatur?", "st": "2.21.13"}, {"sp": "N", "t": "Solet a quibusdam et illud opponi: <em>Omnium igitur artium peritus erit orator, si de omnibus ei dicendum est.<\/em> Possem hic Ciceronis respondere verbis, apud quem hoc invenio: <em>Mea quidem sententia nemo esse poterit omni laude cumulatus orator, nisi erit omnium rerum<\/em> magnarum atque artium scientiam consecutus; sed mihi satis est eius esse oratorem rei de qua dicet non inscium.", "st": "2.21.14"}, {"sp": "N", "t": "Neque enim omnes causas novit, et debet posse de omnibus dicere. De quibus ergo dicet? De quibus didicit. Similiter de artibus quoque, de quibus dicendum erit, interim discet; et de quibus didicerit dicet.", "st": "2.21.15"}, {"sp": "N", "t": "Quid ergo? non faber de fabrica melius aut de musice musicus? Si nesciat orator, quid sit, de quo quaeratur, plane melius. Nam et litigator rusticus illitteratusque de causa sua melius, quam orator, qui nesciet quid in lite sit; sed accepta a musico, a fabro, sicut a litigatore melius orator quam ipse qui docuerit.", "st": "2.21.16"}, {"sp": "N", "t": "Verum et faber, cum de fabrica, et musicus, cum de musica, si quid confirmationem desideraverit, dicet. Non quidem erit orator, sed faciet illud quasi orator, sicut cum vulnus imperitus deligabit, non erit medicus, sed faciet ut medicus.", "st": "2.21.17"}, {"sp": "N", "t": "An huiusmodi res neque in laudem neque in deliberationem neque in iudicium veniunt? Ergo cum de faciendo portu Ostiensi deliberatum est, non debuit sententiam dicere orator? atqui opus erat ratione architectorum.", "st": "2.21.18"}, {"sp": "N", "t": "Livores et tumores in corpore cruditatis an veneni signa sint, non tractat orator? at est id ex ratione medicinae. Circa mensuras et numeros non versabitur? dicamus has geometriae esse partes. Equidem omnia fere credo posse casu aliquo venire in officium oratoris; quod si non accidet, non erunt ei subiecta.", "st": "2.21.19"}, {"sp": "N", "t": "Ita sic quoque recte diximus, materiam rhetorices esse omnes res ad dicendum ei subiectas; quod quidem probat etiam sermo communis. Nam cum aliquid, de quo dicamus, accepimus, positam nobis esse materiam frequenter etiam praefatione testamur.", "st": "2.21.20"}, {"sp": "N", "t": "Gorgias quidem adeo rhetori de omnibus rebus putavit esse dicendum, ut se in auditoriis interrogari pateretur, qua quisque de re vellet. Hermagoras quoque, dicendo materiam esse in causa et in quaestionibus, omnes res subiectas erat complexus.", "st": "2.21.21"}, {"sp": "N", "t": "Sed quaestiones si negat ad rhetoricen pertinere, dissentit a nobis; si autem ad rhetoricen pertinent, ab hoc quoque adiuvamur. Nihil est enim, quod non in causam aut quaestionem cadat.", "st": "2.21.22"}, {"sp": "N", "t": "Aristoteles tres faciendo partes orationis, iudicialem, deliberativam, demonstrativam, paene et ipse oratori subiecit omnia; nihil enim non in haec cadit.", "st": "2.21.23"}, {"sp": "N", "t": "Quaesitum a paucissimis et de instrumento est. Instrumentum voco, sine quo formari materia in id quod velimus effici opus non possit. Verum hoc ego non artem credo egere sed artifice. Neque enim scientia desiderat instrumentum, quae potest esse consummata, etiamsi nihil faciat, sed ille artifex, ut caelator caelum et pictor penicilla. Itaque haec in eum locum, quo de oratore dicturi sumus, differamus.", "st": "2.21.24"}, {"sp": "HDR", "t": "Liber III", "st": "3"}, {"sp": "N", "t": "Quoniam in libro secundo quaesitum est, quid esset rhetorice et quis finis eius, artem quoque esse eam et utilem et virtutem, ut vires nostrae tulerunt, ostendimus, materiamque ei res omnes, de quibus dicere oporteret, subiecimus: iam hinc, unde coeperit, quibus constet, quo quaeque in ea modo invenienda atque tractanda sint, exsequar; intra quem modum plerique scriptores artium constiterunt, adeo ut Apollodorus contentus solis iudicialibus fuerit.", "st": "3.1.1"}, {"sp": "N", "t": "Nec sum ignarus, hoc a me praecipue, quod hic liber inchoat, opus studiosos eius desiderasse, ut inquisitione opinionum, quae diversissimae fuerunt, longe difficillimum, ita nescio an minimae legentibus futurum voluptati, quippe quod prope nudam praeceptorum traditionem desideret.", "st": "3.1.2"}, {"sp": "N", "t": "In ceteris enim admiscere temptauimus aliquid nitoris, non iactandi ingenii gratia (namque in id eligi materia poterat uberior), sed ut hoc ipso adliceremus magis iuventutem ad cognitionem eorum, quae necessaria studiis arbitrabamur, si ducti iucunditate aliqua lectionis libentius discerent ea, quorum ne ieiuna atque arida traditio averteret animos et aures praesertim tam delicatas raderet uerebamur.", "st": "3.1.3"}, {"sp": "N", "t": "Qua ratione se Lucretius dicit praecepta philosophiae carmine esse complexum; namque hac, ut est notum, similitudine utitur:<br>Ac veluti pueris absinthia taetra medentes<br>Cum dare conantur, prius oras pocula circum<br>Aspirant mellis dulci flauoque liquore,<br>et quae sequuntur.", "st": "3.1.4"}, {"sp": "N", "t": "Sed nos ueremur, ne parum hic liber mellis et absinthi multum habere videatur, sitque salubrior studiis quam dulcior. Quin etiam hoc timeo, ne ex eo minorem gratiam ineat, quod pleraque non inventa per me sed ab aliis tradita continebit, habeat etiam quosdam, qui contra sentiant et adversentur, propterea quod plurimi auctores, quamvis eodem tenderent, diversas tamen vias muniverunt atque in suam quisque induxit sequentes.", "st": "3.1.5"}, {"sp": "N", "t": "Illi autem probant qualecunque ingressi sunt iter, nec facile inculcatas pueris persuasiones mutaveris, quia nemo non didicisse mavult quam discere.", "st": "3.1.6"}, {"sp": "N", "t": "Est autem, ut procedente libro patebit, infinita dissensio auctorum, primo ad ea, quae rudia atque inperfecta adhuc erant, adiicientibus quod inuenissent scriptoribus, mox, ut aliquid sui viderentur adferre, etiam recta mutantibus.", "st": "3.1.7"}, {"sp": "N", "t": "Nam primus post eos, quos poetae tradiderunt, movisse aliqua circa rhetoricen Empedocles dicitur. Artium autem scriptores antiquissimi Corax et Tisias Siculi, quos insecutus est vir eiusdem insulae Gorgias Leontinus, Empedoclis, ut traditur, discipulus.", "st": "3.1.8"}, {"sp": "N", "t": "Is beneficio longissimae aetatis (nam centum et novem vixit annos) cum multis simul floruit, ideoque et illorum, de quibus supra dixi, fuit aemulus et ultra Socraten usque duravit.", "st": "3.1.9"}, {"sp": "N", "t": "Thrasymachus Chalcedonius cum hoc et Prodicus Cius et Abderites Protagoras, a quo decem milibus denariorum didicisse artem, quam edidit, Euathlus dicitur, et Hippias Elius et, quem Palameden Plato appellat, Alcidamas Elaïtes.", "st": "3.1.10"}, {"sp": "N", "t": "Antiphon quoque et orationem primus omnium scripsit et nihilo minus et artem ipse composuit et pro se dixisse optime est creditus, etiam Polycrates, a quo scriptam in Socraten diximus orationem, et Theodorus Byzantius ex iis et ipse, quos Plato appellat λογοδαιδάλους", "st": "3.1.11"}, {"sp": "N", "t": "Horum primi communes locos tractasse dicuntur Protagoras, Gorgias, adfectus Prodicus et Hippias et idem Protagoras et Thrasymachus. Cicero in Bruto negat ante Periclea scriptum quidquam, quod ornatum oratorium habeat; eius aliqua ferri. Equidem non reperio quidquam tanta eloquentiae fama dignum; ideoque minus miror esse, qui nihil ab eo scriptum patent, haec autem, quae feruntur, ab alis esse composite.", "st": "3.1.12"}, {"sp": "N", "t": "His successere multi, sed clarissimus Gorgiae auditorum Isocrates, quanquam de praeceptore eius inter auctores non convenit; nos autem Aristoteli credimus. Hinc velut diversae secari coeperunt viae.", "st": "3.1.13"}, {"sp": "N", "t": "Nam et Isocratis praestantissimi discipuli fuerunt in omni studiorum genere, eoque iam seniore (octavum enim et nonagesimum implevit annum) postmeridianis scholis Aristoteles praecipere artem oratoriam coepit, noto quidem illo (ut traditur) versu ex Philocteta frequenter usus: <em>Turpe esse tacere et Isocraten pati dicere.<\/em> ars est utriusque, sed pluribus eam libris Aristoteles complexus est. Eodem tempore Theodectes fuit, de cuius opere supra dictum est.", "st": "3.1.14"}, {"sp": "N", "t": "Theophrastus quoque Aristotelis discipulus de rhetorice diligenter scripsit, atque hinc vel studiosius philosophi quam rhetores praecipueque Stoicorum ac Peripateticorum principes.", "st": "3.1.15"}, {"sp": "N", "t": "Fecit deinde velut propriam Hermagoras viam, quam plurimi sunt secuti; cui maxime par atque aemulus videtur Athenaeus fuisse. Multa post Apollonius Molon, multa Areus, multa Caecilius et Halicarnasseus Dionysius.", "st": "3.1.16"}, {"sp": "N", "t": "Praecipue tamen in se converterunt studia Apollodorus Pergamenus, qui praeceptor Apolloniae Caesaris Augusti fuit, et Theodorus Gadareus, qui se dici maluit Rhodium, quem studiose audisse, cum in eam insulam secessisset, dicitur Tiberius Caesar.", "st": "3.1.17"}, {"sp": "N", "t": "Hi diversas opiniones tradiderunt, appellatique inde Apollodorei ac Theodorei ad morem certas in philosophia sectas sequendi. Sed Apollodori praecepta magis ex discipulis cognoscas, quorum diligentissimus in tradendo fuit Latine Gaius Valgius, Graece Atticus. Nam ipsius sola videtur Ars edita ad Matium, quia ceteras missa ad Domitium epistula non agnoscit. Plura scripsit Theodorus, cuius auditorem Hermagoran sunt qui viderint.", "st": "3.1.18"}, {"sp": "N", "t": "Romanorum primus (quantum ego quidem sciam) condidit aliqua in hanc materiam M. Cato ille censorius, post M. Antonius inchoavit; nam hoc solum opus eius atque id ipsum imperfectum manet. Secuti minus celebres; quorum memoriam, si quo loco res poscet, non omittam.", "st": "3.1.19"}, {"sp": "N", "t": "Praecipuum vero lumen sicut eloquentiae ita praeceptis quoque eius dedit, unicum apud nos specimen orandi docendique oratorias artes, M. Tullius; post quem tacere modestissimum foret, nisi et rhetoricos suos ipse adulescenti sibi elapsos diceret, et in oratoriis haec minora, quae plerumque desiderantur, sciens omisisset.", "st": "3.1.20"}, {"sp": "N", "t": "Scripsit de eadem materia non pauca Cornificius, aliqua Stertinius, nonnihil paler (Gallio; accuratius vero priores Gallione Celsus et Laenas et aetatis nostrae Verginius, Plinius, Tutilius. Sunt et hodie clari eiusdem operis auctores, qui si omnia complexi forent, consuluissent labori meo; sed parco nominibus viventium; ueniet eorum laudi suum tempus, ad posteros enim virtus durabit, non perveniet invidia.", "st": "3.1.21"}, {"sp": "N", "t": "Non tamen post tot ac tantos auctores pigebit meam quibusdam locis posuisse sententiam. Neque enim me cuiusquam sectae velut quadam superstitione imbutus addixi, et electuris quae volent facienda copia fuit, sicut ipse plurium in unum confero inventa, ubicunque ingenio non erit locus, curae testimonium meruisse contentus.", "st": "3.1.22"}, {"sp": "N", "t": "Nec diu nos moretur quaestio, quae rhetorices origo sit. Nam cui dubium est, quia; sermonem ab ipsa rerum natura geniti protinus homines acceperint (quod certe principium est eius rei), huic studium et incrementum dederit utilitas, summam ratio et exercitatio?", "st": "3.2.1"}, {"sp": "N", "t": "Nec video, quare curam dicendi patent quidam inde coepisse, quod ii, qui in discrimen aliquod vocabantur, accuratius loqui defendendi sui gratia instituerint. Haec enim ut honestior causa, ita non utique prior est, cum praesertim accusatio praecedat defensionem; nisi quis dicet, etiam gladium fabricatum ab eo prius, qui ferrum in tutelam sui quam qui in perniciem alterius compararit.", "st": "3.2.2"}, {"sp": "N", "t": "Initium ergo dicendi dedit natura, initium artis observatio. Homines enim, sicuti in medicina, cum viderent alia salubria, alia insalubria, ex observatione eorum effecerunt artem, ita, cum in dicendo alia utilia, alia inutilia deprehenderent, notarunt ea ad imitandum vitandumque, et quaedam secundum rationem eorum adiecerunt ipsi quoque; haec confirmata sunt usu, tum quae sciebat quisque docuit.", "st": "3.2.3"}, {"sp": "N", "t": "Cicero quidem initium orandi conditoribus urbium ac legum latoribus dedit, in quibus fuisse vim dicendi necesse est; cur tamen hanc primam originem putet, non video, cum sint adhuc quaedam vagae et sine urbibus ac sine legibus gentes, et tamen qui sunt in iis nati et legationibus fungantur et accusent aliqua atque defendant et denique alium alio melius loqui credant.", "st": "3.2.4"}, {"sp": "N", "t": "Omnis autem orandi ratio, ut plurimi maximique auctores tradiderunt, quinque partibus constat, inventione, dispositione, elocutione, memoria, pronuntiatione sive actione, utroque enim modo dicitur. Omnis vero sermo, quo quidem voluntas aliqua enuntiatur, habeat necesse est rem et verba.", "st": "3.3.1"}, {"sp": "N", "t": "Ac si est brevis et una conclusione finitus, nihil fortasse ultra desideret; at oratio longior plura exigit. Non tantum enim refert, quid et quo modo dicamus, sed etiam quo loco; opus ergo est et dispositione. Sed neque omnia, quae res postulat, dicere neque suo quaeque loco poterimus nisi adiuvante memoria; quapropter ea quoque pars quarta erit.", "st": "3.3.2"}, {"sp": "N", "t": "Verum haec cuncta corrumpit ac propemodum perdit indecora vel voce vel gestu pronuntiatio. Huic quoque igitur tribuendus est necessario quintus locus.", "st": "3.3.3"}, {"sp": "N", "t": "Nec audiendi quidam, quorum est Albucius, qui tris modo primas esse partes volunt, quoniam memoria atque actio natura non arte contigant: quarum nos praecepta suo loco dabimus; licet Thrasymachus quoque idem de actione crediderit.", "st": "3.3.4"}, {"sp": "N", "t": "His adiecerunt quidam sextam partem, ita ut inventioni iudicium subnecterent, quia primum esset invenire, deinde iudicare. Ego porro ne invenisse quidem credo eum, qui non iudicavit; neque enim contraria, communia, stulta invenisse dicitur quisquam, sed non vitasse.", "st": "3.3.5"}, {"sp": "N", "t": "Et Cicero quidem in Rhetoricis iudicium subiecit invention; mihi autem adeo tribus primis partibus videtur esse permixtum (nam neque dispositio sine eo neque elocutio fuerit), ut pronuntiationem quoque vel plurimum ex eo mutuari putem.", "st": "3.3.6"}, {"sp": "N", "t": "Quod hoc audacius dixerim, quod in Partitionibus oratoriis ad easdem, de quibus supra dictum est, quinque pervenit partes. Nam cum dupliciter primum divisisset in inventionem atque elocutionem, res ac dispositionem inventioni, verba et pronuntiationem elocutioni dedit quintamque constituit, communem ac velut custodem omnium, memoriam. Idem in Oratore quinque rebus constare eloquentiam dicit, in quibus postea scriptis certior eius sententia est.", "st": "3.3.6"}, {"sp": "N", "t": "Non minus mihi cupidi novitatis alicuius videntur fuisse, qui adiecerunt ordinem, cum dispositionem dixissent, quasi aliud sit dispositio quam rerum ordine quam optimo collocatio. Dion inventionem modo et dispositionem tradidit sed utramque duplicem, rerum et verborum, ut sit elocutio inventionis, pronuntiatio dispositionis, his quinta pars memoriae, accedat. Theodorei fere inventionem duplicem, rerum atque elocutionis, deinde tris ceteras partes.", "st": "3.3.8"}, {"sp": "N", "t": "Hermagoras iudicium, partitionem, ordinem, quaeque sunt elocutionis, subiicit oeconomiae, quae Graece appellata ex cura rerum domesticarum et hic per abusionem posita nomine Latino caret.", "st": "3.3.9"}, {"sp": "N", "t": "Est et circa hoc quaestio, quod memoriam in ordine partium quidam inventioni, quidam dispositioni subiunxerunt; nobis quartus eius locus maxime placet. Non enim tantum inventa tenere, ut disponamus, nec disposita, ut eloquamur, sed etiam verbis formata memoriae mandare debemus. Hac enim omnia, quaecunque in orationem collata sunt, continentur.", "st": "3.3.10"}, {"sp": "N", "t": "Fuerunt etiam in hac opinione non pauci, ut has non rhetorices partes esse existimarent sed opera oratoris; eius enim esse invenire, disponere, eloqui et cetera.", "st": "3.3.11"}, {"sp": "N", "t": "Quod si accipimus, nihil arti relinquemus. Nam bene dicere est oratoris, rhetorice tamen erit bene dicendi scientia; vel, ut alii putant, artificis est persuadere, vis autem persuadendi artis. Ita invenire quidem et disponere oratoris, inventio autem et dispositio rhetorices propria videri potest.", "st": "3.3.12"}, {"sp": "N", "t": "In eo plures dissenserunt, utrumne hae partes essent rhetorices an eiusdem opera an, ut Athenaeus credit, elementa, quae vocant στοιχεῖα Sed neque elementa recte quis dixerit, alioqui tantum initia erunt, ut mundi vel umor vel ignis vel materia vel corpora insecabilia; nec operum recte nomen accipient, quae non ab allis perficiuntur, sed aliud ipsa perficiunt: partes igitur.", "st": "3.3.13"}, {"sp": "N", "t": "Nam cum sit ex his rhetorice, fieri non potest ut, cum totum ex partibus constet, non sint partes totius ex quibus constat. Videntur autem mihi, qui haec opera dixerunt, eo quoque moti, quod in alia rursus divisione nollent in idem nomen incidere, partes enim rhetorices esse dicebant laudativam, deliberativam, iudicialem. Quae si partes sunt, materiae sunt potius quam artis.", "st": "3.3.14"}, {"sp": "N", "t": "Namque in his singulis rhetorice tota est, quia et inventionem et dispositionem et elocutionem et memoriam et pronuntiationem quaecunque earum desiderat. Itaque quidam genera tria rhetorices dicere maluerunt, optime autem ii, quos secutus est Cicero, genera causarum.", "st": "3.3.15"}, {"sp": "N", "t": "Sed tria an plura sint, ambigitur. Nec dubie prope omnes utique summae apud antiquos auctoritatis scriptores Aristotelem secuti, qui nomine tantum alio contionalem pro deliberativa appellat, hac partitione contenti fuerunt.", "st": "3.4.1"}, {"sp": "N", "t": "Verum et tum leviter est temptatum, cum apud Graecos quosdam tum apud Ciceronem in libris de Oratore, et nunc maximo temporum nostrorum auctore prope impulsum, ut non modo plura haec genera, sed paene innumerabilia videantur.", "st": "3.4.2"}, {"sp": "N", "t": "Nam si laudandi ac vituperandi officium in parte tertia ponimus, in quo genere versari videbimur, cum querimur, consolamur, mitigamus, concitamus, terremus, confirmamus, praecipimus, obscure dicta interpretamur, narramus, deprecamur, gratias agimus, gratulamur, obiurgamus, maledicimus, describimus, mandamus, renuntiamus, optamus, opinamur, plurima alia?", "st": "3.4.3"}, {"sp": "N", "t": "ut mihi in illa vetere persuasione permanenti velut petenda sit venia, quaerendunque, quo moti priores rem tam late fusam tam breviter astrinxerint. Quos qui errasse putant, hoc secutos arbitrantur, quod in his fere versari tum oratores videbant;", "st": "3.4.4"}, {"sp": "N", "t": "nam et laudes ac vituperationes scribebantur, et ἐπιταφίους dicere erat moris, et plurimum in consiliis ac iudiciis insumebatur operae, ut scriptores artium pro solis comprehenderint frequentissima.", "st": "3.4.5"}, {"sp": "N", "t": "Qui vero defendunt, tria faciunt genera auditorum, unum, quod ad delectationem conveniat, alterum, quod consilium accipiat, tertium, quod de causis iudicet. Mihi cuncta rimanti et talis quaedam ratio succurrit, quod omne orationis officium aut in iudiciis est aut extra iudicia.", "st": "3.4.6"}, {"sp": "N", "t": "Eorum, de quibus iudicio quaeritur, manifestum est genus; ea, quae ad iudicem non veniunt, aut praeteritum habent tempus aut futurum; praeterita laudamus aut vituperamus, de futuris deliberamus.", "st": "3.4.7"}, {"sp": "N", "t": "Item omnia, de quibus dicendum est, aut certa sint necesse est aut dubia. Certa, ut cuique est animus, laudat aut culpat; ex dubiis partim nobis ipsis ad electionem sunt libera, de his deliberatur; partim aliorum sententiae commissa, de his lite contenditur.", "st": "3.4.8"}, {"sp": "N", "t": "Anaximenes iudicialem et contionalem generales partes esse voluit, septem autem species: hortandi, dehortandi, laudandi, vituperandi, accusandi, defendendi, exquirendi, quod ἐξεταστικόν dicit; quarum duae primae deliberativi, duae sequentes demonstrativi, tres ultimae iudicialis generis sunt partes.", "st": "3.4.9"}, {"sp": "N", "t": "Protagoran transeo, qui interrogandi, respondendi, mandandi, precandi, quod εὐχωλήν dixit, partes solas putat. Plato in Sophiste iudiciali et contionali tertiam adiecit προσομιλητικήν, quam sane permittamus nobis dicere sermocinatricem; quae a forensi ratione diiungitur et est accommodata privatis disputationibus, cuius vis eadem profecto est quae dialecticae.", "st": "3.4.10"}, {"sp": "N", "t": "Isocrates in omni genere inesse laudem ac vituperationem existimavit. Nobis et tutissimum est auctores plurimos sequi, et ita videtur ratio dictare.", "st": "3.4.11"}, {"sp": "N", "t": "Est igitur, ut dixi, unum genus, quo laus ac uituperatio continetur, sed est appellatum a parte meliore laudativum; idem alii demonstrativum vocant. Utrumque nomen ex Graeco creditur fluxisse, nam ἐγκωμιαστικόν aut ἐπιδεικτικόν dicunt.", "st": "3.4.12"}, {"sp": "N", "t": "Sed mihi ἐπιδεικτικόν non tam demonstrationis vim habere quam ostentationis videtur et multum ab illo ἐγκωμιαστικῷ differre; nam ut continet laudativum in se genus, ita non intra hoc solum consistit.", "st": "3.4.13"}, {"sp": "N", "t": "An quisquam negaverit Panegyricos ἐπιδεικτικούς esse? Atqui formam suadendi habent et plerumque de utilitatibus Graeciae loquuntur; ut causarum quidem genera tria sint, sed ea tum in negotiis tum in ostentatione posita. Nisi forte non ex Graeco mutantes demonstrativum vocant, uerum id sequuntur, quod laus ac uituperatio quale sit quidque demonstrat.", "st": "3.4.14"}, {"sp": "N", "t": "Alterum est deliberativum, tertium iudiciale. Ceterae species in haec tria incident genera, nec invenietur ex his ulla, in qua non laudare ac vituperare, suadere ac dissuadere, intendere quid vel depellere debeamus. Illa quoque sunt communia, conciliare, narrare, docere, augere, minuere, concitandis componendisve adfectibus animos audientium fingere.", "st": "3.4.15"}, {"sp": "N", "t": "Ne iis quidem accesserim, qui laudativam materiam honestorum, deliberatiuam utilium, iudicialem iustorum quaestione contineri putant, celeri magis ac rotunda usi distributione quam vera. Stant enim quodam modo mutuis auxiliis omnia. Nam et in laude iustitia utilitasque tractatur et in consiliis honestas, et raro iudicialem inveneris causam, in cuius non parte aliquid eorum, quae supra diximus, reperiatur.", "st": "3.4.16"}, {"sp": "N", "t": "Omnis autem oratio constat aut ex iis, quae significantur, aut et iis, quae significant, id est rebus et verbis. Facultas orandi consummatur natura, arte, exercitatione, cui partem quartam adiiciunt quidam imitationis, quam nos arti subiicimus.", "st": "3.5.1"}, {"sp": "N", "t": "Tria sunt item, quae praestare debeat orator; ut doceat, moveat, delectet. Haec enim clarior divisio quam eorum, qui totum opus in res et in adfectus partiuntur. Non semper autem omnia in eam quae tractabitur materiam cadent. Erunt enim quaedam remotae ab adfectibus, qui ut non ubique habent locum, ita quocunque irruperunt, plurimum valent.", "st": "3.5.2"}, {"sp": "N", "t": "Praestantissimis auctoribus placet alia in rhetorice esse, quae probationem desiderent, alia quae non desiderent, cum quibus ipse consentio. Quidam vero, ut Celsus, de nulla re dicturum oratorem, nisi de qua quaeratur, existimant, cui cum maxima pars scriptorum repugnat tum etiam ipsa partitio; nisi forte laudare, quae constet esse honesta, et vituperare, quae ex confesso sint turpia, non est oratoris officium.", "st": "3.5.3"}, {"sp": "N", "t": "Illud iam omnes fatentur, esse quaestiones aut in scripto aut in non scripto; in scripto de iure, in non scripto de re. Illud rationale hoc legale genus Hermagoras atque eum secuti vocant, id est νομικόν et λογικόν.", "st": "3.5.4"}, {"sp": "N", "t": "Idem sentiunt, qui omnem quaestionem ponunt in rebus et in verbis. Item convenit, quaestiones esse aut infinitas aut finitas. Infinitae sunt, quae remotis personis et temporibus et locis ceterisque similibus in utramque partem tractantur, quod Graeci θέσιν dicunt, Cicero propositum, alii quaestiones universales civiles, alii quaestiones philosopho convenientes, Athenaeus partem causae appellat.", "st": "3.5.5"}, {"sp": "N", "t": "Hoc genus Cicero scientia et actione distinguit, ut sit scientiae, <em>An providentia mundus regatur;<\/em> actionis, <em>An accedendum ad rempublicam administrandam.<\/em> Prius trium generum, an sit? quid sit? quale sit? omnia enim haec ignorari possunt; sequens duorum, quo modo adipiscamur? quo modo utamur?", "st": "3.5.6"}, {"sp": "N", "t": "Finitae autem sunt ex complexu rerum personarum temporum ceterorumque; hae ὑποθέσεις a Graecis dicuntur, causae a nostris. In his omnis quaestio videtur circa res personasque consistere.", "st": "3.5.7"}, {"sp": "N", "t": "Amplior est semper infinite, inde enim finita descendit. Quod ut exemplo pateat, infinita est, <em>An uxor ducenda?<\/em> finita, <em>An Catoni ducenda?<\/em> ideoque esse suasoria potest. Sed etiam remotae personis propriis ad aliquid referri solent. Est enim simplex, <em>An respublica administranda?<\/em> refertur ad aliquid, <em>An in tyrannide administranda?<\/em>", "st": "3.5.8"}, {"sp": "N", "t": "Sed hic quoque; subest velut latens persona:; tyrannus enim geminat quaestionem, subestque et temporis et qualitatis tacita vis; nondum tamen hoc proprie dixeris causam. Hae autem, quas infinitas voco, et generales appellantur; quod si est verum, finitae speciales erunt. In omni autem speciali utique inest generalis, ut quae sit prior.", "st": "3.5.9"}, {"sp": "N", "t": "Ac nescio an in causis quoque, quidquid in quaestionem venit qualitatis, generale sit. <em>Milo Clodium occidit, iure occidit insidiatorem;<\/em> nonne hoc quaeritur, <em>An sit ius insidiatorem occidendi?<\/em> Quid in coniecturis? non illa generalia, <em>An causa sceleris odium? cupiditas? An tormentis credendum? Testibus an argumentis maior fides habenda?<\/em> Nam finitione quidem comprehendi nihil non in universum certum erit.", "st": "3.5.10"}, {"sp": "N", "t": "Quidam putant etiam eas thesis posse aliquando nominari, quae personis causisque contineantur, aliter tantummodo positas: ut causa sit, cum <em>Orestes accusatur:<\/em> thesis, <em>An Orestes recte sit absolutus;<\/em> cuius generis est, <em>An Cato recte Marciam Hortensio tradiderit.<\/em> Hi thesin a causa sic distinguunt, ut illa sit spectativae partis, haec activae; illic enim veritatis tantum gratia disputari, hic negotium agi.", "st": "3.5.11"}, {"sp": "N", "t": "Quanquam inutiles quidam oratori putant universales quaestiones, quia nihil prosit, quod constet ducendam esse uxorem vel administrandam rempublicam, si quis vel aetate vel valetudine impediatur. Sed non omnibus eiusmodi quaestionibus sic occurri potest, ut illis, sitne virtus finis? regaturne providentia mundus?", "st": "3.5.12"}, {"sp": "N", "t": "Quin etiam in iis, quae ad personam referuntur, ut non est satis generalem tractasse quaestionem, ita perveniri ad speciem nisi illa prius excussa non potest. Nam quomodo, an sibi uxor ducenda sit, deliberabit Cato, nisi constiterit, uxores esse ducendas? Et quomodo, an ducere debeat Marciam, quaeretur, nisi Catoni ducenda uxor est?", "st": "3.5.13"}, {"sp": "N", "t": "Sunt tamen inscripti nomine Hermagorae libri, qui confirmant illam opinionem, sive falsus est titulus sive alius hic Hermagoras fuit. Nam eiusdem esse quomodo possunt, qui de hac arte mirabiliter multa composuit, cum, sicut ex Ciceronis quoque rhetorico primo manifestum est, materiam rhetorices in thesis et causas diviserit? Quod reprehendit Cicero ac thesin nihil ad oratorem pertinere contendit totumque hoc genus quaestionis ad philosophos refert.", "st": "3.5.14"}, {"sp": "N", "t": "Sed me liberavit respondendi verecundia, et quod ipse hos libros improbat, et quod in Oratore atque his, quos de Oratore scripsit, et Topicis praecipit, ut a propriis personis atque temporibus avocemus controversiam: quia latius dicere liceat de genere quam de specie, et, quod in universo probatum sit, in parte probatum esse necesse sit.", "st": "3.5.15"}, {"sp": "N", "t": "Status autem in hoc omne genus materiae iidem, qui in causas, cadunt. Adhuc adiicitur, alias esse quaestiones in rebus ipsis, alias quae ad aliquid referantur: illud, <em>An uxor ducenda?<\/em> hoc, <em>An seni ducenda?<\/em> illud, <em>An fortis?<\/em> hoc, <em>An fortior?<\/em> et similia.", "st": "3.5.16"}, {"sp": "N", "t": "Causam finit Apollodorus, ut interpretation Valgi discipuli eius utar, ita: <em>Causa est negotium omnibus suis partibus spectans ad quaestionem;<\/em> aut: <em>Causa est negotium, cuius finis est controversia.<\/em> Ipsum deinde negotium sic finit: <em>Negotium est congregatio personarum, locorum, temporum, causarum, modorum, casuum, factorum, instrumentorum, sermonum, scriptorum et non scriptorum.<\/em>", "st": "3.5.17"}, {"sp": "N", "t": "Causam nunc intelligamus ὑπόθεσιν, negotium περίστασιν. Sed et ipsam causam quidam similiter finierunt, ut Apollodorus negotium. Isocrates autem causam esse ait quaestionem finitam civilem aut rem controversam in personarum finitarum complexu; Cicero his verbis: <em>Causa certis personis, locis, temporibus, actionibus, negotiis cernitur, aut in omnibus aut in plerisque eorum.<\/em>", "st": "3.5.18"}, {"sp": "N", "t": "Ergo cum omnis causa contineatur aliquo statu, priusquam dicere aggredior, quo modo genus quodque causae sit tractandum, id quod est commune omnibus, quid sit status et unde ducatur et quot et qui sint, intuendum puto. Quanquam id nonnulli ad iudiciales tantum pertinere materias putaverunt, quorum inscitiam, cum omnia tria genera fuero exsecutus, res ipsa deprehendet.", "st": "3.6.1"}, {"sp": "N", "t": "Quod nos statum, id quidam constitutionem vocant, alii quaestionem, alii quod ex quaestione appareat, Theodorus <em>caput<\/em> id est κεφάλαιον γενικώτατον, ad quod referantur omnia. Quorum diversa appellatio, vis eadem est; nec interest discentium, quibus quidque nominibus appelletur, dum res ipsa manifesta sit.", "st": "3.6.2"}, {"sp": "N", "t": "Statum Graeci στάσιν vocant, quod nomen non primum ab Hermagora traditum putant, sed alii ab Naucrate, Isocratis discipulo, alii a Zopyro Clazomenio; quanquam videtur Aeschines quoque in oratione contra Ctesiphontem uti hoc verbo, cum a iudicibus petit, ne Demostheni permittant evagari, sed eum dicere de ipso causae statu cogant.", "st": "3.6.3"}, {"sp": "N", "t": "Quae appellatio dicitur ducta vel ex eo, quod ibi sit primus causae congressus, vel quod in hoc causa consistat. Et nominis quidem haec origo; nunc quid sit. Statum quidam dixerunt primam causarum conflictionem; quos recte sensisse, parum elocutos puto.", "st": "3.6.4"}, {"sp": "N", "t": "Non enim est status prima conflictio, <em>fecisti, non feci;<\/em> sed quod ex prima conflictione nascitur, id est genus quaestionis, fecisti, <em>non feci, an fecerit? Hoc fecisti, non hoc feci, quid fecerit?<\/em> Quia ex his apparet, illud coniectura, hoc finitione quaerendum, atque in eo pars utraque insistit, erit quaestio coniecturalis vel finitivi status.", "st": "3.6.5"}, {"sp": "N", "t": "Quid si enim dicat quis, <em>sons est duorum inter se corporum conflictio:<\/em> erret, ut opinor, non enim sonus est conflictio sed ex conflictione. Sed hoc levius; intelligitur enim utcunque dictum. Inde vero ingens male interpretantibus innatus est error, qui, quia primam conflictionem legerant, crediderunt statum semper ex prima quaestione ducendum; quod est vitiosissimum.", "st": "3.6.6"}, {"sp": "N", "t": "Nam quaestio nulla non habet utique statum, constat enim ex intentione et depulsione; sed aliae sunt propriae causarum, de quibus ferenda sententia est, aliae adductae extrinsecus, aliquid tamen ad summam causae conferentes, velut auxilia quaedam, quo fit ut in controversia una plures quaestiones esse dicantur.", "st": "3.6.7"}, {"sp": "N", "t": "Harum porro plerumque levissima quaeque primo loco fungitur. Namque et illud frequens est, ut ea, quibus minus confidimus, cum tractata sunt, omittamus, interim sponte nostra velut donantes, interim ad ea quae sunt potentiora gradum ex iis fecisse contenti.", "st": "3.6.8"}, {"sp": "N", "t": "Simplex autem causa etiamsi varie defenditur, non potest habere plus uno, de quo pronuntietur, atque inde erit status causae, quod et orator praecipue sibi obtinendum et iudex spectandum maxime intelligit; in hoc enim causa consistet. Ceterum quaestionum possunt esse diversi.", "st": "3.6.9"}, {"sp": "N", "t": "Quod ut brevissimo pateat exemplo: cum dicit reus, <em>Etiamsi feci, recte feci,<\/em> qualitatis utitur statu; cum adiicit, <em>sed non feci,<\/em> coniecturam movet. Semper autem firmius est non fecisse, ideoque in eo statum esse iudicabo, quod dicerem, si mihi plus quam unum dicere non liceret.", "st": "3.6.10"}, {"sp": "N", "t": "Recte igitur est appellata causarum prima conflictio non quaestionum. Nam et pro Rabirio Postumo Cicero prima parte orationis in hoc intendit, ut actionem competere in equitem Romanum neget; secunda, nullam ad eum pecuniam pervenisse confirmat. Statum tamen in eo dicam fuisse, quod est potentius.", "st": "3.6.11"}, {"sp": "N", "t": "Nec in causa Milonis circa primas quaestiones iudicabo conflixisse causam, sed ubi totis viribus insidiator Clodius ideoque iure interfectus ostenditur. Et hoc est, quod ante omnia constituere in animo suo debeat orator, etiamsi pro causa plura dicturus est, quid maxime liquere iudici velit. Quod tamen ut primum cogitandum, ita non utique primum dicendum erit.", "st": "3.6.12"}, {"sp": "N", "t": "Alii statum crediderunt primam eius, cum quo ageretur, deprecationem. Quam sententiam his verbis Cicero complectitur: <em>in quo primum insistit quasi ad repugnandum congressa defensio.<\/em> Unde rursus alia quaestio, an eum semper is faciat qui respondet. Cui rei praecipue repugnat Cornelius Celsus dicens non a depulsione sumi, sed ab eo qui propositionem suam confirmet; ut, si hominem occisum reus negat, status ab accusatore nascatur, quia is velit probare; si iure occisum reus dicit, translata probationis necessitate idem a reo fiat, et sit eius intentio.", "st": "3.6.13"}, {"sp": "N", "t": "Cui non accedo equidem; nam est vero propius quod contra dicitur, nullam esse litem, si is, cum quo agatur, nihil respondeat, ideoque fieri statum a respondente.", "st": "3.6.14"}, {"sp": "N", "t": "Mea tamen sententia varium id est, et accidit pro condicione causarum, quia et videri potest propositio aliquando statum facere, ut in coniecturalibus causis; utitur enim coniectura magis qui agit, (quo moti quidam eundem a reo infitialem esse dixerunt) et in syllogismo tota ratiocinatio ab eo est qui intendit.", "st": "3.6.15"}, {"sp": "N", "t": "Sed quia videtur illic quoque necessitatem hos status exsequendi facere qui negat, (is enim si dicat, <em>non feci,<\/em> coget adversarium coniectura uti; et si dicat, <em>non habes legem,<\/em> syllogismo) concedamus ex depulsione nasci statum. Nihilominus enim res eo revertetur, ut modo is qui agit, modo is cum quo agitur, statum faciat.", "st": "3.6.16"}, {"sp": "N", "t": "Sit enim accusatoris intentio, <em>Hominem occidisti.<\/em> Si negat reus, faciat statum qui negat. Quid si confitetur, sed iure a se adulterum dicit occisum? nempe legem esse certum est quae permittat. Nisi aliquid accusator respondet, nulla lis est. <em>Non fuit,<\/em> inquit, <em>adulter;<\/em> ergo depulsio incipit esse actoris, ille statum faciet. Ita erit quidem status ex prima depulsione, sed ea fiet ab accusatore non a reo.", "st": "3.6.17"}, {"sp": "N", "t": "Quid? quod eadem quaestio potest eundem vel accusatorem facere vel reum: Qui artem ludicram exercuerit, in quattuordecim primis <em>ordinibus ne sedeat;<\/em> qui se praetori in hortis ostenderat neque erat productus, sedit in quattuordecim ordinibus.", "st": "3.6.18"}, {"sp": "N", "t": "Nempe intentio est: <em>Artem ludicram exercuisti;<\/em> depulsio: <em>Non exercui artem ludicram;<\/em> quaestio: <em>Quid sit artem ludicram exercere?<\/em> Si accusabitur theatrali lege, depulsio erit rei; si excitatus fuerit de spectaculis et aget iniuriarum, depulsio erit accusatoris.", "st": "3.6.19"}, {"sp": "N", "t": "Frequentius tamen illud accidet, quod est a plurimis traditum. Effugerunt has quaestiones qui dixerunt, status esse id, quod appareat ex intentione et depulsione, ut <em>Fecisti<\/em>, <em>Non feci<\/em> aut <em>Recte feci.<\/em>", "st": "3.6.20"}, {"sp": "N", "t": "Viderimus tamen, utrum id sit status an in eo status. Hermagoras statum vocat, per quem subiecta res intelligatur et ad quem probationes etiam partium referantur. Nostra opinio semper haec fuit: cum essent frequenter in causa diversi quaestionum status, in eo credere status causae, quod esset in ea potentissimum et in quo maxime res verteretur. Id si quis generalem quaestionem vel caput generale dicere malet cum hoc mihi non erit pugna, non magis, quam si aliud adhuc, quo idem intelligatur, eius rei nomen invenerit, quanquam tota volumina in hanc disputationem impendisse multos sciam; nobis statum dici placet.", "st": "3.6.21"}, {"sp": "N", "t": "Sed cum in aliis omnibus inter scriptores summa dissensio est, tum in hoc praecipue videtur mihi studium quoque diversa tradendi fuisse; adeo, nec qui sit numerus nec quae nomina nec qui generales quive speciales sint status, convenit.", "st": "3.6.22"}, {"sp": "N", "t": "Ac primum Aristoteles elementa decem constituit, circa quae versari videatur omnis quaestio. οὐσίαν, quam Plautus essentiam vocat, neque sane aliud est eius nomen Latinum; sed ea quaeritur, an sit. Qualitatem, cuius apertus intellectus est. Quantitatem, quae dupliciter a posterioribus divisa est, quam magnum et quam multum sit? Ad aliquid, unde ducta est translatio et comparatio.", "st": "3.6.23"}, {"sp": "N", "t": "Post haec Ubi et Quando; deinde Facere, Pati, Habere, quod est quasi armatum esse, vestitum esse. Novissime κεῖσθαι, quod est compositum esse quodam modo, ut calere, stare, irasci. Sed ex iis omnibus prima quattuor ad status pertinere, cetera ad quosdam locos argumentorum videntur.", "st": "3.6.24"}, {"sp": "N", "t": "Alii novem elementa posuerunt, Personam, in qua de animo, corpore, extra positis quaeratur, quod pertinere ad coniecturae et qualitatis instrumenta video. Tempus, quod χρόνον vocant, ex quo quaestio, an is quem, dum addicta est, mater peperit, servus sit natus. Locum, unde controversia videtur, an fas fuerit tyrannum in templo occidere. An exulaverit, qui domi latuit. Tempus iterum, quod καιρόν appellant;", "st": "3.6.25"}, {"sp": "N", "t": "hanc autem videri volunt speciem illius temporis, ut aestatem vel hiemem; huic subiicitur ille in pestilentia comissator. Actum, id est πρῆξιν, quod eo referunt, <em>sciens commiserit an insciens? necessitate an casu?<\/em> et talia. Numerum, qui cadit in speciem quantitatis, an Thrasybulo triginta praemia debeantur, quia tot tyrannos sustulerit?", "st": "3.6.26"}, {"sp": "N", "t": "Causam, cui plurimae subiacent lites, quotiens factum non negatur, sed quia iusta ratione sit factum, defenditur. τρόπον, cum id, quod alio modo fieri licet, alio dicitur factum; hinc est adulter loris caesus vel fame necatus. Occasionem factorum, quod est apertius, quam ut vel interpretandum vel exemplo sit demonstrandum, tamen ἀφορμὰς ἔργων vocant.", "st": "3.6.27"}, {"sp": "N", "t": "Hi quoque nullam quaestionem extra haec putant. Quidam detrahunt duas partes, numerum et occasionem, et pro illo quod dixi actum subiiciunt res, id est πράγματα. Quae ne praeterisse viderer, satis habui attingere. Ceterum his nec status satis ostendi nec omnes contineri locos credo, quod apparebit diligentius legentibus, quae de utraque re dicam. Erunt enim plura multo, quam quae his elementis comprehenduntur.", "st": "3.6.28"}, {"sp": "N", "t": "Apud plures auctores legi, placuisse quibusdam, unum omnino statum esse coniecturalem. Sed quibus placuerit, neque illi tradiderunt neque ego usquam reperire potui. Rationem tamen hanc secuti dicuntur, quod res omnis signis colligeretur. Quo modo licet qualitatis quoque solum statum faciant, quia ubique, qualis sit cuiusque rei natura, quaeri potest. Sed utrocunque modo sequetur summa confusio.", "st": "3.6.29"}, {"sp": "N", "t": "Neque interest, unum quis statum faciat an nullum, si omnes causae sunt condicionis eiusdem. Coniectura dicta est a coniectu, id est directione quadam rationis ad veritatem, unde etiam somniorum atque ominum interpretes coniectores vocantur. Appellatum tamen est hoc genus varie, sicut sequentibus apparebit.", "st": "3.6.30"}, {"sp": "N", "t": "Fuerunt, qui duos status facerent: Archedemus coniecturalem et finitivum, exclusa qualitate, quia sic de ea quaeri existimabat, quid esset iniquum, quid iniustum, quid dicto audientem non esse; quod vocat <em>de eodem et alio.<\/em>", "st": "3.6.31"}, {"sp": "N", "t": "Huic diversa sententia eorum fuit, qui duos quidem status esse voluerunt, sed unum infitialem, alterum iuridicialem. Infitialis est, quem dicimus coniecturalem, cui ab infitiando nomen alii in totum dederunt, alii in partem, quia accusatorem coniectura, reum infitiatione uti putaverunt.", "st": "3.6.32"}, {"sp": "N", "t": "Iuridicialis est qui Graece dicitur δικαιολογικός Sed quemadmodum ab Archedemo qualitas exclusa est, sic ab his repudiata finitio. Nam subiiciunt eam iuridiciali, quaerendumque arbitrantur iustumne sit, sacrilegium appellari quod obiiciatur vel furtum vel amentiam.", "st": "3.6.33"}, {"sp": "N", "t": "Qua in opinione Pamphilus fuit, sed qualitatem in plura partitus est; plurimi deinceps, mutatis tantum nominibus, in rem de qua constet, et in rem de qua non constet. Nam est verum nec aliter fieri potest, quam ut aut certum sit factum esse quid aut non sit; si non est certum, coniectura sit, si certum est, reliqui status.", "st": "3.6.34"}, {"sp": "N", "t": "Nam idem dicit Apollodorus, cum quaestionem aut in rebus extra positis, quibus coniectura explicatur, aut in nostris opinionibus existimat positam, quorum illud πραγματικόν, hoc περὶ ἐννοίας vocat; idem, qui ἀπρόληπτον et προλημπτικόν dicunt, id est dubium et praesumptum, quo significatur de quo liquet.", "st": "3.6.35"}, {"sp": "N", "t": "Idem Theodorus, qui de eo, an sit, et de accidentibus ei quod esse constat, id est περὶ οὐσίας καὶ συμβεβηκότων existimat quaeri. Nam in his omnibus prius genus coniecturam habet, sequens reliqua. Sed haec reliqua Apollodorus duo vult esse, qualitatem et de nomine, id est finitivam; Theodorus, quid, quale, quantum, ad aliquid.", "st": "3.6.36"}, {"sp": "N", "t": "Sunt et qui de eodem et de alio modo qualitatem esse modo finitionem velint. In duo et Posidonius dividit, vocem et res. In voce quaeri putat an significet, quid, quam multa, quo modo? in rebus coniecturam, quod κατ᾽ αἴσθησιν vocat, et qualitatem, et finitionem, cui nomen dat κατ᾽ ἔννοιαν, et ad aliquid. Unde et illa divisio est, alia esse scripta, alia inscripta.", "st": "3.6.37"}, {"sp": "N", "t": "Celsus Cornelius duos et ipse fecit status generales, an sit? quale sit? Priori subiecit finitionem, quia aeque quaeratur an sit sacrilegus, qui nihil se sustulisse de templo dicit et qui privatam pecuniam confitetur sustulisse. Qualitatem in rem et scriptum dividit. Scripto quattuor partes legales, exclusa translatione; quantitatem et mentis quaestionem coniecturae subiecit.", "st": "3.6.38"}, {"sp": "N", "t": "Est etiam alia in duos dividendi status ratio, quae docet, aut de substantia controversiam esse, aut de qualitate; ipsam porro qualitatem aut in summo genere consistere aut in succedentibus.", "st": "3.6.39"}, {"sp": "N", "t": "De substantia est coniectura. Quaestio enim tractatur rei, an facta sit? an fiat? an futura sit? interdum etiam mentis; idque melius, quam quod iis placuit, qui statum eundem facti nominaverunt, tanquam de praeterito tantum et tantum de facto quaereretur.", "st": "3.6.40"}, {"sp": "N", "t": "Pars qualitatis, quae est de summo genere, raro in iudicium venit, quale est, idne sit honestum, quod vulgo laudatur; succedentium autem aliae de communi appellatione, ut sitne sacrilegus, qui pecuniam privatam ex templo furatus est; aut de re denominata, ubi et factum esse certum est nec dubitatur, quid sit quod factum est. Cui subiacent omnes de honestis, iustis, utilibus quaestiones.", "st": "3.6.41"}, {"sp": "N", "t": "His etiam ceteri status contineri dicuntur, quia et quantitas modo ad coniecturam referatur, ut maiorne sol quam terra? modo ad qualitatem, quanta poena quempiam quantove praemio sit affici iustum? et translatio versetur circa qualitatem, et definitio pars sit translationis;", "st": "3.6.42"}, {"sp": "N", "t": "quin et contrariae leges et ratiocinativus status, id est syllogismos, et plerumque scripti et voluntatis aequo nitantur (nisi quod hic tertius aliquando coniecturam accipit, quid senserit legis constitutor); ambiguitatem vero semper coniectura explicari necesse sit, quia, cum sit manifestum, verborum intellectum esse duplicem, de sola quaeritur voluntate.", "st": "3.6.43"}, {"sp": "N", "t": "A plurimis tres sunt facti generales status, quibus et Cicero in Oratore utitur, et omnia, quae aut in controversiam aut in contentionem veniant, contineri putat, Sitne? Quid sit? Quale sit? quorum nomina apertiora sunt, quam ut dicenda sint.", "st": "3.6.44"}, {"sp": "N", "t": "Idem Patrocles sentit. Tres fecit et M. Antonius his quidem verbis: <em>Paucae res sunt, quibus ex rebus omnes orationes nascuntur, factum non factum, ius iniuria, bonum malum.<\/em> Sed quoniam, quod iure dicimur fecisse, non hunc solum intellectum habet, ut lege, sed illum quoque, ut iuste fecisse videamur, secuti Antonium apertius voluerunt eosdem status distinguere. Itaque dixerunt coniecturalem, legalem, iuridicialem; qui et Verginio placent.", "st": "3.6.45"}, {"sp": "N", "t": "Horum deinde fecerunt species, ita ut legali subiicerent finitionem et alios, qui ex scripto ducuntur, legum contrariarum, quae ἀντινομία dicitur, et scripti et sententiae vel voluntatis, id est κατὰ ῥητὸν καὶ διάνοιαν et μετάλημψιν, quam nos varie translativam, transumptivam, transpositivam vocamus, συλλογισμόν quem accipimus ratiocinativum vel collectivum, ambiguitatis, quae ἀμφιβολία nominatur; quos posui, quia et ipsi a plerisque status appellantur, cum quibusdam legales potius quaestiones eas dici placuerit.", "st": "3.6.46"}, {"sp": "N", "t": "Quattuor fecit Athenaeus, προτρεπτικὴν στάσιν vel παρορμητικήν, id est exhortativum, qui suasoriae est proprius; συντελικήν, qua coniecturam significari magis ex his, quae sequuntur, quam ex ipso nomine apparet; ὑπαλλακτικήν ea finitio est, mutatione enim nominis constat; iuridicialem, eadem appellatione Graeca qua ceteri usus. Nam est, ut dixi, multa in nominibus differentia.", "st": "3.6.47"}, {"sp": "N", "t": "Sunt qui ὑπαλλακτικήν translationem esse existiment, secuti hanc mutationis significationem. Fecerunt alii totidem status, sed alios, An sit? Quid sit? Quale sit? Quantum sit? ut Caecilius et Theon.", "st": "3.6.48"}, {"sp": "N", "t": "Aristoteles in rhetoricis, An sit, Quale, Quantum, et Quam multum sit? quaerendum putat. Quodam tamen loco finitionis quoque vim intelligit, quo dicit quaedam sic defendi, <em>Sustuli, sed non furtum feci; Percussi, sed non iniuriam feci.<\/em>", "st": "3.6.49"}, {"sp": "N", "t": "Posuerat et Cicero in libris rhetoricis, facti, nominis, generis, actionis; ut in facto coniectura, in nomine finitio, in genere qualitas, in actione ius intelligeretur. iuri subiecerat translationem. Verum hic legales quoque quaestiones alio loco tractat ut species actionis.", "st": "3.6.50"}, {"sp": "N", "t": "Fuerunt qui facerent quinque, coniecturam, finitionem, qualitatem, quantitatem, ad aliquid. Theodorus quoque, ut dixi, iisdem generalibus capitibus utitur. An sit? Quid sit? Quale sit? Quantum sit? Ad aliquid. Hoc ultimum maxime in comparativo genere versari putat, quoniam melius ac peius, maius et minus nisi alio relata non intelliguntur.", "st": "3.6.51"}, {"sp": "N", "t": "Sed in illas quoque translativas, ut supra significavi, quaestiones incidit, An huic ius agendi sit? vel, facere aliquid conveniat? An contra hunc? An hoc tempore? An sic? omnia enim ista referri ad aliquid necesse est.", "st": "3.6.52"}, {"sp": "N", "t": "Alii sex status putant, coniecturam, quam γένεσιν vocant, et qualitatem, et proprietatem, id est μετάστασις quo verbo finitio ostenditur, et quantitatem, quam μετάστασις; dicunt, et comparationem, et translationem, cuius adhuc novum nomen inventum est μετάστασις novum, inquam, in statu, alioqui ab Hermagora inter species iuridiciales usitatum.", "st": "3.6.53"}, {"sp": "N", "t": "Aliis septem esse placuit; a quibus nec translatio nec quantitas nec comparatio recepta est, sed in horum trium locum subditae quattuor legales adiectaeque tribus illis rationalibus.", "st": "3.6.54"}, {"sp": "N", "t": "Alii pervenerunt usque ad octo, translatione ad septem superiores adiecta. A quibusdam deinde divisa ratio est, ut status rationales appellarent, quaestiones (quemadmodum supra dixi) legales, ut in illis de re, in his de scripto quaereretur. Quidam in diversum hos status esse,", "st": "3.6.55"}, {"sp": "N", "t": "illas quaestiones maluerunt. Sed alii rationales tres putaverunt, An sit? Quid sit? Quale sit? Hermagoras solus quattuor, coniecturam, proprietatem, translationem, qualitatem, quam per accidentia, id est κατὰ συμβεβηκός vocat, hac interpretatione, an illi accidat viro bono esse, vel malo. Hanc ita dividit, de appetendis et <em>fugiendis,<\/em> quae est pars deliberativa;", "st": "3.6.56"}, {"sp": "N", "t": "de persona, ea ostenditur laudativa; negotialem, quam πραγματικήν vocat, in qua de rebus ipsis quaeritur, remoto personarum complexu, ut, Sitne liber qui est in assertione, an divitiae superbiam pariant, an iustum quid, an bonum sit. Iuridicialem, in qua fere eadem sed certis destinatisque personis quaerantur: an ille iuste hoc fecerit, vel bene", "st": "3.6.57"}, {"sp": "N", "t": "Nec me fallit, in primo Ciceronis rhetorico aliam esse loci negotialis interpretationem, cum ita scriptum sit: <em>Negotialis est, in qua, quid iris ex civili more et aequitate sit, consideratur; cui diligentiae praeesse apud nos iurisconsulti existimantur.<\/em>", "st": "3.6.58"}, {"sp": "N", "t": "Sed quod ipsius de his libris iudicium fuerit, supra dixi. Sunt enim velut regestae in hos commentarios, quos adolescens deduxerat, scholae, et si qua est in his culpa, tradentis est, sive eum movit id, quod Hermagoras prima in hoc loco posuit exempla ex quaestionibus iuris, sive quod Graeci πραγματικούς vocant iuris interpretes.", "st": "3.6.59"}, {"sp": "N", "t": "Sed Cicero quidem his pulcherrimos illos de Oratore substituit, ideoque culpari, tanquam falsa praecipiat, non potest. Nos ad Hermagoran. Trans lationem hic primus omnium tradidit, quanquam semina eius quaedam citra nomen ipsum apud Aristotelen reperiuntur.", "st": "3.6.60"}, {"sp": "N", "t": "Legales autem quaestiones has fecit, scripti et voluntatis (quam ipse vocat κατὰ ῥητὸν καὶ ὑπεξαίρεσιν, id est dictum et exceptionem, quorum prius ei cum omnibus commune est, exceptionis nomen minus usitatum), ratiocinativum, ambiguitatis, legum contrariarum.", "st": "3.6.61"}, {"sp": "N", "t": "Albutius eadem divisione usus detrahit translationem, subiiciens eam iuridiciali. In legalibus quoque quaestionibus nullum putat esse, qui dicatur ratiocinativus. Scio plura inventuros adhuc, qui legere antiquos studiosius volent, sed ne haec quoque excesserint modum vereor.", "st": "3.6.62"}, {"sp": "N", "t": "Ipse me paulum in alia, quam prius habuerim, opinione nunc esse confiteor. Et fortasse tutissimum erat famae modo studenti nihil ex eo mutare, quod multis annis non sensissem modo, verum etiam approbassem.", "st": "3.6.63"}, {"sp": "N", "t": "Sed non sustineo esse conscius mihi dissimulati (in eo praesertim opere, quod ad bonorum iuvenum aliquam utilitatem componimus) in ulla parte iudicii mei. Nam et Hippocrates, clarus arte medicinae, videtur honestissime fecisse, quod quosdam errores suos, ne posteri errarent, confessus est; et M. Tullius non dubitavit aliquos iam editos libros aliis postea scriptis ipse damnare, sicut Catulum atque Lucullum et hos ipsos, de quibus modo sum locutus, artis rhetoricae.", "st": "3.6.64"}, {"sp": "N", "t": "Etenim supervacuus foret in studiis longior labor, si nihil liceret melius invenire praeteritis. Neque tamen quidquam ex iis, quae tum praecepi, supervacuum fuit; ad easdem enim particulas haec quoque, quae nunc praecipiam, revertentur; ita neminem didicisse paeniteat, colligere tantum eadem ac disponere paulo significantius conor. Omnibus autem satisfactum volo, non me hoc serius demonstrare aliis, quam mihi ipse persuaserim.", "st": "3.6.65"}, {"sp": "N", "t": "Secundum plurimos auctores servabam tris rationales status, coniecturam, qualitatem, finitionem, unum legalem. Hi mihi status generales erant. Legalem in quinque species partiebar, scripti et voluntatis, legum contrariarum, collectivum, ambiguitatis, translationis.", "st": "3.6.66"}, {"sp": "N", "t": "Nunc quartum ex generalibus intelligo posse removeri; sufficit enim prima divisio, qua diximus alios rationales, alios legales esse; ita non erit status, sed quaestionum genus; alioqui et rationalis status esset.", "st": "3.6.67"}, {"sp": "N", "t": "Ex iis etiam, quos speciales vocabam, removi translationem, frequenter quidem (sicut omnes qui me secuti sunt meminisse possunt) testatus et in ipsis etiam illis sermonibus me nolente vulgatis hoc tamen complexus, vix in ulla controversia translationis statum posse reperiri, ut non et alius in eadem recte dici videretur, ideoque a quibusdam eum exclusum.", "st": "3.6.68"}, {"sp": "N", "t": "ferri, cum in omnibus fere causis, in quibus cecidisse quis formula dicitur, hae sint quaestiones, an huic, an cum hoc, an hac lege, an apud hunc, an hoc tempore liceat agere?", "st": "3.6.69"}, {"sp": "N", "t": "et si qua sunt talia. Sed personae, tempora, actiones ceteraque propter aliquam causam transferuntur; ita non est in translatione quaestio sed in eo, propter quod transferuntur: Non debes apud praetorem petere fidei commissum, sed apud consules, maior enim praetoria cognitione summa est. Quaeritur, an maior summa sit, facti controversia est.", "st": "3.6.70"}, {"sp": "N", "t": "Non licet tibi agere mecum, cognitor enim fieri non potuisti: iudicatio, an potuerit. Non debuisti interdicere sed petere: an recte interdictum sit, ambigitur. Quae omnia succedunt legitimis quaestionibus.", "st": "3.6.71"}, {"sp": "N", "t": "An non praescriptiones (etiam in quibus maxime videtur manifesta translatio) easdem omnes species habent, quas eae leges, quibus agitur, ut aut de nomine aut scripto et sententia vel ratiocinatione quaeratur? Deinde status ex quaestione oritur; translatio non habet quaestionem, de qua contendit orator, sed propter quam contendit.", "st": "3.6.72"}, {"sp": "N", "t": "Hoc apertius, Occidisti hominem, Non occidi; quaestio, an occiderit, status coniectura. Non est tale, Habeo ius actionis, Non habes, ut sit quaestio, an habeat, et inde status. Accipiat enim actionem necne, ad eventum pertinet, non ad causam, et ad id, quod pronuntiat iudex, non id, propter quod pronuntiat.", "st": "3.6.73"}, {"sp": "N", "t": "Hoc illi simile est, Puniendus es, Non sum; videbit iudex, an puniendus sit. Sed non hic erit quaestio nec hic status. Ubi ergo? Puniendus es, hominem occidisti; Non occidi: An occiderit. Honorandus sum, Non es; num statum habet? non, ut puto. Honorandus sum, quia tyrannum occidi; Non occidisti; quaestio et status.", "st": "3.6.74"}, {"sp": "N", "t": "Similiter, Non recte agis, Recte ago non habet statum. Ubi est ergo? Non recte agis ignominiosus. Quaeritur, an ignominiosus sit; aut, an agere ignominioso liceat; quaestiones et status. Ergo translativum genus causae ut comparativum et mutuae accusationis.", "st": "3.6.75"}, {"sp": "N", "t": "At enim simile est illi Habeo ius, Non habes, Occidisti, Recte occidi. Non nego, sed nec haec res status facit. Non enim sunt hae propositiones (alioqui causa non explicabitur), sed, cum suis rationibus. Scelus commisit Horatius, sororem enim occidit. Non commisit, debuit enim occidere eam, quae hostis mortem maerebat. Quaestio, an haec iusta causa; ita qualitas.", "st": "3.6.76"}, {"sp": "N", "t": "Et similiter in translatione, Non habes ius abdicandi, quia ignominioso non est actio. Habeo ius, quia abdicatio actio non est. Quaeritur, quid sit actio: finiemus Non licet abdicare filium syllogismo. Item cetera per omnes et rationales et legales status.", "st": "3.6.77"}, {"sp": "N", "t": "Nec ignoro fuisse quosdam, qui translationem in rationali quoque genere ponerent hoc nodo, Hominem occidi, iussus ab imperatore. Dona templi cogenti tyranno dedi. Deserui tempestatibus, luminibus, valetudine impeditus. Id est, non per me stetit, sed per illud. A quibus etiam liberius dissentio.", "st": "3.6.78"}, {"sp": "N", "t": "Non enim actio transfertur sed causa facti, quod accidit paene in omni defensione. Deinde is, qui tali utitur patrocinio, non recedit a forma qualitatis, dicit enim, se culpa vacare; ut magis qualitatis duplex ratio facienda sit, altera qua et factum defenditur, altera qua tantum reus.", "st": "3.6.79"}, {"sp": "N", "t": "Credendum est igitur his, quorum auctoritatem secutus est Cicero, tria esse, quae in omni disputatione quaerantur, an sit, quid sit, quale sit? quod ipsa nobis etiam natura praescribit. Nam primum oportet subesse aliquid, de quo ambigitur; quod, quid sit et quale sit, certe non potest aestimari, nisi prius esse constiterit, ideoque ea prima quaestio.", "st": "3.6.80"}, {"sp": "N", "t": "Sed non statim, quod esse manifestum est, etiam quid sit, apparet. Hoc quoque constituto novissima qualitas superest, neque his exploratis aliud est ultra. His infinitae quaestiones, his finitae continentur; horum aliqua in demonstrativa, deliberativa, iudiciali materia utique tractatur.", "st": "3.6.81"}, {"sp": "N", "t": "Haec rursus iudiciales causas et rationali parte et legali continent; neque enim ulla iuris disceptatio nisi finitione, qualitate, coniectura potest explicari.", "st": "3.6.82"}, {"sp": "N", "t": "Sed instituentibus rudes non erit inutilis latius primo fusa ratio et, si non statim rectissima linea tensa, facilior tamen et apertior via. Discant igitur ante omnia quadripertitam in omnibus causis esse rationem, quam primam intueri debeat qui acturus est. Nam, ut a defensore potissimum incipiam, longe fortissima tuendi se ratio est, si quod obiicitur negari potest; proxima, si non id, quod obiicitur, factum esse dicitur; tertia honestissima, qua recte factum defenditur. Quibus si deficiamur, ultima quidem sed iam sola superest salus aliquo iuris adiutorio elabendi ex crimine, quod neque negari neque defendi potest, ut non videatur iure actio intendi.", "st": "3.6.83"}, {"sp": "N", "t": "Hinc illae quaestiones sive actiones sive translationes. Sunt enim quaedam non laudabilia non natura sed iure concessa, ut in XII tabulis debitoris corpus inter creditores dividi licuit, quam legem mos publicus repudiavit; et aliquid aequum sed prohibitum iure, ut libertas testamentorum.", "st": "3.6.84"}, {"sp": "N", "t": "Accusatori nihilo plura intuenda sunt, ut probet factum esse, hoc esse factum, non recte factum, iure se intendere. Ita circa species easdem lis omnis versabitur translatis tantum aliquando partibus, ut in causis, quibus de praemio agitur, recte factum petitor probat.", "st": "3.6.85"}, {"sp": "N", "t": "Haec quattuor velut proposita formaeque actionis, quae tum generales status vocabam, in duo (ut ostendi) genera discedunt rationale et legale. Rationale simplicius est, quia ipsius tantum naturae contemplatione constat. Itaque in eo satis est ostendisse coniecturam, finitionem, qualitatem.", "st": "3.6.86"}, {"sp": "N", "t": "Legalium plures sint species necesse est, propterea quod multae sunt <em>leges<\/em> et varias habent formas. Alia est cuius verbis nitimur, alia cuius voluntate, alias nobis, cum ipsi nullam habeamus, adiungimus, alias inter se comparamus, alias in diversum interpretamur.", "st": "3.6.87"}, {"sp": "N", "t": "Sic nascuntur haec velut simulacra ex illis tribus, interim simplicia, interim et mixta, propriam tamen faciem ostendentia, ut scripti et voluntatis, quae sine dubio aut qualitate aut coniectura continentur, et syllogismos, qui est maxime qualitatis, et leges contrariae, quae iisdem, quibus scriptum et voluntas, constant, et ἀμφιβολία, quae semper coniectura explicatur.", "st": "3.6.88"}, {"sp": "N", "t": "Finitio quoque utrique generi, quodque rerum quodque scripti contemplatione constat, communis est. Haec omnia, etiamsi in illos tres status veniunt, tamen, quia (ut dixi) habent aliquid velut proprium, videntur demonstranda discentibus, et permittendum ea dicere vel status legales vel quaestiones vel capita quaedam minora, dum sciant, nihil ne in his quidem praeter tria, quae praediximus, quaeri.", "st": "3.6.89"}, {"sp": "N", "t": "At Quantum? et Quam multum? et Ad aliquid et, ut nonnulli putarunt, comparativus non eandem rationem habent; sunt enim haec non ad varietatem iuris sed ad solam rationem referenda, ideoque semper in parte aut coniecturae aut qualitatis ponenda sunt, ut Qua mente? et Quo tempore? et Quo loco?", "st": "3.6.90"}, {"sp": "N", "t": "Sed de singulis dicemus quaestionibus, cum tractare praecepta divisionis coeperimus. Hoc inter omnes convenit, in causis simplicibus singulos status esse causarum, quaestionum autem, quae velut subiacent his et ad illud, quo iudicium continetur, referuntur, saepe in unam cadere plures posse;", "st": "3.6.91"}, {"sp": "N", "t": "etiam credo aliquando dubitari, quo statu sit utendum, cum adversus unam intentionem plura opponuntur; et sicut in colore dicitur narrationis, eum esse optimum, quem actor optime tueatur, ita hic quoque posse dici, eum statum esse faciendum, in quo tuendo plurimum adhibere virium possit orator;", "st": "3.6.92"}, {"sp": "N", "t": "ideoque pro Milone aliud Ciceroni agenti placuit aliud Bruto, cum exercitationis gratia componeret orationem, cum ille iure tanquam insidiatorem occisum et tamen non Milonis consilio dixerit, ille etiam gloriatus sit occiso malo cive:", "st": "3.6.93"}, {"sp": "N", "t": "in coniunctis vero posse duos et tris inveniri vel diversos, ut si quis aliud se non fecisse, aliud recte fecisse defendat, vel generis eiusdem, ut si quis duo crimina neget.", "st": "3.6.94"}, {"sp": "N", "t": "Quod accidit etiam, si de una re quaeratur aliqua sed eam plures petant, vel eodem iure ut proximitatis vel diverso, ut cum hic testamento, ille proximitate nitetur. Quotiens autem aliud alii petitori opponitur, dissimiles esse status necesse est, ut in illa controversia:", "st": "3.6.95"}, {"sp": "N", "t": "<em>Testamenta legibus facta rata sint. Intestatorum parentium liberi heredes sint. Abdicatus ne quid de bonis patris capiat. Nothus ante legitimum natus legitimus filius sit, post legitimum nanus tantum civis. In adoptionem dare liceat. In adoptionem dato redire in familiam liceat, si paler naturalis sine liberis decesserit.<\/em>", "st": "3.6.96"}, {"sp": "N", "t": "<em>Qui ex duobus legitimis alterum in adoptionem dederat, alterum abdicaverat, sustulit nothum; institute herede abdicato decessit. Tres omnes de bonis contendunt.<\/em> Nothum, qui non sit legitimus, Graeci vocant; Latinum rei nomen, ut Cato quoque in oratione quadam testatus est, non habemus ideoque utimur peregrino. Sed ad propositum.", "st": "3.6.97"}, {"sp": "N", "t": "Heredi scripto opponitur lex, <em>Abdicatus ne quid de bonis patris capiat;<\/em> fit status scripti et voluntatis, an ullo modo capere possit, an ex voluntate patris, an heres scriptus. Notho duplex fit quaestio, quod post legitimos natus sit et quod non sit ante legitimum natus.", "st": "3.6.98"}, {"sp": "N", "t": "Prior syllogismon habet, an pro non natis sint habendi, qui a familia sunt alienati. Altera et scripti et voluntatis. Non esse enim hunc natum ante legitimum convenit, sed voluntate legis se tuebitur, quam dicet talem fuisse, ut legitimus esset nothus tum natus, cum alius legitimus in domo non esset.", "st": "3.6.99"}, {"sp": "N", "t": "Scriptum quoque legis excludet dicens, non utique, si postea legitimus natus non sit, notho nocere; uteturque hoc argumento: <em>Finge solum natum nothum, cuius condicionis erit? Tantum civis? atqui non erit post legitimum natus. An filius? atqui non erit ante legitimos natus. Quare si verbis legis stari non potest, voluntate standum est.<\/em>", "st": "3.6.100"}, {"sp": "N", "t": "Nec quemquam turbet, quod ex una lege duo status fiant; duplex est, ita vim duarum habet Redire in familiam volenti dicitur ab altero primum, <em>Ut tibi redire liceat, heres sum.<\/em> Idem status, qui in petitione abdicati; quaeritur enim, an possit esse heres abdicatus.", "st": "3.6.101"}, {"sp": "N", "t": "Obiicitur communiter a duobus, <em>Redire tibi in familiam non licet, non enim pater sine liberis decessit.<\/em> Sed in hoc propria quisque eorum quaestione nitetur. Alter enim dicet abdicatum quoque inter liberos esse, et argumentum ducet ex ipsa, qua repellitur, lege; supervacuum enim fuisse prohiberi patris bonis abdicatum, si esset numero alienorum; Nunc quia filii iure futurus fuerit intestati heres, oppositam esse legem, quae tamen non id efficiat, ne filius sit, sed ne heres sit. Status finitivus, quid sit filius.", "st": "3.6.102"}, {"sp": "N", "t": "Rursus nothus eisdem colligit argumentis, non sine liberis patrem decessisse, quibus in petitione usus est, ut probaret esse se filium. Nisi forte et hic finitionem movet, an liberi sint etiam non legitimi. Cadent ergo in unam controversiam vel specialiter duo legitimi status scripti et voluntatis et syllogismos et praeterea finitio, vel tres illi, qui natura soli sunt, coniectura in scripto et voluntate, qualitas in syllogismo, et, quae per se est aperta, finitio.", "st": "3.6.103"}, {"sp": "N", "t": "Causa quoque et iudicatio et continens est in omni genere causarum. Nihil enim dicitur, cui non insit ratio et quo iudicium referatur et quod rem maxime continent. Sed quia magis haec variantur in litibus et fere tradita sunt ab iis, qui de iudicialibus causis aliqua composuerunt, in illam partem differantur. Nunc, quia in tria genera causas divisi, ordinem sequar.", "st": "3.6.104"}, {"sp": "N", "t": "Ac potissimum incipiam ab ea, quae constat laude ac vituperatione. Quod genus videtur Aristoteles atque eum secutus Theophrastus a parte negotiali, hoc est πραγματικῇ removisse totamque ad solos auditores relegasse, et id eius nominis, quod ab ostentatione ducitur, proprium est.", "st": "3.7.1"}, {"sp": "N", "t": "Sed mos Romanus etiam negotiis hoc munus inseruit. Nam et funebres laudationes pendent frequenter ex aliquo publico officio atque ex senatus consulto magistratibus saepe mandantur, et laudare testem vel contra pertinet ad momentum iudiciorum, et ipsis etiam reis dare laudatores licet, et editi in Competitores, in L. Pisonem, in Clodium et Curionem libri vituperationem continent et tamen in Senatu loco sunt habiti sententiae.", "st": "3.7.2"}, {"sp": "N", "t": "Neque infitias eo, quasdam esse ex hoc genere materias ad solam compositas ostentationem, ut laudes deorum virorumque, quos priora tempora tulerunt. Quo solvitur quaestio supra tractata, manifestumque est errare eos, qui nunquam oratorem dicturum nisi de re dubia putaverunt.", "st": "3.7.3"}, {"sp": "N", "t": "An laudes Capitolini Iovis, perpetua sacri certaminis materia, vel dubiae sunt vel non oratorio genere tractantur? Ut desiderat autem laus, quae negotiis adhibetur, probationem, sic etiam illa, quae ostentationi componitur, habet interim aliquam speciem probationis;", "st": "3.7.4"}, {"sp": "N", "t": "ut qui Romulum Martis filium educatumque a lupa dicat, in argumentum caelestis ortus utatur his, quod abiectus in profluentem non potuerit exstingui, quod omnia sic egerit, ut genitum praeside bellorum deo incredibile non esset, quod ipsum quoque caelo receptum temporis eius homines non dubitaverint.", "st": "3.7.5"}, {"sp": "N", "t": "Quaedam vero etiam in defensionis speciem cadent, ut si in laude Herculis permutatum cum regina Lydiae habitum et imperata, ut traditur, pensa orator excuset. Sed proprium laudis est res amplificare et ornare. Quae materia praecipue quidem in deos et homines cadit, est tamen et aliorum animalium, etiam carentium anima.", "st": "3.7.6"}, {"sp": "N", "t": "Verum in deis generaliter primum maiestatem ipsius eorum naturae venerabimur, deinde proprie vim cuiusque et inventa, quae utile aliquid hominibus attulerint.", "st": "3.7.7"}, {"sp": "N", "t": "Vis ostenditur, ut in Iove regendorum omnium, in Marte belli, in Neptuno maris; inventa, ut artium in Minerva, Mercurio litterarum, medicinae Apolline, Cerere frugum, Libero vini. Tum si qua ab iis acta vetustas tradidit, commemoranda. Addunt etiam dis honorem parentes, ut si quis sit filius Iovis; addit antiquitas, ut iis, qui sunt ex Chao; progenies quoque, ut Apollo ac Diana Latonae.", "st": "3.7.8"}, {"sp": "N", "t": "Laudandum in quibusdam quod geniti immortales, quibusdam quod immortalitatem virtute sint consecuti; quod pietas principis nostri praesentium quoque temporum decus fecit. Magis est varia laus hominum.", "st": "3.7.9"}, {"sp": "N", "t": "Nam primum dividitur in tempora, quodque ante eos fuit quoque ipsi vixerunt; in iis autem, qui fato sunt functi, etiam quod est insecutum. Ante hominem patria ac parentes maioresque erunt, quorum duplex tractatus est: aut enim respondisse nobilitati pulchrum erit aut humilius genus illustrasse factis.", "st": "3.7.10"}, {"sp": "N", "t": "Illa quoque interim ex eo, quod ante ipsum fuit, tempore trahentur, quae responsis vel auguriis futuram claritatem promiserint, ut eum, qui ex Thetide natus esset, maiorem patre suo futurum cecinisse dicuntur oracula.", "st": "3.7.11"}, {"sp": "N", "t": "Ipsius vero laus hominis ex animo et corpore et extra positis peti debet. Et corporis quidem fortuitorumque cum levior, tum non uno modo tractanda est. Nam et pulchritudinem interim roburque prosequimur honore verborum, ut Homerus in Agamemnone atque Achille, et interim confert admirationi multum etiam infirmitas, ut cum idem Tydea parvum sed bellatorem dicit fuisse.", "st": "3.7.12"}, {"sp": "N", "t": "Fortuna vero tum dignitatem adfert, ut in regibus principibusque (namque est haec materia ostendendae virtutis uberior), tum quo minores opes fuerunt, maiorem bene factis gloriam parit. Sed omnia, quae extra nos bona sunt quaeque hominibus forte obtigerunt, non ideo laudantur, quod habuerit quis ea, sed quod iis honeste sit usus.", "st": "3.7.13"}, {"sp": "N", "t": "Nam divitiae et potentia et gratia, cum plurimum virium dent, in utramque partem certissimum faciunt morum experimentum, aut enim meliores sumus propter haec aut peiores. Animi semper vera laus, sed non una per hoc opus via ducitur.", "st": "3.7.14"}, {"sp": "N", "t": "Namque alias aetatis gradus gestarumque rerum ordinem sequi speciosius fuit, ut in primis annis laudaretur indoles, tum disciplinae, post hoc operum id est factorum dictorumque contextus; alias in species virtutum dividere laudem, fortitudinis, iustitiae, continentiae ceterarumque, ac singulis adsignare, quae secundum quamque earum gesta erunt.", "st": "3.7.15"}, {"sp": "N", "t": "Utra sit autem harum via utilior, cum materia deliberabimus, dum sciamus gratiora esse audientibus, quae solus quis aut primus aut certe cum paucis fecisse dicetur, si quid praeterea supra spem aut exspectationem, praecipue quod aliena potius causa quam sua.", "st": "3.7.16"}, {"sp": "N", "t": "Tempus, quod finem hominis insequitur, non semper tractare contingit; non solum quod viventes aliquando laudamus, sed quod rara haec occasio est, ut referri possint divini honores et decreta et publice statuae constitutae.", "st": "3.7.17"}, {"sp": "N", "t": "Inter quae numeraverim ingeniorum monumenta, quae saeculis probarentur. Nam quidam, sicut Menander, iustiora posterorum quam suae aetatis iudicia sunt consecuti. Adferunt laudem liberi parentibus, urbes conditoribus, leges latoribus, artes inventoribus nec non instituta quoque auctoribus, ut a Numa traditum deos colere, a Publicola fasces populo summittere.", "st": "3.7.18"}, {"sp": "N", "t": "Qui omnis etiam in vituperatione ordo constabit, tantum in diversum. Nam et turpitudo generis opprobrio multis fuit, et quosdam claritas ipsa notiores circa vitia et invisos magis fecit, et in quibusdam, ut in Paride traditum est, praedicta pernicies, et corporis ac fortunae quibusdam mala contemptum, sicut Thersitae atque Iro, quibusdam bona vitiis corrupta odium attulerunt, ut Nirea imbellem, Plisthenen impudicum a poetis accepimus.", "st": "3.7.19"}, {"sp": "N", "t": "Et animo totidem vitia, quot virtutes sunt, nec minus quam in laudibus duplici ratione tractantur. Et post mortem adiecta quibusdam ignominia est, ut Maelio, cuius domus solo aequata, Marcoque Manlio, cuius praenomen e familia in posterum exemptum est;", "st": "3.7.20"}, {"sp": "N", "t": "et parentes malorum odimus; et est conditoribus urbium infame contraxisse aliquam perniciosam ceteris gentem, qualis est primus Iudaicae superstitionis auctor; et Gracchorum leges invisae; et si quod est exemplum deforme posteris traditum, quale libidinis vir Perses in muliere Samia instituere ausus dicitur primus.", "st": "3.7.21"}, {"sp": "N", "t": "Sed in viventibus quoque iudicia hominum velut argumenta sunt morum, et honos aut ignominia veram esse laudem vel vituperationem probat.", "st": "3.7.22"}, {"sp": "N", "t": "Interesse tamen Aristoteles putat, ubi quidque laudetur aut vituperetur. Nam plurimum refert, qui sint audientium mores, quae publice recepta persuasio, ut illa maxime quae probant esse in eo, qui laudabitur, credant, aut in eo, contra quem dicemus, ea quae oderunt. Ita non dubium erit iudicium, quod orationem praecesserit.", "st": "3.7.23"}, {"sp": "N", "t": "Ipsorum etiam permiscenda laus semper, nam id benevolos facit; quotiens autem fieri poterit, cum materiae utilitate iungenda. Minus Lacedaemone studia litterarum quam Athenis honores merebuntur, plus patientia ac fortitudo. Rapto vivere quibusdam honestum, aliis cura legum. Frugalitas apud Sybaritas forsitan odio foret, veteribus Romanis summum luxuria crimen.", "st": "3.7.24"}, {"sp": "N", "t": "Eadem in singulis differentia. Maxime favet iudex, qui sibi dicentem assentiri putat. Idem praecipit illud quoque (quod mox Cornelius Celsus prope supra modum invasit), quia sit quaedam virtutibus ac vitiis vicinitas, utendum proxima derivatione verborum, ut pro temerario fortem, pro prodigo liberalem, pro avaro parcum vocemus; quae eadem etiam contra valet. Quod quidem orator, id est vir bonus, nunquam faciet, nisi forte communi utilitate ducetur.", "st": "3.7.25"}, {"sp": "N", "t": "Laudantur autem urbes similiter atque homines. Nam pro parente est conditor, et multum auctoritatis adfert vetustas, ut iis, qui terra dicuntur orti; et virtutes ac vitia circa res gestas eadem quae in singulis, illa propria quae ex loci positione ac munitione sunt. Cives illis ut hominibus liberi decori.", "st": "3.7.26"}, {"sp": "N", "t": "Est laus et operum, in quibus honor, utilitas, pulchritudo, auctor spectari solet. Honor ut in templis, utilitas ut in muris, pulchritudo vel auctor utrobique. Est et locorum, qualis Siciliae apud Ciceronem, in quibus similiter speciem et utilitatem intuemur; speciem in maritimis, planis, amoenis; utilitatem in salubribus, fertilibus. Erit et dictorum honestorum factorumque laus generalis, erit et rerum omnis modi.", "st": "3.7.27"}, {"sp": "N", "t": "Nam et somni et mortis scriptae laudes et quorundam a medicis ciborum. Itaque, ut non consensi hoc laudativum genus circa solam versari honesti quaestionem, sic qualitate maxime contineri puto; quamquam tres status omnes cadere in hoc opus possint, iisque usum C. Caesarem in vituperando Catone notaverit Cicero. totum autem habet aliquid simile suasoriis, quia plerumque eadem illic suaderi, hic laudari solent.", "st": "3.7.28"}, {"sp": "N", "t": "Deliberativas quoque miror a quibusdam sola utilitate finitas. Ac si quid in his unum sequi oporteret, potior fuisset apud me Ciceronis sententia, qui hoc materiae genus dignitate maxime contineri putat. Nec dubito, quin ii, qui sunt in illa priore sententia, secundum opinionem pulcherrimam ne utile quidem, nisi quod honestum esset, existimarint.", "st": "3.8.1"}, {"sp": "N", "t": "Et est haec ratio verissima, si consilium contingat semper bonorum atque sapientium. Verum apud imperitos, apud quos frequenter dicenda sententia est, populumque praecipue, qui ex pluribus constat indoctis, discernenda sunt haec et secundum communes magis intellectus loquendum.", "st": "3.8.2"}, {"sp": "N", "t": "Sunt enim multi, qui etiam, quae credunt honesta, non tamen satis eadem utilia quoque existiment, et quae turpia esse dubitare non possunt, utilitatis specie ducti probent, ut foedus Numantinum iugumque Caudinum.", "st": "3.8.3"}, {"sp": "N", "t": "Ne qualitatis quidem statu, in quo et honestorum et utilium quaestio est, complecti eas satis est. Nam frequenter in his etiam coniecturae locus est, nonnunquam tractatur aliqua finitio, aliquando etiam legales possunt incidere tractatus, in privata maxime consilia, si quando ambigetur an liceat.", "st": "3.8.4"}, {"sp": "N", "t": "De coniectura paulo post pluribus. Interim est finitio apud Demosthenen, Det Halonnesum Philippus, an reddat? apud Ciceronem in Philippicis, Quid sit tumultus? Quid? non illa similis iudicialium quaestio de statua Servi Sulpici, an iis demum ponenda sit, qui in legatione ferro sunt interempti?", "st": "3.8.5"}, {"sp": "N", "t": "Ergo pars deliberativa, quae eadem suasoria dicitur, de tempore futuro consultans quaerit etiam de praeterito. Officiis constat duobus suadendi ac dissuadendi. Prooemio, quale est in iudicialibus, non ubique eget, quia conciliatus est ei quisque, quem consulit. Initium tamen quodcunque debet habere aliquam prooemii speciem; neque enim abrupte nec unde libuit incipiendum, quia est aliquid in omni materia naturaliter primum.", "st": "3.8.6"}, {"sp": "N", "t": "In senatu et utique in contionibus eadem ratio quae apud iudices, adquirendae sibi plerumque eorum, apud quos dicendum sit, benevolentiae. Nec mirum, cum etiam in panegyricis petatur audientium favor, ubi emolumentum non in utilitate aliqua, sed in sola laude consistit.", "st": "3.8.7"}, {"sp": "N", "t": "Aristoteles quidem nec sine causa putat et a nostra et ab eius, qui dissentiet, persona duci frequenter in consiliis exordium, quasi mutuantibus hoc nobis a iudiciali genere, nonnunquam etiam, ut minor res maiorve videatur; in demonstrativis vero prooemia esse maxime libera existimat.", "st": "3.8.8"}, {"sp": "N", "t": "Nam et longe a materia duci, ut in Helenae laude Isocrates fecerit; et ex aliqua rei vicinia, ut idem in Panegyrico, cum queritur plus honoris corporum quam animorum virtutibus dari; et Gorgias in Olympico laudans eos, qui primi tales instituerint conventus. Quos secutus videlicet C. Sallustius in bello Iugurthino et Catilinae nihil ad historiam pertinentibus principiis orsus est.", "st": "3.8.9"}, {"sp": "N", "t": "Sed nunc ad suasoriam, in qua, etiam cum prooemio utemur, breviore tamen et velut quodam capite tantum et initio debebimus esse contenti. Narrationem vero nunquam exigit privata deliberatio, eius duntaxat rei, de qua dicenda sententia est; quia nemo ignorat id de quo consulit.", "st": "3.8.10"}, {"sp": "N", "t": "Extrinsecus possunt pertinentia ad deliberationem multa narrari. In contionibus saepe est etiam illa, quae ordinem rei docet, necessaria.", "st": "3.8.11"}, {"sp": "N", "t": "Adfectus ut quae maxime postulat. Na M et concitanda et lenienda frequenter est ira, et ad metum, cupiditatem, odium, conciliationem impellendi animi. Nonnunquam etiam movenda miseratio, sive, ut auxilium obsessis feratur, suadere oportebit sive sociae civitatis eversionem deflebimus.", "st": "3.8.12"}, {"sp": "N", "t": "Valet autem in consiliis auctoritas plurimum. Nam et prudentissimus esse haberique et optimus debet, qui sententiae suae de utilibus atque honestis credere omnes velit. In iudiciis enim vulgo fas habetur indulgere aliquid studio suo; consilia nemo est qui neget secundum mores dari. Graecorum quidem plurimi omne hoc officium contionale esse iudicaverunt et in sola reipublicae administratione posuerunt.", "st": "3.8.13"}, {"sp": "N", "t": "Quin et Cicero in hac maxime parte versatur. Ideoque suasuris de pace, bello, copiis, operibus, vectigalibus haec duo esse praecipue nota voluit, vires civitatis et mores, ut ex natura cum ipsarum rerum tum audientium ratio suadendi duceretur.", "st": "3.8.14"}, {"sp": "N", "t": "Nobis maior in re videtur varietas, nam et consultantium et consiliorum plurima sunt genera. Quare in suadendo et dissuadendo tria primum spectanda erunt, quid sit de quo deliberetur, qui sint qui deliberent, qui sit qui suadeat.", "st": "3.8.15"}, {"sp": "N", "t": "Rem, de qua deliberatur, aut certum est posse fieri aut incertum. Si incertum, haec erit quaestio sola aut potentissima; saepe enim accidet, ut prius dicamus, ne si possit quidem fieri, esse faciendum, deinde fieri non posse. Cum autem de hoc quaeritur, coniectura est, an Isthmos intercidi, an siccari palus Pomptina, an portus fieri Ostiae possit, an Alexander terras ultra Oceanum sit inventurus.", "st": "3.8.16"}, {"sp": "N", "t": "Sed in iis quoque quae constabit posse fieri, coniectura aliquando erit, si quaeretur, an utique futurum sit, ut Carthaginem superent Romani; ut redeat Hannibal, si Scipio exercitum in Africam transtulerit; ut servent fidem Samnites, si Romani arma deposuerint. Quaedam et fieri posse et futura esse credibile est, sed aut alio tempore aut alio loco aut alio modo.", "st": "3.8.17"}, {"sp": "N", "t": "Ubi coniecturae non erit locus, alia sunt intuenda. Et primum aut propter ipsam rem, de qua sententiae rogantur, consultabitur aut propter alias intervenientes extrinsecus causas. Propter ipsam deliberant Patres conscripti, an stipendium militi constituant?", "st": "3.8.18"}, {"sp": "N", "t": "Haec materia simplex erit. Accedunt causae aut faciendi, ut deliberant patres conscripti, an Fabios dedant Gallis bellum minitantibus; aut non faciendi, ut deliberat C. Caesar, an perseveret in Germaniam ire, cum milites passim testamenta facerent.", "st": "3.8.19"}, {"sp": "N", "t": "Hae suasoriae duplices sunt. Nam et illic causa deliberandi est, quod bellum Galli minitentur; esse tamen potest quaestio, dedendine fuerint etiam citra hanc denuntiationem, qui contra fas, cum legati missi essent, proelium inierint, regemque, ad quem mandata acceperant, trucidarint.", "st": "3.8.20"}, {"sp": "N", "t": "Et hic nihil Caesar sine dubio deliberaret nisi propter hanc militum perturbationem; est tamen locus quaerendi, an citra hunc quoque casum penetrandum in Germaniam fuerit. Semper autem de eo prius loquemur, de quo deliberari etiam detractis sequentibus possit.", "st": "3.8.21"}, {"sp": "N", "t": "Partes suadendi quidam putaverunt honestum, utile, necessarium. Ego non invenio huic tertiae locum. Quantalibet enim vis ingruat, aliquid fortasse pati necesse sit, nihil facere; de faciendo autem deliberatur.", "st": "3.8.22"}, {"sp": "N", "t": "Quodsi hanc vocant necessitatem, in quam homines graviorum metu coguntur, utilitatis erit quaestio; ut si obsessi et impares et aqua ciboque defecti de facienda ad hostem deditione deliberent et dicatur, <em>necesse est;<\/em> nempe sequitur, ut hoc subiiciatur, <em>alioqui pereundum est:<\/em> ita propter id ipsum non est necesse, quia perire potius licet.", "st": "3.8.23"}, {"sp": "N", "t": "Denique non fecerunt Saguntini nec in rate Opitergina circumventi. Igitur in his quoque causis aut de sola utilitate ambigetur aut quaestio inter utile atque honestum consistet. At enim si quis liberos procreare volet, necesse habet ducere uxorem.", "st": "3.8.24"}, {"sp": "N", "t": "Quis dubitat? sed ei, qui pater vult fieri, liqueat necesse est uxorem esse ducendam. Itaque mihi ne consilium quidem videtur, ubi necessitas est, non magis quam ubi constat, quid fieri non possit. Omnis enim deliberatio de dubiis est. Melius igitur, qui tertiam partem dixerunt δυνατόν quod nostri possibile nominant, quae ut dura videatur appellatio, tamen sola est.", "st": "3.8.25"}, {"sp": "N", "t": "Quas partes non omnes in omnem cadere suasoriam manifestius est, quam ut docendum sit. Tamen apud plerosque earum numerus augetur, a quibus ponuntur ut partes, quae superiorum species sunt partium. Nam fas, iustum, pium, aequum, mansuetum quoque (sic enim sunt interpretati τὸ ἥμερον) et si qua adhuc adiicere quis eiusdem generis velit, subiici possunt honestati.", "st": "3.8.26"}, {"sp": "N", "t": "An sit autem facile, magnum, iucundum, sine periculo, ad quaestionem pertinet utilitatis. Qui loci oriuntur ex contradictione: <em>Est quidem utile sed difficile, parvum, iniucundum, periculosum.<\/em>", "st": "3.8.27"}, {"sp": "N", "t": "Tamen quibusdam videtur esse nonnunquam de iucunditate sola consultatio, ut si de aedificando theatro, instituendis ludis deliberetur. Sed neminem adeo solutum luxu puto, ut nihil in causa suadendi sequatur praeter voluptatem.", "st": "3.8.28"}, {"sp": "N", "t": "Praecedat enim semper aliquid necesse est, ut in ludis honor deorum, in theatro non inutilis laborum remissio, deformis et incommoda turbae, si id non sit, conflictatio, et nihilominus eadem illa religio, cum theatrum veluti quoddam illius sacri templum vocabimus.", "st": "3.8.29"}, {"sp": "N", "t": "Saepe vero et utilitatem despiciendam esse dicimus, ut honesta faciamus, ut cum illis Opiterginis damus consilium, ne se hostibus dedant, quanquam perituri sint, nisi fecerint; et utilia honestis praeferimus, ut cum suademus, ut bello Punico servi armentur.", "st": "3.8.30"}, {"sp": "N", "t": "Sed neque hic plane concedendum est esse id inhonestum, liberos enim natura omnes et eisdem constare elementis et fortasse antiquis etiam nobilibus ortos dici potest; et illic, ubi manifestum periculum est, opponenda alia, ut crudelius etiam perituros adfirmemus, si se dediderint, sive hostis non servaverit fidem, sive Caesar vicerit, quod est vero similius.", "st": "3.8.31"}, {"sp": "N", "t": "Haec autem, quae tantum inter se pugnant, plerumque nominibus deflecti solent. Nam et utilitas ipsa expugnatur ab iis, qui dicunt, non solum potiora esse honesta quam utilia, sed ne utilia quidem esse, quae non sint honesta; et contra, quod nos honestum, illi vanum, ambitiosum, stolidum, verbis quam re probabilius vocant.", "st": "3.8.32"}, {"sp": "N", "t": "Nec tantum inutilibus comparantur utilia, sed inter se quoque ipsa, ut si ex duobus eligamus, in altero quid sit magis, in altero quid sit minus. Crescit hoc adhuc. Nam interim triplices etiam suasoriae incidunt: ut cum Pompeius deliberabat, Parthos an Africam an Aegyptum peteret. Ita non tantum, utrum melius sed quid sit optimum, quaeritur, itemque contra.", "st": "3.8.33"}, {"sp": "N", "t": "Nec unquam incidet in hoc genere materiae dubitatio rei, quae undique secundum nos sit. Nam ubi contradictioni locus non est, quae potest esse causa dubitandi? Ita fere omnis suasoria nihil est aliud quam comparatio, videndumque, quid consecuturi simus et per quid, ut aestimari possit, plus in eo quod petimus sit commodi, an vero in eo per quod petimus incommodi.", "st": "3.8.34"}, {"sp": "N", "t": "Est utilitatis et in tempore quaestio, <em>expedit sed non nunc;<\/em> et in loco, <em>non hic;<\/em> et in persona, <em>non nobis, non contra hos;<\/em> et in genere agendi, <em>non sic;<\/em> et in modo, <em>non in tantum.<\/em> Sed personam saepius decoris gratia intuemur, quae et in nobis et in iis, qui deliberant, spectanda est.", "st": "3.8.35"}, {"sp": "N", "t": "Itaque quamvis exempla plurimum in consiliis possint, quia facillime ad consentiendum homines ducuntur experimentis, refert tamen, quorum auctoritas et quibus adhibeatur.", "st": "3.8.36"}, {"sp": "N", "t": "Diversi sunt enim deliberantium animi, duplex condicio. Nam consultant aut plures aut singuli; sed in utrisque differentia, quia et in pluribus multum interest, senatus sic an populus, Romani an Fidenates, Graeci an barbari, et in singulis, Catoni petendos honores suadeamus an C. Mario, de ratione belli Scipio prior ani Fabius deliberet.", "st": "3.8.37"}, {"sp": "N", "t": "Proinde intuenda sexus, dignitas, actas. Sed mores praecipue discrimen dabunt. Et honesta quidem honestis suadere facillimum est; si vero apud turpes recta obtinere conabimur, ne videamur exprobrare diversam vitae sectam, cavendum.", "st": "3.8.38"}, {"sp": "N", "t": "Et animus deliberantis non ipsa honesti natura, quam he non respicit, permouendus, sed laude, vulgi opinion, et si parum proficiet haec vanitas, secutura ex his utilitate, aliquanto vero magis obiiciendo aliquos, si diversa fecerint, metus.", "st": "3.8.39"}, {"sp": "N", "t": "Namque praeter id quod his levissimi cuiusque animus facillime terretur, nescio an etiam naturaliter apud plurimos plus valeat malorum timor quam spes bonorum, sicut facilior eisdem turpium quam honestorum intellectus est.", "st": "3.8.40"}, {"sp": "N", "t": "Aliquando bonis quoque suadentur parum decora, dantur parum bonis consilia, in quibus ipsorum qui consulunt spectator utilitas. Nec me fallit, quae statim cogitatio subire possit legentem: Hoc ergo praecipis?", "st": "3.8.41"}, {"sp": "N", "t": "et hoc fas putas? Poterat me liberare Cicero, qui ita scribit ad Brutum, praepositis plurimis, quae honeste suaderi Caesari possint: <em>Simne bonus vir, si haec suadeam? Minime. Suasoris enim finis est utilitas eius, cui quisque suadet. At recta sunt. Quis negat? sed non est semper rectis in suadendo locus.<\/em> Sed quia est altior quaestio nec tantum ad suasorias pertinet, destinatus est mihi hic locus duodecimo, qui summus futurus est, libro.", "st": "3.8.41"}, {"sp": "N", "t": "Nec ego quicquam fieri turpiter velim. Verum interim haec vel ad scholarum exercitationes pertinere credantur, nam et iniquorum ratio noscenda est, ut melius aequa tueamur.", "st": "3.8.43"}, {"sp": "N", "t": "Interim si quis bono inhonesta suadebit, meminerit non suadere tanquam inhonesta, it quidam declamatores Sextum Pompeium ad piraticam propter hoc ipsum quod turpis et crudelis sit, impellunt; sed dandus illis deformibus color idque etiam apud malos.", "st": "3.8.44"}, {"sp": "N", "t": "Neque enim quisquam est tam malus, ut videri velit. Sic Catilina apud Sallustium loquitur, ut rem sceleratissimam non militia, sed indignatione videatur audere. Sic Atreus apud Varium: — Iam fero (inquit) infandissima, Iam facere cogor. Quanto magis eis, quibus cura famae fuit, conservandus est hic velut ambitus?", "st": "3.8.45"}, {"sp": "N", "t": "Quare et, cum Ciceroni dabimus consilium, ut Antonium roget, vel etiam ut Philippicas (ita vitam pollicente eo) exurat, non cupiditatem lucis allegabimus (haec enim si valet in animo eius, tacentibus quoque nobis valet), sed ut reipublicae se servet hortabimur.", "st": "3.8.46"}, {"sp": "N", "t": "Hac illi opus est occasione, ne eum talium precum pudeat. Et C. Caesari suadentes regnum adfirmabimus stare iam rempublicam nisi uno regente non posse. Nam qui de re nefaria deliberat, id solum quaerit, quomodo quam minimum peccare videatur.", "st": "3.8.47"}, {"sp": "N", "t": "Multum refert etiam, quae sit persona suadentis; quia anteacta vita si illustris fuit aut clarius genus aut aetas aut fortuna adfert expectationem, providendum est, ne quae dicuntur ab eo qui dicit dissentiant. At his contraria summissiorem quendam modum postulant. Nam quae in aliis libertas est, in aliis licentia vocatur, et quibusdam sufficit auctoritas, quosdam ratio ipsa aegre tuetur.", "st": "3.8.48"}, {"sp": "N", "t": "Ideoque longe mihi difficillimae videntur prosopopoeiae, in quibus ad reliquum suasoriae laborem accedit etiam personae difficultas. Namque idem illud aliter Caesar, aliter Cicero, aliter Cato suadere debebit. Utilissima vero haec exercitatio, vel quod duplicis est operis, vel quod poetis quoque aut historiarum futuris scriptoribus plurimum confert. Verum et oratoribus necessaria.", "st": "3.8.49"}, {"sp": "N", "t": "Nam sunt multae a Graecis Latinisque compositae orationes, quibus alii uterentur, ad quorum condicionem vitamque aptanda quae dicebantur fuerunt. An eodem modo cogitavit aut eandem personam induit Cicero, cum scriberet Cn. Pompeio et cum T. Ampio ceterisve; ac non uniuscuiusque eorum fortunam, dignitatem, res gestas intuitus omnium, quibus vocem dabat, etiam imagine expressit? ut melius quidem sed tamen ipsi dicere viderentur.", "st": "3.8.50"}, {"sp": "N", "t": "Neque enim minus vitiosa est oratio, si ab homine quam si ab re, cui accommodari debuit, dissidet; ideoque Lysias optime videtur in iis, quae scribebat indoctis, servasse veritatis fidem. Enimvero praecipue declamatoribus considerandum est, quid cuique personae conveniat, qui paucissimas controversias ita dicunt ut advocati, plerumque filii, parentes, divites, senes, asperi, lenes, avari, denique superstitiosi, timidi, derisores fiunt; ut vix comoediarum actoribus plures habitus in pronuntiando concipiendi sint quam his in dicendo.", "st": "3.8.51"}, {"sp": "N", "t": "Quae omnia possunt videri prosopopoeiae, quam ego suasoriis subieci, quia nullo alio ab iis quam persona distat. Quanquam haec aliquando etiam in controversias ducitur, quae ex historiis compositae certis agentium nominibus continentur.", "st": "3.8.52"}, {"sp": "N", "t": "Neque ignoro plerumnque exercitationis gratia poni et poeticas et historicas, ut Priami verba apud Achillem aut Sullae dictaturam deponentis in contione. Sed haec in partem cedent trium generum, in quae causas divisimus. Nam et rogare, indicare, rationem reddere et alia, de quibus supra dictum est, varie atque ut res tulit in materia iudiciali, deliberativa, demonstrativa, solemus.", "st": "3.8.53"}, {"sp": "N", "t": "Frequentissime vero in iis utimur ficta personarum, quas ipsi substituimus, oratione, ut apud Ciceronem pro Caelio Clodiam et Caecus Appius et Clodius frater, ille in castigationem, hic in exhortationem vitiorum compositus, alloquitur.", "st": "3.8.54"}, {"sp": "N", "t": "Solent in scholis fingi materiae ad deliberandum similiores controversiis et ex utroque genere commixtae, ut cum apud C. Caesarem consultatio de poena Theodoti ponitur. Constat enim accusatione et defensione causa eius, quod est iudicialium proprium.", "st": "3.8.55"}, {"sp": "N", "t": "Permixta tamen est et utilitatis ratio, an pro Caesare fuerit occidi Pompeium, an timendum a rege bellum, si Theodotus sit occisus, an id minime opportunum hoc tempore et periculosum et certe longum sit futurum.", "st": "3.8.56"}, {"sp": "N", "t": "Quaeritur et de honesto, deceatne Caesarem ultio Pompeii, an sit verendum, ne peiorem faciat suarum partium causam, si Pompeium indignum morte fateatur.", "st": "3.8.57"}, {"sp": "N", "t": "Quod genus accidere etiam veritati potest. Non simplex autem circa suasorias error in plerisque declamatoribus fuit, qui dicendi genus in iis diversum atque in totum illi iudiciali contrarium esse existimaverunt. Nam et principia abrupta et concitatam semper orationem et in verbis effusiorem, ut ipsi vocant, cultum adfectaverunt, et earum breviores utique commentarios quam legalis materiae facere laborarunt.", "st": "3.8.58"}, {"sp": "N", "t": "Ego porro ut prooemio video non utique opus esse suasoriis, propter quas dixi supra causas, ita cur initio furioso sit exclamandum, non intelligo; cum proposita consultatione rogatus sententiam, si modo est sanus, non quiritet, sed quam maxime potest civili et humano ingressu mereri adsensum deliberantis velit.", "st": "3.8.59"}, {"sp": "N", "t": "Cur autem torrens et utique aequaliter concitata sit in ea dicentis oratio, cum vel praecipue moderationem consilia desiderent? Neque ego negaverim, saepius subsidere in controversiis impetum dicendi prooemio, narratione, argumentis; quae si detrahas, id fere supererit, quo suasoriae constant, verum id quoque aequalius erit non tumultuosius atque turbidius.", "st": "3.8.60"}, {"sp": "N", "t": "Verborum autem magnificentia non validius est adfectanda suasorias declamantibus, sed contingit magis; nam et personae fere magnae fingentibus placent, regum, principum, senatus, populi et res ampliores; ita cum verba rebus aptentur, ipso materiae nitore clarescunt.", "st": "3.8.61"}, {"sp": "N", "t": "Alia veris consiliis ratio est, ideoque Theophrastus quam maxime remotum ab omni adfectione in deliberativo genere voluit esse sermonem, secutus in hoc auctoritatem praeceptoris sui, quanquam dissentire ab eo non timide solet.", "st": "3.8.62"}, {"sp": "N", "t": "Namque Aristoteles idoneam maxime ad scribendum demonstrativam proximamque ab ea iudicialem putavit, videlicet quoniam prior ilia tota esset ostentationis, haec secunda egeret artis, vel ad fallendum, si ita poposcisset utilitas, consilia fide prudentiaque constarent.", "st": "3.8.63"}, {"sp": "N", "t": "Quibus in demonstrativa consentio, nam et omnes alii scriptores idem tradiderunt; in iudiciis autem consiliisque secundum condicionem ipsius, quae tractabitur, rei accommodandam dicendi credo rationem.", "st": "3.8.64"}, {"sp": "N", "t": "Nam et Philippicas Demosthenis iisdem quibus habitas in iudiciis orationes video eminere virtutibus, et Ciceronis sententiae et contiones non minus clarum, quam est in accusationibus ac defensionibus, eloquentiae lumen ostendunt. Dicit tamen idem de suasoria hoc modo: <em>Tota autem oratio simplex et gravis et sententiis debet ornatior esse quam verbis.<\/em>", "st": "3.8.65"}, {"sp": "N", "t": "Usum exemplorum nulli materiae magis convenire merito fere omnes consentiunt, cum plerumque videantur respondere futura praeteritis, habeaturque experimentum velut quoddam rationis testimonium.", "st": "3.8.66"}, {"sp": "N", "t": "Brevitas quoque aut copia non materiae genere sed modo constat. Nam ut in consiliis plerumque simplicior quaestio est, ita saepe in causis minor. Quae omnia vera esse sciet, si quis non orationes modo, sed historias etiam (namque in iis contiones atque sententiae plerumque suadendi ac dissuadendi funguntur officio), legere maluerit quam in commentariis rhetorum consenescere.", "st": "3.8.67"}, {"sp": "N", "t": "Inveniet enim nec in consiliis abrupta initia et concitatius saepe in iudiciis dictum et verba aptata rebus in utroque genere et breviores aliquando causarum orationes quam sententiarum.", "st": "3.8.68"}, {"sp": "N", "t": "Ne illa quidem in iis vitia deprehendet, quibus quidam declamatores laborant, quod et contra sentientibus inhumane conviciantur et ita plerumque dicunt, tanquam ab iis qui deliberant utique dissentiant, ideoque obiurgantibus similiores sunt quam suadentibus.", "st": "3.8.69"}, {"sp": "N", "t": "Haec adolescentes sibi scripta sciant, ne aliter quam dicturi sunt exerceri velint et in desuescendis morentur. Ceterum, cum advocari coeperint in consilia amicorum, dicere sententiam in senatu, suadere si quid consulet princeps, quod praeceptis fortasse non credunt, usu docebuntur.", "st": "3.8.70"}, {"sp": "N", "t": "Nunc de iudiciali genere, quod est praecipue multiplex, sed officiis constat duobus intentionis ac depulsionis. Cuius partes, ut plurimis auctoribus placuit, quinque sunt: prooemium, narratio, probatio, refutatio, peroratio. His adiecerunt quidam partitionem, propositionem, excessum; quarum priores duae probationi succedunt.", "st": "3.9.1"}, {"sp": "N", "t": "Nam proponere quidem, quae sis probaturus, necesse est, sed et concludere; cur igitur si illa pars causae est, non et haec sit? Partitio vero dispositionis est species, ipsa dispositio pars rhetorices et per omnes materias totumque earum corpus aequaliter fusa, sicut inuentio, elocutio.", "st": "3.9.2"}, {"sp": "N", "t": "Ideoque eam non orationis totius partem unam esse credendum est sed quaestionum etiam singularum. Quae est enim quaestio, in qua non promittere possit orator, quid primo, quid secundo, quid tertio sit loco dicturus? quod est proprium partitionis. Quam ergo ridiculum est, quaestionem quidem speciem esse probationis, partitionem autem, quae sit species quaestionis, partem totius orationis vocari?", "st": "3.9.3"}, {"sp": "N", "t": "Egressio vero vel, quod usitatius esse coepit, excessus, sive est extra causam, non potest esse pars causae, sive est in causa, adiutorium vel ornamentum partium est earum, ex quibus egreditur. Nam si, quidquid in causa est, pars causae vocabitur, cur non argumentum, similitudo, locus communis, adfectus, exempla partes vocentur?", "st": "3.9.4"}, {"sp": "N", "t": "Tamen nec iis adsentior, qui detrahunt refutationem tanquam probationi subiectam, ut Aristoteles; haec enim est, quae constituat, illa, quae destruat. Hoc quoque idem aliquatenus novat, quod prooemio non narrationem subiungit sed propositionem. Verum id facit, quia propositio ei genus, narratio species videtur, et hac non semper, illa semper et ubique credit opus esse.", "st": "3.9.5"}, {"sp": "N", "t": "Verum ex his quas constitui partibus non, ut quidque primum dicendum, ita primum cogitandum est; sed ante omnia intueri oportet, quod sit genus causae, quid in ea quaeratur, quae prosint, quae noceant, deinde quid confirmandum sit ac refellendum, tum quo modo narrandum.", "st": "3.9.6"}, {"sp": "N", "t": "Expositio enim probationum est praeparatio, nec esse utilis potest, nisi prius constiterit, quid debeat de probatione promittere. Postremo intuendum, quemadmodum iudex sit conciliandus. Neque enim nisi totius causae partibus diligenter inspectis scire possumus, qualem nobis facere animum cognoscentis expediat, severum an mitem, concitatum an remissum, adversum gratiae an obnoxium.", "st": "3.9.7"}, {"sp": "N", "t": "Neque ideo tamen eos probaverim, qui scribendum quoque prooemium novissime putant. Nam ut conferri materiam omnem et, quid quoque loco sit opus, constare decet, antequam dicere aut scribere ordiamur, ita incipiendum ab iis, quae prima sunt.", "st": "3.9.8"}, {"sp": "N", "t": "Nam nec pingere quisquam aut fingere coepit a pedibus, nec denique ars ulla consummatur ibi, unde ordiendum est. Quid fiet alioqui, si spatium componendi orationem stilo non fuerit? nonne nos haec inversa consuetudo deceperit? Inspicienda igitur materia est, quo praecepimus ordine, scribenda, quo dicemus.", "st": "3.9.9"}, {"sp": "N", "t": "Ceterum causa omnis, in qua pars altera agentis est, altera recusantis, aut unius rei controversia constat aut plurium. Haec simplex dicitur, illa coniuncta. Una controversia est per se furti, per se adulterii. Plures aut eiusdem generis, ut in pecuniis repetundis, aut diversi, ut si quis sacrilegii et homicidii simul accusetur. Quod nunc in publicis iudiciis non accidit, quoniam praetor certa lege sortitur, principum autem et senatus cognitionibus frequens est et populi fuit; privata quoque iudicia saepe unum iudicem habere multis et diversis formulis solent.", "st": "3.10.1"}, {"sp": "N", "t": "Nec aliae species erunt, etiamsi unus a duobus dumtaxat eandem rem atque ex eadem causa petet aut duo ab uno aut plures a pluribus, quod accidere in hereditariis litibus interim scimus, quia quamvis in multis personis causa tamen una est, nisi si condicio personarum quaestiones variaverit.", "st": "3.10.2"}, {"sp": "N", "t": "Diversum his tertium genus, quod dicitur comparativum; cuius rei tractatus in parte causae frequens est, ut cum apud centumviros post alia quaeritur et hoc, uter dignior hereditate sit. Rarum est autem, ut in foro iudicia propter id solum constituantur, sicut divinationes, quae fiunt de accusatore constituendo, et nonnunquam inter delatores, uter praemium meruerit.", "st": "3.10.3"}, {"sp": "N", "t": "Adiecerunt quidam numero mutuam accusationem, quae ἀντικατηγορία vocatur, allis videlicet succedere hanc quoque comparativo generi existimantibus, cui similis erit petitionum invicem diversarum, quod accidit vel frequentissime. Id si et ipsum vocari debet ἀντικατηγορία (nam proprio caret nomine) duo genera erunt eius, alterum quo litigatores idem crimen invicem intentant, alterum quo aliud atque aliud. Cui et petitionum condicio par est.", "st": "3.10.4"}, {"sp": "N", "t": "Cum apparuerit genus causae, tum intuebimur, negeturne factum, quod intenditur, an defendatur, an alio nomine appelletur, an a genere actionis repellatur; unde sunt status.", "st": "3.10.5"}, {"sp": "N", "t": "His inventis, intuendum deinceps Hermagorae videtur, quid sit quaestio, ratio, iudicatio, continens, vel, ut alii vocant, firmamentum. Quaestio latius intelligitur omnis, de qua in utramque partem vel in plures partes dici credibiliter potest.", "st": "3.11.1"}, {"sp": "N", "t": "In iudiciali autem materia dupliciter accipienda est: altero modo, quo dicimus multas quaestiones habere controversiam, quo etiam minores omnes complectimur, altero, quo significamus summam illam, in qua causa vertitur; de hac nunc loquor, ex qua nascitur status, an factum sit,", "st": "3.11.2"}, {"sp": "N", "t": "quid factum sit, an recte factum sit. Has Hermagoras et Apollodorus et alii plurimi scriptores proprie quaestiones vocant, Theodorus, ut dixi, capita generalia, sicut illas minores aut ex illis pendentes specialia. Nam et quaestionem ex quaestione nasci et speciem in species dividi convenit.", "st": "3.11.3"}, {"sp": "N", "t": "Hanc igitur quaestionem veluti principalem vocant ζήτημα. Ratio autem est, qua id, quod factum esse constat, defenditur. Et cur non utamur eodem, quo sunt usi omnes fere, exemplo? Orestes matrem occidit, hoc constat; dicit se iuste fecisse: status erit qualitatis; quaestio, an iuste fecerit, ratio, quod Clytaemnestra maritum suum, patrem Orestis, occidit; hoc αἴτιον dicitur. κρινόμενον autem iudicatio, an oportuerit vel nocentem matrem a filio occidi.", "st": "3.11.4"}, {"sp": "N", "t": "Quidam diviserunt αἴτιον et αἰτίαν ut esset altera, propter quam iudicium constitutum est, ut occisa Clytaemnestra, altera, qua factum defenditur, ut occisus Agamemnon. Sed tanta est circa verba dissensio, ut alii αἰτίαν causam iudicii, αἴτιον autem facti vocent, alii eadem in contrarium vertant. Latinorum quidam haec initium et rationem vocaverunt, quidam utrumque eodem nomine appellant.", "st": "3.11.5"}, {"sp": "N", "t": "Causa quoque ex causa, id est αἴτιον ἐξ αἰτίου nasci videtur, quale est: Occidit Agamemnonem Clytaemnestra, quia ille filiam communem immolaverat et captivam pellicem adducebat. Iidem putant et sub una quaestione plures esse rationes, ut si Orestes et alteram adferat causam matris necatae, quod responsis sit impulsus; quot autem causas faciendi, totidem iudicationes; nam et haec erit iudicatio, an responsis parere debuerit.", "st": "3.11.6"}, {"sp": "N", "t": "Sed et una causa plures habere quaestiones et iudicationes (ut ego arbitror) potest, ut in eo, qui, cum adulteram deprehensam occidisset, adulterum, qui tum effugerat, postea in foro occidit. Causa enim est una, adulter fuit; quaestiones et iudicationes, an illo tempore, an illo loco licuerit occidere.", "st": "3.11.7"}, {"sp": "N", "t": "Sed sicut, cum sint plures quaestiones omnesque suos status habeant, causae tamen status unus sit, ad quem referuntur omnia, ita iudicatio maxime propria, de qua pronuntiatur.", "st": "3.11.8"}, {"sp": "N", "t": "συνέχον autem (quod, ut dixi, continens alii, firmamentum alii putant, Cicero <em>firmissimam argumentationem defensoris et adpositissimam ad iudicationem<\/em>) quibusdam id videtur esse, post quod nihil quaeritur, quibusdam id quod ad iudicationem firmissimum adfertur.", "st": "3.11.9"}, {"sp": "N", "t": "Causa facti non in omnes controversias cadit. Nam quae fuerit causa faciendi, ubi factum negatur? At ubi causa tractetur, negant eodem loco esse iudicationem quo quaestionem, idque et in Rhetoricis Cicero et in Partitionibus dicit.", "st": "3.11.10"}, {"sp": "N", "t": "Nam in coniectura est quaestio ex illo <em>Factum, non factum<\/em> an factum sit. Ibi ergo iudicatio, ubi quaestio, quia in eadem re prima quaestio et extrema disceptatio. At in qualitate, <em>Matrem Orestes occidit: recte, non recte,<\/em> an recte occiderit, quaestio nec statim iudicatio. Quando ergo? <em>Ilia patrem meum occiderat; sed non ideo tu matrem debuisti occidere;<\/em> an debuerit, hic iudicatio.", "st": "3.11.11"}, {"sp": "N", "t": "Firmamentum autem verbis ipsius ponam: <em>si velit Orestes<\/em> dicere eiusmodi animum matris suae fuisse in patrem <em>suum, in se ipsum ac sorores, in regnum, in famam generis et familiae, ut ab ea poenas liberi potissimum sui petere debuerint.<\/em>", "st": "3.11.12"}, {"sp": "N", "t": "Utuntur alii et talibus exemplis: <em>Qui bona paterna consumpserit, ne contionetur; in opera publica consumpsit;<\/em> quaestio, an, quisquis consumpserit, prohibendus sit: iudicatio, an, qui sic.", "st": "3.11.13"}, {"sp": "N", "t": "Vel, ut in causa militis Arrunti, qui Lusium tribunum vim sibi inferentem interfecit, quaestio, an iure fecerit, ratio, quod is vim afferebat; iudicatio, an indemnatum, an tribunum a milite occidi oportuerit.", "st": "3.11.14"}, {"sp": "N", "t": "Alterius etiam status quaestionem, alterius iudicationem putant. Quaestio qualitatis, an recte Clodium Milo occiderit.", "st": "3.11.15"}, {"sp": "N", "t": "Iudicatio coniecturalis, an Clodius insidias fecerit. Ponunt et illud, saepe causam in aliquam rem dimitti, quae non sit propria quaestionis, et de ea iudicati. A quibus multum dissentio. Nam et illa quaestio, an omnes, qui paterna bona consumpserint, contione sint prohibendi, habeat oportet suam iudicationem. Ergo non alia quaestio alia iudicatio erit, sed plures quaestiones et plures iudicationes.", "st": "3.11.16"}, {"sp": "N", "t": "Quid? non in causa Milonis ipsa coniectura refertur ad qualitatem? nam si est insidiatus Clodius, sequitur, ut recte sit occisus. Cum vero in aliquam rem missa causa recessum est a quaestione, quae erat, et hic constituta quaestio, ubi iudicatio est.", "st": "3.11.17"}, {"sp": "N", "t": "Paulum in his secum etiam Cicero dissentit. Nam in Rhetoricis (quemadmodum supra dixi) Hermagoran est secutus; in Topicis ex statu effectam contentionem κρινόμενον existimat, idque Trebatio, qui iuris erat consultus, adludens <em>qua de re agitur<\/em> appellat; quibus id contineatur, <em>continentia, quasi firmamenta defensionis, quibus sublatis defensio nulla sit;<\/em>", "st": "3.11.18"}, {"sp": "N", "t": "at in Partitionibus oratoriis firmamentum, quod opponitur defensioni, quia continens, quod primum sit, ab accusatore dicatur, ratio a reo, ex rationis et firmamenti quaestione disceptatio sit iudicationum. Verius igitur et brevius ii, qui statum et continens et iudicationem idem esse voluerunt; continens autem id esse, quo sublato lis esse non possit.", "st": "3.11.19"}, {"sp": "N", "t": "Hoc mihi videntur utramque causam complexi, et quod Orestes matrem et quod Clytaemnestra Agamemnonem occiderit. Iidem iudicationem et statum consentire semper existimarunt, neque enim aliud eorum rationi conveniens fuisset.", "st": "3.11.20"}, {"sp": "N", "t": "Verum haec adfectata subtilitas circa nomina rerum ambitiose laborat, a nobis in hoc assumpta solum, ne parum diligenter inquisisse de opere, quod aggressi sumus, videremur; simplicius autem instituenti non est necesse per tam minutas rerum particulas rationem docendi concidere.", "st": "3.11.21"}, {"sp": "N", "t": "Quo vitio multi quidem laborarunt, praecipue tamen Hermagoras, vir alioqui subtilis et in plurimis admirandus, tantum diligentiae nimium sollicitae, ut ipsa eius reprehensio laude aliqua non indigna sit.", "st": "3.11.22"}, {"sp": "N", "t": "Haec autem brevior et vel ideo lucidior multo via neque discentem per ambages fatigabit nec corpus orationis in parva momenta diducendo consumet. Nam qui viderit, quid sit, quod in controversiam veniat, quid in eo et per quae velit efficere pars diversa, quid nostra, quod in primis est intuendum, nihil eorum ignorare, de quibus supra diximus, poterit.", "st": "3.11.23"}, {"sp": "N", "t": "Neque est fere quisquam modo non stultus atque ab omni prorsus usu dicendi remotus, quin sciat, et quid litem faciat, (quod ab illis causa vel continens dicitur) et quae sit inter litigantes quaestio, et de quo iudicari oporteat; quae omnia idem sunt. Nam et de eo quaestio est, quod in controversiam venit, et de eo iudicatur, de quo quaestio est.", "st": "3.11.24"}, {"sp": "N", "t": "Sed non perpetuo intendimus in haec animum et cupiditate laudis utcunque acquirendae vel dicendi voluptate evagamur, quando uberior semper extra causam materia est, quia in controversia pauca sunt, extra omnia, et hic dicitur de his, quae accepimus, illic, de quibus volumus.", "st": "3.11.25"}, {"sp": "N", "t": "Nec tam hoc praecipiendum est, ut quaestionem, continens, iudicationem inveniamus (nam id quidem facile est), quam ut intueamur semper, aut certe si digressi fuerimus saltem respiciamus, ne plausum adfectantibus arma excidant.", "st": "3.11.26"}, {"sp": "N", "t": "Theodori schola, ut dixi, omnia refert ad <em>capita.<\/em> His plura intelliguntur: uno modo summa quaestio item ut status, altero ceterae quae ad summam referuntur, tertio propositio cum adfirmatione; ut dicimus, <em>Caput rei est,<\/em> apud Menandrum κεφάλαιόν ἐστιν. In universum autem, quidquid probandum est, erit caput; sed id maius aut minus. Et quoniam, quae de his erant a scriptoribus artium tradita,", "st": "3.11.27"}, {"sp": "N", "t": "verbosius etiam quam necesse erat exposuimus, praeterea, quae partes essent iudicialium causarum, supra dictum est, proximus liber a prima, id est exordio incipiet.", "st": "3.11.28"}], []);})();
